  5: namespace App\Services\Ai\Pricing;
  6: 
  7: use App\Models\User;
  8: use App\Services\Ai\AgentTool;
  9: use App\Services\Ai\Contracts\ToolProvider;
 10: use App\Services\SettingService;
 11: 
 12: /**
 13:  * Pricing AI domain (P07): price-list, coupon and promotion tools.
 14:  *
 15:  * Disabled by default behind ai_pricing_tools_enabled. Tool classes land
 16:  * per phase under Tools/ and are registered in TOOL_CLASSES below.
 17:  */
 18: final class PricingToolProvider implements ToolProvider
 19: {
 20:     /** @var array<string, AgentTool>|null */
 21:     private ?array $toolsCache = null;
 22: 
 23:     /** @var list<class-string<AgentTool>> */
 24:     private const TOOL_CLASSES = [
 25:         // Phase 1: Read tools
 26:         \App\Services\Ai\Pricing\Tools\ExplainPriceTool::class,
 27:         \App\Services\Ai\Pricing\Tools\QuotePriceTool::class,
 28:         \App\Services\Ai\Pricing\Tools\CompareCustomerPricesTool::class,
 29:         \App\Services\Ai\Pricing\Tools\ListPriceListsTool::class,
 30:         \App\Services\Ai\Pricing\Tools\GetPriceListTool::class,
 31:         \App\Services\Ai\Pricing\Tools\ListCouponsTool::class,
 32:         \App\Services\Ai\Pricing\Tools\GetCouponTool::class,
 33:         \App\Services\Ai\Pricing\Tools\ListPromotionsTool::class,
 34:         \App\Services\Ai\Pricing\Tools\PricingHealthReportTool::class,
 35:         \App\Services\Ai\Pricing\Tools\SimulateCartTool::class,
 36: 
 37:         // Phase 2: Price-list write tools
 38:         \App\Services\Ai\Pricing\Tools\CreatePriceListTool::class,
 39:         \App\Services\Ai\Pricing\Tools\UpdatePriceListTool::class,
 40:         \App\Services\Ai\Pricing\Tools\SetPriceListStatusTool::class,
 41:         \App\Services\Ai\Pricing\Tools\UpsertPriceListItemsTool::class,
 42:         \App\Services\Ai\Pricing\Tools\DeletePriceListItemsTool::class,
 43:         \App\Services\Ai\Pricing\Tools\ClonePriceListTool::class,
 44:         \App\Services\Ai\Pricing\Tools\SchedulePriceChangeTool::class,
 45:         \App\Services\Ai\Pricing\Tools\RefreshCatalogPricesTool::class,
 46: 
 47:         // Phase 4: Vision
 48:         \App\Services\Ai\Pricing\Tools\ParsePriceSheetTool::class,
 49: 
 50:         // Phase 4: Import (CSV → single upsert proposal)
 51:         \App\Services\Ai\Pricing\Tools\ImportPriceListItemsTool::class,
 52:         \App\Services\Ai\Pricing\Tools\ExportPriceListTool::class,
 53: 
 54:         // Phase 3: Coupon & promotion write tools
 55:         \App\Services\Ai\Pricing\Tools\CreateCouponsTool::class,
 56:         \App\Services\Ai\Pricing\Tools\UpdateCouponTool::class,
 57:         \App\Services\Ai\Pricing\Tools\SetCouponStatusTool::class,
 58:         \App\Services\Ai\Pricing\Tools\CreatePromotionTool::class,
 59:         \App\Services\Ai\Pricing\Tools\UpdatePromotionTool::class,
 60:         \App\Services\Ai\Pricing\Tools\SetPromotionStatusTool::class,
 61:         \App\Services\Ai\Pricing\Tools\CouponPerformanceTool::class,
 62:         \App\Services\Ai\Pricing\Tools\WhatIfPriceChangeTool::class,
 63:         \App\Services\Ai\Pricing\Tools\MarginRiskReportTool::class,
 64:         // Phase 1: Read tools (explain_price, quote_price, ...).
 65:         // Phase 2: Price-list write tools (upsert_price_list_items, ...).
 66:         // Phase 3: Coupon & promotion tools (create_coupons, ...).
 67:         // Phase 4: Vision/import tools (parse_price_sheet, ...).
 68:         // Phase 5: What-if & proactive tools (what_if_price_change, ...).
 69:     ];
 70: 
 71:     public function __construct(private SettingService $settings) {}
 72: 
 73:     /** @return array<string, AgentTool> */
 74:     public function tools(): array
 75:     {
 76:         if ($this->toolsCache !== null) {
 77:             return $this->toolsCache;
 78:         }
 79:         $tools = [];
 80:         foreach (self::TOOL_CLASSES as $class) {
 81:             if (class_exists($class)) {
 82:                 /** @var AgentTool $tool */
 83:                 $tool = app($class);
 84:                 $tools[$tool->name()] = $tool;
 85:             }
 86:         }
 87: 
 88:         return $this->toolsCache = $tools;
 89:     }
 90: 
 91:     public function enabled(): bool
 92:     {
 93:         return $this->settings->getBool('ai_pricing_tools_enabled', false);
 94:     }
 95: 
 96:     public function isToolHidden(string $name): bool
 97:     {
 98:         return match ($name) {
 99:             'parse_price_sheet' => ! $this->settings->getBool('ai_pricing_vision_enabled', false),
100:             'list_coupons', 'get_coupon', 'create_coupons', 'update_coupon', 'set_coupon_status',
101:             'list_promotions', 'create_promotion', 'update_promotion', 'set_promotion_status',
102:             'coupon_performance', 'simulate_cart', 'margin_risk_report' => ! $this->settings->getBool('ai_promotions_tools_enabled', false),
103:             default => false,
104:         };
105:     }
106: 
107:     public function domain(): string
108:     {
109:         return 'pricing';
110:     }
111: 
112:     public function usesGlobalAdminLock(): bool
113:     {
114:         return false;
115:     }
116: 
117:     public function canReadEntity(User $actor, string $type): ?bool
118:     {
119:         if (! in_array($type, ['price_list', 'coupon', 'promotion'], true)) {
120:             return null;
121:         }
122:         if (! $this->enabled()) {
123:             return false;
124:         }
125: 
126:         return match ($type) {
127:             'price_list' => $actor->can('price_lists.view'),
128:             'coupon' => ! $this->isToolHidden('get_coupon') && $actor->can('coupons.view'),
129:             'promotion' => ! $this->isToolHidden('list_promotions') && $actor->can('promotions.view'),
130:             default => false,
131:         };
132:     }
133: 
134:     public function systemPromptSection(User $actor): ?string
135:     {
136:         if (! $this->enabled()) {
137:             return null;
138:         }
139:         if (! $actor->can('price_lists.view') && ! $actor->can('coupons.view')) {
140:             return null;
141:         }
142: 
143:         return implode("\n", [
144:             'دومين التسعير:',
145:             '— ترتيب السعر: قائمة العميل الخاصة ← قائمة المجموعة ← قائمة القناة (جملة/موزع/قطاعي) ← السعر الأساسي للمتغير.',
146:             '— خصم المجموعة بيتطبق على سعر القناة أو الأساسي بس، مش على قوائم العميل أو المجموعة.',
147:             '— عميل الجملة أو الموزع اللي مش معتمد بيتسعّر قطاعي.',
148:             '— لأي سؤال "ليه السعر كده" استخدم explain_price. ماتحسبش أسعار بنفسك أبدًا.',
149:             '— العروض (promotions) بتتسجل بس ومش بتتطبق تلقائيًا على السلة حاليًا. قول كده بوضوح.',
150:             '— الكوبون في الحساب بيخصم من البضاعة. كوبون free_shipping خصمه على الشحن مش البضاعة.',
151:             '— التواريخ النسبية ("من أول الشهر"، "لحد الخميس") تتحسب بتوقيت القاهرة.',
152:             '— ماتعرضش سعر تكلفة إلا لو الأداة رجّعته.',
153:         ]);
154:     }
155: } 1: <?php
