18:     /** @param array<string,mixed> $via */
19:     public function __invoke(User $actor, Location $location, bool $active, array $via = []): Location
20:     {
21:         return DB::transaction(function () use ($actor, $location, $active, $via): Location {
22:             StaffAdministration::lock();
23:             StaffAdministration::authorize($actor, ['locations.update', 'locations.manage']);
24:             $locked = Location::query()->lockForUpdate()->findOrFail($location->id);
25:             $this->access->assertBranch($actor->id, $locked->branch_id);
26:             $before = ['is_active' => (bool) $locked->is_active];
27:             if (! $active && ! (bool) $locked->is_active) {
28:                 return $locked;
29:             }
30:             if ($active && ! (bool) \App\Models\Branch::query()->find($locked->branch_id)?->is_active) {
31:                 abort(422, 'لا يمكن تفعيل موقع داخل فرع متوقف.');
