30:             StaffAdministration::lock();
31:             StaffAdministration::authorize($actor, ['roles.create', 'roles.manage']);
32:             $this->access->assertCentralAccess($actor);
33:             abort_unless(StaffAdministration::mayGrantPermissions($actor, $permissions), 403);
34:             StaffAdministration::clearPermissionCacheAfterCommit();
35:             try {
36:                 $role = Role::create(['name' => $data['name'], 'guard_name' => 'staff']);
37:             } catch (\Spatie\Permission\Exceptions\RoleAlreadyExists|\Illuminate\Database\UniqueConstraintViolationException $e) {
38:                 throw \Illuminate\Validation\ValidationException::withMessages([
39:                     'name' => 'اسم الدور مستخدم بالفعل؛ أعد التحميل ثم حاول مرة أخرى.',
40:                 ]);
41:             }
42:             $role->syncPermissions($permissions);
43:             StaffAdministration::audit($actor, 'role.created', 'role', $role->id, array_keys($data), [], StaffAdministration::roleState($role), $via);
44: 
45:             return $role;
46:         });
