 5: namespace App\Http\Controllers\Api\V1\Webhook;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Services\PaymentWebhookService;
 9: use Illuminate\Http\JsonResponse;
10: use Illuminate\Http\Request;
11: 
12: /**
13:  * ويب هوك بوابات الدفع — بلا مصادقة Sanctum؛ الحماية بنمط توقيع
14:  * كل بوابة (driver) وبالتسجيل في webhook_logs (Idempotency).
15:  */
16: class PaymentWebhookController extends Controller
17: {
18:     public function __construct(private readonly PaymentWebhookService $webhooks) {}
19: 
20:     public function handle(Request $request, string $gateway): JsonResponse
21:     {
22:         $raw = $request->getContent();
23: 
24:         // حد الحجم قبل أي فك ترميز: حمولة ضخمة لا تُفكَّك (F9). الرفض
25:         // والتسجيل المختصر يتمّان في الخدمة (وقتها لا تُخزَّن الحمولة)
26:         $payload = strlen($raw) > 262144 ? null : json_decode($raw, true);
27:         // الهيدرات بمفاتيح صغيرة + الـ query: أنماط Paymob (hmac في query)
28:         // وStripe (هيدر موقّع) تحتاج أكثر من هيدر واحد (F-06)
29:         $headers = collect($request->headers->all())
30:             ->map(fn (array $values): ?string => $values[0] ?? null)
31:             ->all();
32:         $result = $this->webhooks->handle(
33:             $gateway,
34:             is_array($payload) ? $payload : [],
35:             $raw,
36:             $headers,
37:             $request->query(),
38:             $request->ip(),
39:         );
40: 
41:         return response()->json($result['body'], $result['http']);
42:     }
43: } 1: <?php
