 18: final class CatalogToolProvider implements ToolProvider
 19: {
 20:     /** @var array<string, AgentTool>|null */
 21:     private ?array $toolsCache = null;
 22: 
 23:     /** @var list<class-string<AgentTool>> */
 24:     private const TOOL_CLASSES = [
 25:         // Phase 1: Read tools
 26:         \App\Services\Ai\Catalog\Tools\ListCategoriesTool::class,
 27:         \App\Services\Ai\Catalog\Tools\GetCategoryTool::class,
 28:         \App\Services\Ai\Catalog\Tools\SearchProductsTool::class,
 29:         \App\Services\Ai\Catalog\Tools\GetProductTool::class,
 30:         \App\Services\Ai\Catalog\Tools\LookupCodeTool::class,
 31:         \App\Services\Ai\Catalog\Tools\CheckPublishabilityTool::class,
 32:         \App\Services\Ai\Catalog\Tools\CatalogHealthReportTool::class,
 33: 
 34:         // Phase 2: Category write tools
 35:         \App\Services\Ai\Catalog\Tools\CreateCategoryTool::class,
 36:         \App\Services\Ai\Catalog\Tools\UpdateCategoryTool::class,
 37:         \App\Services\Ai\Catalog\Tools\MoveCategoryTool::class,
 38:         \App\Services\Ai\Catalog\Tools\ReorderCategoriesTool::class,
 39:         \App\Services\Ai\Catalog\Tools\SetCategoryStatusTool::class,
 40:         \App\Services\Ai\Catalog\Tools\DeleteCategoryTool::class,
 41: 
 42:         // Phase 3: Product & Variant write tools
 43:         \App\Services\Ai\Catalog\Tools\CreateProductDraftTool::class,
 44:         \App\Services\Ai\Catalog\Tools\UpdateProductTool::class,
 45:         \App\Services\Ai\Catalog\Tools\SetProductStatusTool::class,
 46:         \App\Services\Ai\Catalog\Tools\DeleteProductTool::class,
 47:         \App\Services\Ai\Catalog\Tools\AddVariantsTool::class,
 48:         \App\Services\Ai\Catalog\Tools\UpdateVariantTool::class,
 49:         \App\Services\Ai\Catalog\Tools\SetVariantStatusTool::class,
 50:         \App\Services\Ai\Catalog\Tools\DeleteVariantTool::class,
 51:         \App\Services\Ai\Catalog\Tools\BulkUpdatePricesTool::class,
 52: 
 53:         // Phase 4: Media & Vision tools
 54:         \App\Services\Ai\Catalog\Tools\AttachProductImagesTool::class,
 55:         \App\Services\Ai\Catalog\Tools\ListProductMediaTool::class,
 56:         \App\Services\Ai\Catalog\Tools\ReorderProductMediaTool::class,
 57:         \App\Services\Ai\Catalog\Tools\DeleteProductMediaTool::class,
 58:         \App\Services\Ai\Catalog\Tools\AnalyzeProductPhotosTool::class,
 59: 
 60:         // Phase 5: Copywriting & Fixes
 61:         \App\Services\Ai\Catalog\Tools\DraftProductCopyTool::class,
 62:         \App\Services\Ai\Catalog\Tools\PlanCatalogFixesTool::class,
 63:     ];
 64: 
 65:     public function __construct(private SettingService $settings) {}
 66: 
 67:     /** @return array<string, AgentTool> */
 68:     public function tools(): array
 69:     {
 70:         if ($this->toolsCache !== null) {
 71:             return $this->toolsCache;
 72:         }
 73:         $tools = [];
 74:         foreach (self::TOOL_CLASSES as $class) {
 75:             if (class_exists($class)) {
 76:                 /** @var AgentTool $tool */
 77:                 $tool = app($class);
 78:                 $tools[$tool->name()] = $tool;
 79:             }
 80:         }
 81: 
 82:         return $this->toolsCache = $tools;
 83:     }
 84: 
 85:     public function enabled(): bool
 86:     {
 87:         return $this->settings->getBool('ai_catalog_tools_enabled', false);
 88:     }
 89: 
 90:     public function domain(): string
 91:     {
 92:         return 'catalog';
 93:     }
 94: 
 95:     public function usesGlobalAdminLock(): bool
 96:     {
 97:         return false;
 98:     }
 99: 
100:     public function isToolHidden(string $name): bool
101:     {
102:         if (! $this->enabled()) {
