 18: final class ProposalBuilder
 19: {
 20:     private ?AiConversation $conversation = null;
 21: 
 22:     public function __construct(private SettingService $settings) {}
 23: 
 24:     public function setConversation(?AiConversation $conversation): void
 25:     {
 26:         $this->conversation = $conversation;
 27:     }
 28: 
 29:     public function conversation(): ?AiConversation
 30:     {
 31:         return $this->conversation;
 32:     }
 33: 
 34:     public function hashArgs(array $args): string
 35:     {
 36:         $c = $this->canonical($args);
 37: 
 38:         return hash_hmac('sha256', json_encode($c, JSON_THROW_ON_ERROR), (string) config('app.key'));
 39:     }
 40: 
 41:     public function canonical(mixed $v): mixed
 42:     {
 43:         if (is_array($v)) {
 44:             $isList = array_is_list($v);
 45:             $out = array_map(fn ($x) => $this->canonical($x), $v);
 46:             if (! $isList) {
 47:                 ksort($out);
 48:             }
 49: 
 50:             return $out;
 51:         }
 52: 
 53:         return $v;
 54:     }
 55: 
 56:     /**
 57:      * @param  array<string,mixed>  $args
 58:      * @param  array<string,mixed>  $expectedVersions
 59:      * @param  list<string>  $warnings
 60:      * @param  array<string,mixed>|null  $inverse
 61:      * @param  array<string,mixed>  $extraPreview
 62:      */
 63:     public function make(
 64:         User $actor,
 65:         string $tool,
 66:         array $args,
 67:         string $risk = 'medium',
 68:         string $title = '',
 69:         mixed $before = null,
 70:         mixed $after = null,
 71:         array $warnings = [],
 72:         array $expectedVersions = [],
 73:         ?array $inverse = null,
 74:         ?string $typedConfirmation = null,
 75:         ?string $typedConfirmationHint = null,
 76:         array $extraPreview = [],
 77:         ?AiConversation $conv = null,
 78:     ): ToolOutcome {
 79:         $conversation = $conv ?? $this->conversation;
 80:         if (! $conversation) {
 81:             throw new \LogicException('ProposalBuilder requires an active AiConversation.');
 82:         }
 83: 
 84:         $preview = array_merge([
 85:             'title' => $title !== '' ? $title : $tool,
 86:             'before' => $before,
 87:             'after' => $after,
 88:             'warnings' => $warnings,
 89:         ], $extraPreview);
 90: 
 91:         if ($typedConfirmation !== null) {
 92:             $preview['typed_confirmation'] = $typedConfirmation;
 93:         }
 94:         if ($typedConfirmationHint !== null) {
 95:             $preview['typed_confirmation_hint'] = $typedConfirmationHint;
 96:         }
 97: 
 98:         return $this->makeProposal($actor, $conversation, $tool, $args, $expectedVersions, $preview, $inverse, $risk);
 99:     }
100: 
101:     public function makeProposal(
102:         User $actor,
103:         AiConversation $conv,
104:         string $tool,
105:         array $args,
106:         array $expected,
107:         array $preview,
108:         ?array $inverse,
109:         string $risk,
110:     ): ToolOutcome {
111:         if (in_array($tool, ['create_staff_user', 'assign_roles', 'set_user_status'], true)) {
112:             $names = array_merge($args['roles'] ?? [], $tool === 'assign_roles' ? ($args['add'] ?? []) : []);
113:             if (isset($args['user_id'])) {
114:                 $names = array_merge($names, User::findOrFail($args['user_id'])->roles()->pluck('name')->all());
115:             }
116:             foreach (Role::where('guard_name', 'staff')->whereIn('name', $names)->get() as $role) {
117:                 $expected['role:'.$role->id] = (int) $role->lock_version;
118:             }
119:         }
120:         $ttl = max(1, (int) $this->settings->get('ai_action_ttl_minutes', 10));
121:         $action = AiPendingAction::create([
122:             'conversation_id' => $conv->id,
123:             'user_id' => $actor->id,
124:             'tool' => $tool,
125:             'args' => $args,
126:             'expected_versions' => $expected,
127:             'preview' => $preview,
128:             'inverse' => $inverse,
129:             'args_hash' => $this->hashArgs($args),
130:             'risk' => $risk,
131:             'status' => 'pending',
132:             'expires_at' => now()->addMinutes($ttl),
133:         ]);
134: 
135:         [$typed, $typedHint] = self::resolveTypedConfirmation($tool, $args, $preview);
136: 
137:         $blockType = $preview['block_type'] ?? 'confirm_action';
138:         $block = [
139:             'type' => $blockType,
140:             'action_id' => $action->id,
141:             'tool' => $tool,
142:             'risk' => $risk,
143:             'title' => $preview['title'] ?? $tool,
144:             'before' => $preview['before'] ?? null,
145:             'after' => $preview['after'] ?? null,
146:             'warnings' => $preview['warnings'] ?? [],
147:             'expires_at' => $action->expires_at->toIso8601String(),
148:         ];
149: 
150:         foreach (['moved_id', 'rows', 'summary', 'top', 'blocked', 'stages', 'items', 'deep_link', 'stocktake_id', 'stocktake_number', 'recent_movements'] as $extraKey) {
151:             if (array_key_exists($extraKey, $preview)) {
152:                 $block[$extraKey] = $preview[$extraKey];
153:             }
154:         }
155: 
156:         if ($risk === 'high' && $typed) {
157:             $block['typed_confirmation'] = $typed;
158:             if ($typedHint) {
159:                 $block['typed_confirmation_hint'] = $typedHint;
160:             }
161:         }
162:         if (isset($preview['permission_diff'])) {
163:             $block = array_merge($block, ['type' => 'permission_diff'] + $block + $preview['permission_diff']);
164:         }
165: 
166:         return ToolOutcome::proposal($block, ['pending_action_id' => $action->id]);
167:     }
168: 
169:     /**
170:      * @param  array<string,mixed>  $args
171:      * @param  array<string,mixed>  $preview
172:      * @return array{0: ?string, 1: ?string}
173:      */
174:     public static function resolveTypedConfirmation(string $tool, array $args, array $preview = []): array
175:     {
176:         if (isset($preview['typed_confirmation']) && is_string($preview['typed_confirmation']) && $preview['typed_confirmation'] !== '') {
177:             return [$preview['typed_confirmation'], $preview['typed_confirmation_hint'] ?? null];
178:         }
179: 
180:         $typed = null;
181:         $typedHint = null;
182: 
183:         if ($tool === 'set_branch_status' && isset($args['branch_id'])) {
184:             $b = Branch::find($args['branch_id']);
185:             $typed = $b?->code;
186:         } elseif ($tool === 'delete_role' && isset($args['role_id'])) {
187:             $r = Role::find($args['role_id']);
188:             $typed = $r?->name;
189:         } elseif (in_array($tool, ['approve_dealer_application', 'reject_dealer_application', 'suspend_customer', 'set_credit_limit'], true) && isset($args['customer_id'])) {
190:             $phone = Customer::withTrashed()->find($args['customer_id'])?->phone;
191:             $typed = $phone ? substr((string) $phone, -4) : null;
192:             $typedHint = 'آخر 4 أرقام من موبايل التاجر';
193:         } elseif ($tool === 'adjust_customer_wallet' && isset($args['customer_id'])) {
194:             $phone = Customer::withTrashed()->find($args['customer_id'])?->phone;
195:             $typed = $phone ? substr((string) $phone, -4) : null;
196:             $typedHint = 'آخر 4 أرقام من موبايل العميل';
197:         } elseif (in_array($tool, ['set_category_status', 'delete_category'], true) && isset($args['category_id'])) {
198:             $cat = Category::withTrashed()->find($args['category_id']);
199:             $typed = $cat?->slug;
200:         } elseif (in_array($tool, ['set_product_status', 'delete_product'], true) && isset($args['product_id'])) {
201:             $prod = Product::withTrashed()->find($args['product_id']);
202:             $typed = $prod?->code;
203:         } elseif ($tool === 'delete_variant' && isset($args['variant_id'])) {
204:             $var = ProductVariant::withTrashed()->find($args['variant_id']);
205:             $typed = $var?->sku;
206:         } elseif ($tool === 'bulk_update_prices') {
207:             $typed = 'تنفيذ';
208:         }
209: 
210:         return [$typed, $typedHint];
211:     }
