  5: namespace App\Services;
  6: 
  7: /**
  8:  * Cryptographic webhook signature validator supporting multiple gateway drivers:
  9:  * - hmac (default): HMAC-SHA256 over raw request body against designated header.
 10:  * - stripe: Stripe-Signature header format (t=...,v1=...) with 300s replay prevention.
 11:  * - paymob: HMAC-SHA512 over official concatenated transaction dictionary fields.
 12:  * - moyasar: Constant-time comparison of secret_token within payload.
 13:  * All signature checks utilize timing-attack safe hash_equals.
 14:  */
 15: class WebhookSignatureVerifier
 16: {
 17:     /**
 18:      * Verify standard HMAC-SHA256 signature against raw request body.
 19:      *
 20:      * @param  string|null  $secret
 21:      * @param  string  $rawBody
 22:      * @param  string|null  $signature
 23:      * @return bool
 24:      */
 25:     public function verify(?string $secret, string $rawBody, ?string $signature): bool
 26:     {
 27:         if ($secret === null || $secret === '' || $signature === null || $signature === '') {
 28:             return false;
 29:         }
 30: 
 31:         if (str_starts_with($signature, 'sha256=')) {
 32:             $signature = substr($signature, 7);
 33:         }
 34: 
 35:         $expected = hash_hmac('sha256', $rawBody, $secret);
 36: 
 37:         return hash_equals($expected, strtolower(trim($signature)));
 38:     }
 39: 
 40:     /**
 41:      * Dispatch signature validation to gateway-specific verifier.
 42:      *
 43:      * @param  string  $driver
 44:      * @param  string|null  $secret
 45:      * @param  string  $rawBody
 46:      * @param  array<string, string|null>  $headers  Lowercase header map
 47:      * @param  array<string, mixed>  $query
 48:      * @param  array<string, mixed>  $payload
 49:      * @param  string|null  $signatureHeader
 50:      * @return bool
 51:      */
 52:     public function verifyGateway(string $driver, ?string $secret, string $rawBody, array $headers, array $query, array $payload, ?string $signatureHeader = null): bool
 53:     {
 54:         return match ($driver) {
 55:             'stripe' => $this->verifyStripe($secret, $rawBody, $headers),
 56:             'paymob' => $this->verifyPaymob($secret, $query, $payload),
 57:             'moyasar' => $this->verifyMoyasar($secret, $payload),
 58:             default => $this->verify(
 59:                 $secret,
 60:                 $rawBody,
 61:                 $headers[strtolower($signatureHeader ?? 'X-Webhook-Signature')] ?? null,
 62:             ),
 63:         };
 64:     }
 65: 
 66:     /** @param array<string, string|null> $headers */
 67:     private function verifyStripe(?string $secret, string $rawBody, array $headers): bool
 68:     {
 69:         $header = $headers['stripe-signature'] ?? null;
 70:         if ($secret === null || $secret === '' || $header === null || $header === '') {
 71:             return false;
 72:         }
 73: 
 74:         $timestamp = null;
 75:         $signatures = [];
 76:         foreach (explode(',', $header) as $part) {
 77:             $pair = explode('=', trim($part), 2);
 78:             if (count($pair) !== 2) {
 79:                 continue;
 80:             }
 81:             if ($pair[0] === 't') {
 82:                 $timestamp = $pair[1];
 83:             } elseif ($pair[0] === 'v1') {
 84:                 $signatures[] = $pair[1];
 85:             }
 86:         }
 87:         if ($timestamp === null || $signatures === [] || ! ctype_digit($timestamp)) {
 88:             return false;
 89:         }
 90:         // Reject events older than 5 minutes to prevent replay attacks
 91:         if (abs(time() - (int) $timestamp) > 300) {
 92:             return false;
 93:         }
 94: 
 95:         $expected = hash_hmac('sha256', $timestamp.'.'.$rawBody, $secret);
 96:         foreach ($signatures as $signature) {
 97:             if (hash_equals($expected, strtolower(trim($signature)))) {
 98:                 return true;
 99:             }
100:         }
101: 
102:         return false;
103:     }
104: 
105:     /**
106:      * @param  array<string, mixed>  $query
107:      * @param  array<string, mixed>  $payload
108:      */
109:     private function verifyPaymob(?string $secret, array $query, array $payload): bool
110:     {
111:         $hmac = $query['hmac'] ?? null;
112:         if ($secret === null || $secret === '' || ! is_string($hmac) || $hmac === '') {
113:             return false;
114:         }
115: 
116:         $tx = isset($payload['obj']) && is_array($payload['obj']) ? $payload['obj'] : $payload;
117:         // Official Paymob callback field order for HMAC-SHA512 calculation
118:         $fields = [
119:             'amount_cents', 'created_at', 'currency', 'error_occured',
120:             'has_parent_transaction', 'id', 'integration_id', 'is_3d_secure',
121:             'is_auth', 'is_capture', 'is_refunded', 'is_standalone_payment',
122:             'is_voided', 'order.id', 'owner', 'pending',
123:             'source_data.pan', 'source_data.sub_type', 'source_data.type', 'success',
124:         ];
125:         $concatenated = '';
126:         foreach ($fields as $field) {
127:             $value = data_get($tx, $field);
128:             if (is_bool($value)) {
129:                 $concatenated .= $value ? 'true' : 'false';
130:             } elseif (is_scalar($value)) {
131:                 $concatenated .= (string) $value;
132:             }
133:         }
134: 
135:         $expected = hash_hmac('sha512', $concatenated, $secret);
136: 
137:         return hash_equals($expected, strtolower(trim($hmac)));
138:     }
139: 
140:     /** @param array<string, mixed> $payload */
141:     private function verifyMoyasar(?string $secret, array $payload): bool
142:     {
143:         $token = $payload['secret_token'] ?? null;
144:         if ($secret === null || $secret === '' || ! is_string($token) || $token === '') {
145:             return false;
146:         }
147: 
148:         return hash_equals($secret, $token);
149:     }
