 63:     public function __construct(private ToolRegistry $registry) {}
 64: 
 65:     /**
 66:      * @param  list<array<string,mixed>>  $mentions
 67:      * @param  array<string,mixed>|null  $selection
 68:      * @param  list<string>  $attachments
 69:      * @return list<string>|null
 70:      */
 71:     public function route(
 72:         string $text,
 73:         array $mentions = [],
 74:         ?array $selection = null,
 75:         ?AiConversation $conversation = null,
 76:         array $attachments = [],
 77:     ): ?array {
 78:         $domains = [];
 79: 
 80:         if ($attachments !== []) {
 81:             $domains['catalog'] = true;
 82:         }
 83: 
 84:         $refs = $mentions;
 85:         if ($selection !== null) {
 86:             $refs[] = $selection;
 87:         }
 88:         foreach ($refs as $ref) {
 89:             $entity = (string) ($ref['entity'] ?? '');
 90:             $mapped = match ($entity) {
 91:                 'category', 'product', 'variant' => 'catalog',
 92:                 'customer', 'customer_group' => 'customers',
 93:                 'branch', 'user', 'role', 'permission', 'location' => 'admin',
 94:                 'transfer', 'stocktake', 'production_receipt' => 'inventory',
 95:                 'price_list', 'coupon', 'promotion' => 'pricing',
 96:                 'treasury', 'treasury_transfer', 'expense' => 'finance',
 97:                 default => null,
 98:             };
 99:             if ($mapped !== null) {
100:                 $domains[$mapped] = true;
101:             }
102:         }
103: 
104:         $norm = EntityResolver::normalizeForSearch(EntityResolver::normalizeDigits($text));
105:         $lower = mb_strtolower($text);
106: 
107:         foreach (self::KEYWORDS as $domain => $words) {
108:             foreach ($words as $word) {
109:                 $normWord = EntityResolver::normalizeForSearch($word);
110:                 if ($normWord === '') {
111:                     continue;
112:                 }
113:                 // Short keywords ('عد' count vs 'تعديل' modify, 'رف' shelf vs
114:                 // 'ارفض' reject) must match whole words, or every sentence
115:                 // containing them misroutes.
116:                 if (mb_strlen($normWord) <= 2) {
117:                     $matched = (bool) preg_match('/(^|\s)'.preg_quote($normWord, '/').'(\s|$)/u', $norm);
118:                 } else {
119:                     $matched = str_contains($norm, $normWord) || str_contains($lower, mb_strtolower($word));
120:                 }
121:                 if ($matched) {
122:                     $domains[$domain] = true;
123:                     break;
124:                 }
125:             }
126:         }
127: 
128:         $domains = array_fill_keys($this->disambiguate($norm, array_keys($domains), $refs), true);
129: 
130:         if ($conversation !== null) {
131:             $lastToolName = $this->lastToolInConversation($conversation);
132:             if ($lastToolName !== null) {
133:                 $lastDomain = $this->toolDomain($lastToolName);
134:                 if ($lastDomain !== null) {
135:                     $domains[$lastDomain] = true;
136:                 }
137:             }
138:         }
139: 
140:         if ($domains === []) {
141:             return null;
142:         }
143: 
144:         return array_keys($domains);
145:     }
146: 
147:     /**
148:      * تمييز محفظة المنتج من محفظة العميل، وتحويل البضاعة من تحويل الفلوس،
149:      * ورصيد الصنف من رصيد الخزنة — بعد مطابقة الكلمات وقبل إرجاع الدومينات.
150:      *
151:      * @param  list<string>  $domains
152:      * @param  list<array<string,mixed>>  $refs
153:      * @return list<string>
154:      */
155:     private function disambiguate(string $norm, array $domains, array $refs): array
156:     {
157:         if ($domains === []) {
158:             return $domains;
159:         }
160:         $has = fn (string $word): bool => str_contains($norm, EntityResolver::normalizeForSearch($word));
161:         $hasAny = function (array $words) use ($has): bool {
162:             foreach ($words as $word) {
163:                 if ($has($word)) {
164:                     return true;
165:                 }
166:             }
167: 
168:             return false;
169:         };
170:         $mentionsCustomer = false;
171:         foreach ($refs as $ref) {
172:             if (in_array((string) ($ref['entity'] ?? ''), ['customer', 'customer_group'], true)) {
173:                 $mentionsCustomer = true;
174:                 break;
175:             }
176:         }
177:         $transferWord = $has('تحويل') || $has('حول');
178: 
179:         $drop = function (array $names) use (&$domains): void {
180:             $domains = array_values(array_diff($domains, $names));
181:         };
182:         $keep = function (string $name) use (&$domains): void {
183:             if (! in_array($name, $domains, true)) {
184:                 $domains[] = $name;
185:             }
186:         };
187: 
188:         if ($has('محفظة')) {
189:             $walletFinance = $hasAny(['عميل', 'رصيد', 'شحن', 'استرداد', 'جنيه', 'مبلغ']) || $mentionsCustomer;
190:             if ($walletFinance) {
191:                 $keep('finance');
192:                 $otherCatalog = false;
193:                 foreach (self::KEYWORDS['catalog'] ?? [] as $word) {
194:                     if (in_array($word, ['محفظة', 'محفظه'], true)) {
195:                         continue;
196:                     }
197:                     $normWord = EntityResolver::normalizeForSearch($word);
198:                     if ($normWord !== '' && str_contains($norm, $normWord)) {
199:                         $otherCatalog = true;
200:                         break;
201:                     }
202:                 }
203:                 if (! $otherCatalog) {
204:                     $drop(['catalog']);
205:                 }
206:                 $otherInventory = false;
207:                 foreach (self::KEYWORDS['inventory'] ?? [] as $word) {
208:                     if (in_array($word, ['شحن', 'مشحون'], true)) {
209:                         continue;
210:                     }
211:                     $normWord = EntityResolver::normalizeForSearch($word);
212:                     if ($normWord !== '' && str_contains($norm, $normWord)) {
213:                         $otherInventory = true;
214:                         break;
215:                     }
216:                 }
217:                 if (! $otherInventory) {
218:                     $drop(['inventory']);
219:                 }
220:             } else {
221:                 $drop(['finance']);
222:             }
223:         }
224: 
225:         if ($transferWord) {
226:             $moneyCtx = $hasAny(['خزنة', 'خزينة', 'درج', 'فلوس', 'نقدية', 'كاش', 'بنك', 'مبلغ', 'اعتماد', 'اعتمد', 'يعتمد', 'معلقة', 'معلق']);
227:             $goodsCtx = $hasAny(['بضاعة', 'قطعة', 'صنف', 'كرتونة', 'شنطة', 'منتج', 'مخزن']);
228:             if ($moneyCtx && ! $goodsCtx) {
229:                 $keep('finance');
230:                 $drop(['inventory', 'catalog']);
231:             } elseif ($goodsCtx && ! $moneyCtx) {
232:                 $drop(['finance', 'catalog']);
233:             }
234:         }
235: 
236:         if ($has('رصيد')) {
237:             $financeCtx = $hasAny(['خزنة', 'خزينة', 'درج', 'بنك', 'محفظة']);
238:             $inventoryCtx = $hasAny(['صنف', 'مخزن', 'قطعة']);
239:             if ($financeCtx && ! $inventoryCtx) {
240:                 $keep('finance');
241:                 $drop(['inventory']);
242:             } elseif ($inventoryCtx && ! $financeCtx) {
243:                 $drop(['finance']);
244:             }
245:         }
246: 
247:         if ($hasAny(['وردية', 'ورديات']) && ! $hasAny(['مخزن', 'صنف', 'جرد', 'بضاعة'])) {
248:             $keep('finance');
249:             $drop(['inventory']);
250:         }
251: 
252:         if ($has('مصروف') && ! $hasAny(['مخزن', 'صنف', 'منتج', 'بضاعة', 'جرد'])) {
253:             $keep('finance');
254:             $drop(['inventory']);
255:         }
256: 
257:         if ($hasAny(['حركة', 'حركات']) && $hasAny(['خزنة', 'خزينة', 'درج', 'بنك', 'محفظة']) && ! $hasAny(['مخزن', 'صنف', 'بضاعة'])) {
258:             $drop(['inventory']);
259:         }
260: 
261:         if (($has('عجز') || $has('زيادة')) && ($has('درج') || $has('وردية'))) {
262:             $keep('finance');
263:             $drop(['inventory']);
264:         }
265: 
266:         return array_values($domains);
267:     }
