269:     private function lastToolInConversation(AiConversation $conversation): ?string
270:     {
271:         $lastModelWithCall = AiMessage::query()
272:             ->where('conversation_id', $conversation->id)
273:             ->where('role', 'model')
274:             ->whereNotNull('provider_parts')
275:             ->orderByDesc('id')
276:             ->limit(5)
277:             ->get(['provider_parts']);
278: 
279:         foreach ($lastModelWithCall as $msg) {
280:             foreach ((array) $msg->provider_parts as $part) {
281:                 if (is_array($part) && isset($part['functionCall']['name']) && is_string($part['functionCall']['name'])) {
282:                     return $part['functionCall']['name'];
283:                 }
284:             }
285:         }
286: 
287:         return null;
288:     }
