290:     private function toolDomain(string $toolName): ?string
291:     {
292:         if (in_array($toolName, ['find_entities', 'ask_user_to_choose', 'bulk_actions'], true)) {
293:             return null;
294:         }
295:         $def = $this->registry->definitions()[$toolName] ?? null;
296:         if (! $def) {
297:             return null;
298:         }
299:         if (isset($def['provider']) && $def['provider'] instanceof \App\Services\Ai\Contracts\ToolProvider) {
300:             return $def['provider']->domain();
301:         }
302:         if ($this->registry->isCustomerTool($toolName)) {
303:             return 'customers';
304:         }
305:         if (in_array($toolName, ['view_settings', 'view_document_numbering', 'update_settings', 'update_document_numbering'], true)) {
306:             return 'settings';
307:         }
308: 
309:         return 'admin';
310:     }
