 5: namespace App\Actions\Branches;
 6: 
 7: use App\Enums\PosShiftStatus;
 8: use App\Enums\TransferStatus;
 9: use App\Exceptions\BusinessException;
10: use App\Models\Branch;
11: use App\Models\PosShift;
12: use App\Models\StockLevel;
13: use App\Models\StockTransfer;
14: use App\Models\Treasury;
15: use App\Models\User;
16: use App\Services\BranchAccess;
17: use App\Services\StaffAdministration;
18: use Illuminate\Support\Facades\DB;
19: 
20: final class UpdateBranch
21: {
22:     public function __construct(private BranchAccess $access) {}
23: 
24:     /** @param array<string,mixed> $data @param array<string,mixed> $via */
25:     public function __invoke(User $actor, Branch $branch, array $data, array $via = [], ?string $expectedUpdatedAt = null): Branch
26:     {
27:         $this->access->assertCentralAccess($actor);
28:         DB::transaction(function () use ($actor, $branch, $data, $via, $expectedUpdatedAt): void {
29:             StaffAdministration::lock();
30:             StaffAdministration::authorize($actor, ['branches.update', 'branches.manage']);
31:             $this->access->assertCentralAccess($actor);
32:             $locked = Branch::query()->lockForUpdate()->findOrFail($branch->id);
33:             // M3: قفل توافقي حقيقي بالـ lock_version (بدقة أقل من الثانية)،
34:             // مع دعم expectedUpdatedAt القديم احتياطًا.
35:             $expectedLockVersion = $data['lock_version'] ?? null;
36:             unset($data['lock_version']);
37:             if ($expectedLockVersion !== null) {
38:                 abort_if((int) $locked->lock_version !== (int) $expectedLockVersion, 409, 'تم تعديل السجل بواسطة مستخدم آخر؛ أعد التحميل قبل الحفظ.');
39:             } elseif ($expectedUpdatedAt !== null && $locked->updated_at?->toIso8601String() !== $expectedUpdatedAt) {
40:                 abort(409, 'تم تعديل السجل بواسطة مستخدم آخر؛ أعد التحميل قبل الحفظ.');
41:             }
42:             $before = StaffAdministration::branchState($locked);
43:             // city_id wins over free text so the two columns cannot drift.
44:             if (array_key_exists('city_id', $data) && ! empty($data['city_id'])
45:                 && ($city = \App\Models\City::query()->find($data['city_id']))) {
46:                 $data['city'] = $city->name_ar ?: $city->name_en;
47:             }
48:             // M4: same rule as SetLocationStatus — an approved transfer from a
49:             // disabled branch can never be cancelled (release path is locked),
50:             // and a shipped transfer to it can never be received (goods stay
51:             // "in transit" forever). Non-zero balances would freeze too.
52:             if (array_key_exists('is_active', $data) && ! $data['is_active']) {
53:                 $hasOpenTransfers = StockTransfer::query()
54:                     ->where(fn ($q) => $q->where('from_branch_id', $locked->id)->orWhere('to_branch_id', $locked->id))
55:                     ->whereIn('status', [TransferStatus::Approved->value, TransferStatus::Shipped->value])
56:                     ->exists();
57:                 if ($hasOpenTransfers) {
58:                     throw new BusinessException('لا يمكن تعطيل الفرع وبه تحويلات معتمدة أو مشحونة لم تُستلم؛ ألغها أو أكمل استلامها أولًا.');
59:                 }
60:                 if (StockLevel::query()->where('branch_id', $locked->id)->hasNonZeroBalance()->exists()) {
61:                     throw new BusinessException('لا يمكن تعطيل الفرع وبه أرصدة غير صفرية؛ صفّرها أولًا.');
62:                 }
63:             }
64:             // M-12: وردية POS مفتوحة أو خزينة بها رصيد — موظفو الفرع المعطّل
65:             // ممنوعون من أي وصول (fail-closed) فلن يستطيعوا إغلاقها بعده.
66:             if (array_key_exists('is_active', $data) && ! $data['is_active']) {
67:                 if (PosShift::query()->where('branch_id', $locked->id)->where('status', PosShiftStatus::Open->value)->exists()) {
68:                     throw new BusinessException('لا يمكن تعطيل الفرع وبه وردية POS مفتوحة؛ أغلقها أولًا.');
69:                 }
70:                 if (Treasury::query()->where('branch_id', $locked->id)->where('current_balance', '!=', 0)->exists()) {
71:                     throw new BusinessException('لا يمكن تعطيل الفرع وخزائنه بها أرصدة؛ صفّرها أولًا.');
72:                 }
73:             }
74:             // branch.deactivated is recorded only on a real true -> false transition.
75:             $wasActive = (bool) $locked->is_active;
76:             // Changing a branch into a warehouse while POS shifts are open is
77:             // rejected: open shifts cannot be closed from a deactivated branch.
78:             if (array_key_exists('type', $data) && (string) $locked->type->value === 'branch'
79:                 && (string) ($data['type'] instanceof \App\Enums\BranchType ? $data['type']->value : $data['type']) === 'warehouse'
80:                 && PosShift::query()->where('branch_id', $locked->id)->where('status', PosShiftStatus::Open->value)->exists()) {
81:                 throw new BusinessException('لا يمكن تحويل الفرع إلى مخزن وبه وردية POS مفتوحة؛ أغلقها أولًا.');
82:             }
83:             $locked->update($data);
84:             $deactivated = array_key_exists('is_active', $data) && ! (bool) $data['is_active'] && $wasActive;
85:             $action = $deactivated ? 'branch.deactivated' : 'branch.updated';
86:             StaffAdministration::audit($actor, $action, 'branch', $locked->id, array_keys($data), $before, StaffAdministration::branchState($locked), $via);
87:         });
88: 
89:         return $branch->refresh();
90:     }
