 86:         $byTool = [];
 87:         $totalProposals = 0;
 88:         $totalExecuted = 0;
 89:         $totalCancelled = 0;
 90:         $totalFailed = 0;
 91:         // task.txt §2-27: failed_409_count must count 409-conflict failures
