 97:         foreach ($actionRows as $r) {
 98:             $t = (string) $r->tool;
 99:             $st = (string) $r->status;
100:             $c = (int) $r->count;
101:             $byTool[$t] ??= ['tool' => $t, 'total' => 0, 'executed' => 0, 'cancelled' => 0, 'failed' => 0, 'pending' => 0];
102:             $byTool[$t]['total'] += $c;
103:             $totalProposals += $c;
104:             if (in_array($st, ['executed', 'undone'], true)) {
