119:             $decided = $item['executed'] + $item['cancelled'];
120:             $cancelRate = $decided > 0 ? round(($item['cancelled'] / $decided) * 100, 1) : 0.0;
121:             $confirmRate = $decided > 0 ? round(($item['executed'] / $decided) * 100, 1) : 0.0;
