 35:     private function assertAccessible(?User $actor, User $target): void
 36:     {
 37:         abort_if($target->is_system, 404);
 38:         $branch = $this->branches->restrictedBranch($actor);
 39:         abort_if($branch !== null && (int) $target->branch_id !== $branch, 403);
