 42:     public function index(Request $request): AnonymousResourceCollection
 43:     {
 44:         $filters = $request->validate([
 45:             'branch_id' => ['sometimes', 'nullable', 'integer', Rule::exists('branches', 'id')],
 46:             'role' => [
 47:                 'sometimes',
 48:                 'nullable',
 49:                 'string',
 50:                 Rule::exists('roles', 'name')->where('guard_name', 'staff'),
 51:             ],
 52:             'search' => ['sometimes', 'nullable', 'string', 'max:100'],
 53:             'is_active' => ['sometimes', 'boolean'],
 54:             'per_page' => ['sometimes', 'integer', 'min:1', 'max:100'],
 55:         ]);
 56: 
 57:         $branch = $this->branches->restrictedBranch($request->user('staff'));
 58: 
 59:         $users = User::query()
 60:             ->with(['branch', 'roles'])
 61:             ->where('is_system', false)
 62:             ->when($branch !== null, fn ($query) => $query->where('branch_id', $branch))
 63:             ->when(array_key_exists('branch_id', $filters), function ($query) use ($filters): void {
 64:                 if ($filters['branch_id'] === null) {
 65:                     $query->whereNull('branch_id');
 66: 
 67:                     return;
 68:                 }
 69: 
 70:                 $query->where('branch_id', $filters['branch_id']);
 71:             })
 72:             ->when(! empty($filters['role']), function ($query) use ($filters): void {
 73:                 $query->whereHas('roles', function ($roles) use ($filters): void {
 74:                     $roles->where('name', $filters['role'])->where('guard_name', 'staff');
 75:                 });
 76:             })
 77:             ->when(! empty($filters['search']), function ($query) use ($filters): void {
 78:                 $term = SearchTerm::pattern(mb_strtolower(trim($filters['search'])));
 79:                 $query->where(function ($q) use ($term): void {
 80:                     $q->whereRaw('LOWER(name) LIKE ?', [$term])
 81:                         ->orWhereRaw('LOWER(email) LIKE ?', [$term])
 82:                         ->orWhere('phone', 'like', $term);
 83:                 });
 84:             })
 85:             ->when(array_key_exists('is_active', $filters), fn ($q) => $q->where('is_active', (bool) $filters['is_active']))
 86:             ->orderBy('id')
 87:             ->paginate($filters['per_page'] ?? 15)
 88:             ->withQueryString();
 89: 
 90:         return UserResource::collection($users);
 91:     }
