 93:     public function store(StoreUserRequest $request): JsonResponse
 94:     {
 95:         $validated = $request->validated();
 96:         $roles = $validated['roles'] ?? [];
 97:         $currentUser = $request->user('staff');
 98:         $branch = $this->branches->restrictedBranch($currentUser);
 99:         abort_if($branch !== null && (int) ($validated['branch_id'] ?? 0) !== $branch, 403);
100: 
101:         if (
102:             in_array(StaffRole::SuperAdmin->value, $roles, true)
103:             && (! $currentUser instanceof User || ! $currentUser->hasRole(StaffRole::SuperAdmin->value, 'staff'))
