126:     /**
127:      * L8: self-service password rotation — no users.update required, so a
128:      * flagged newcomer can always comply. Only the own password may change
129:      * here, and only with the verified current password.
130:      */
131:     public function updateOwnPassword(Request $request): UserResource|JsonResponse
132:     {
133:         $user = $request->user('staff');
134:         abort_unless($user instanceof User, 403);
135:         $validated = $request->validate([
136:             'expected_version' => ['required', 'integer', 'min:0'],
137:             'current_password' => ['required', 'string', 'max:255'],
138:             'password' => ['required', 'string', Password::min(12)->letters()->numbers(), 'max:255', new PasswordByteLimit],
139:         ]);
140:         $limitKey = 'staff:current-password:'.$user->id;
141:         if (RateLimiter::tooManyAttempts($limitKey, max(1, (int) config('auth.staff_current_password_failures', 5)))) {
142:             throw new TooManyRequestsHttpException(RateLimiter::availableIn($limitKey));
143:         }
144:         if (! Hash::check($validated['current_password'], $user->password)) {
145:             RateLimiter::hit($limitKey, 3600);
146: 
147:             throw ValidationException::withMessages(['current_password' => 'أدخل كلمة المرور الحالية الصحيحة لتغيير بيانات الدخول.']);
148:         }
149:         RateLimiter::clear($limitKey);
150:         $failure = app(UpdateStaffUser::class)(
151:             $user,
152:             $user,
153:             ['password' => Hash::make($validated['password']), 'expected_version' => $validated['expected_version']],
154:             ['current_token_id' => $request->user('staff')?->currentAccessToken()?->id],
155:             verifiedPasswordHash: $user->password,
156:             selfRotation: true
157:         );
158:         if ($failure !== null) {
159:             return response()->json(['message' => 'تعذر تغيير كلمة المرور.'], 403);
160:         }
161: 
162:         return $this->userResource($user->refresh());
163:     }
