165:     public function update(UpdateUserRequest $request, User $user): UserResource|JsonResponse
166:     {
167:         abort_if($user->is_system, 404);
168:         $validated = $request->validated();
169:         $currentUser = $request->user('staff');
170:         $isCurrentUser = $currentUser instanceof User && $currentUser->is($user);
171: 
172:         if ($isCurrentUser && (array_key_exists('roles', $validated) || array_key_exists('is_active', $validated))) {
173:             return response()->json([
174:                 'message' => 'لا يمكنك تغيير أدوارك أو حالة تنشيط حسابك الحالي.',
175:             ], 403);
176:         }
177: 
178:         $roles = $validated['roles'] ?? null;
179:         $userAttributes = Arr::except($validated, ['roles', 'current_password', 'expected_version']);
180: 
181:         if (array_key_exists('password', $userAttributes) && $userAttributes['password'] === null) {
182:             unset($userAttributes['password']);
183:         }
184: 
185:         $verifiedPasswordHash = null;
186:         $credentialChange = $isCurrentUser && (isset($userAttributes['password'])
187:             || (isset($userAttributes['email']) && $userAttributes['email'] !== $user->email));
188:         $passwordLimitKey = 'staff:current-password:'.$user->id;
189:         if ($credentialChange && RateLimiter::tooManyAttempts($passwordLimitKey, max(1, (int) config('auth.staff_current_password_failures', 5)))) {
190:             throw new TooManyRequestsHttpException(RateLimiter::availableIn($passwordLimitKey));
191:         }
192:         if ($isCurrentUser && (isset($userAttributes['password'])
193:             || (isset($userAttributes['email']) && $userAttributes['email'] !== $user->email))
194:             && is_string($validated['current_password'] ?? null)
195:             && Hash::check($validated['current_password'], $user->password)) {
196:             $verifiedPasswordHash = $user->password;
197:         }
198: 
199:         if ($credentialChange && is_string($validated['current_password'] ?? null)) {
200:             if ($verifiedPasswordHash === null) {
201:                 RateLimiter::hit($passwordLimitKey, 3600);
202:             } else {
203:                 RateLimiter::clear($passwordLimitKey);
204:             }
205:         }
206:         if ($credentialChange && $verifiedPasswordHash === null) {
207:             throw ValidationException::withMessages(['current_password' => 'أدخل كلمة المرور الحالية الصحيحة لتغيير بيانات الدخول.']);
208:         }
209:         if (isset($userAttributes['password'])) {
210:             $userAttributes['password'] = Hash::make($userAttributes['password']);
211:         }
212: 
213:         $actionData = Arr::except($validated, ['password']);
214:         if (isset($userAttributes['password'])) {
215:             $actionData['password'] = $userAttributes['password'];
216:         }
217:         // L8: self password-only rotation (verified current password) does not
218:         // require users.update — otherwise flagged newcomers could never comply.
219:         $selfRotation = $isCurrentUser && isset($userAttributes['password'])
220:             && array_diff(array_keys($validated), ['password', 'current_password', 'expected_version']) === [];
221:         $failure = app(UpdateStaffUser::class)($currentUser, $user, $actionData,
222:             ['current_token_id' => $selfRotation ? $request->user('staff')?->currentAccessToken()?->id : null],
223:             verifiedPasswordHash: $verifiedPasswordHash, selfRotation: $selfRotation);
224: 
225:         if ($failure !== null) {
226:             if ($failure === 'insufficient_permissions') {
227:                 return $this->insufficientPermissionsResponse();
228:             }
229: 
230:             return response()->json([
231:                 'message' => $failure === 'protected_super_admin'
232:                     ? 'يجب الإبقاء على حساب Super Admin نشط واحد على الأقل.'
233:                     : 'لا يمكن للمستخدم الحالي تعديل حساب Super Admin أو إسناد دوره.',
234:             ], 403);
235:         }
236: 
237:         return $this->userResource($user->refresh());
238:     }
