240:     public function destroy(Request $request, User $user): JsonResponse
241:     {
242:         abort_if($user->is_system, 404);
243:         $currentUser = $request->user('staff');
244:         $validated = $request->validate(['expected_version' => ['required', 'integer', 'min:0']]);
245: 
246:         if ($currentUser instanceof User && $currentUser->is($user)) {
247:             return response()->json([
248:                 'message' => 'لا يمكنك تعطيل حسابك الحالي.',
249:             ], 403);
250:         }
251: 
252:         $deleted = app(DeactivateStaffUser::class)($currentUser, $user, (int) $validated['expected_version']);
253: 
254:         if (! $deleted) {
255:             return response()->json([
256:                 'message' => 'لا يمكن تعطيل حساب Super Admin أو حساب يمتلك صلاحيات لا تملكها.',
257:             ], 403);
258:         }
259: 
260:         return response()->json([
261:             'message' => 'تم تعطيل حساب الموظف وإلغاء رموزه.',
262:             'data' => UserResource::make($user->refresh()->load(['branch', 'roles.permissions', 'permissions']))->resolve($request),
263:         ]);
264:     }
