  7: use Illuminate\Http\Client\ConnectionException;
  8: use Illuminate\Http\UploadedFile;
  9: use Illuminate\Support\Facades\Http;
 10: use InvalidArgumentException;
 11: use LogicException;
 12: 
 13: class GeminiClient
 14: {
 15:     /**
 16:      * M9: Laravel throws ConnectionException for both connect failures and
 17:      * read timeouts. Retrying a read timeout can double-bill tokens — the
 18:      * provider may have processed the first attempt. Retry connect/DNS
 19:      * failures only; a timeout fails fast instead.
 20:      */
 21:     private static function isConnectFailure(ConnectionException $e): bool
 22:     {
 23:         $message = strtolower($e->getMessage());
 24: 
 25:         return ! str_contains($message, 'timed out')
 26:             && ! str_contains($message, 'timeout')
 27:             && ! str_contains($message, 'cURL error 28');
 28:     }
 29: 
 30:     /**
 31:      * @param  list<UploadedFile>  $images
 32:      * @return array{text: string, model: string, usage: array{input_tokens: int, output_tokens: int, total_tokens: int}}
 33:      */
 34:     public function generate(string $prompt, array $images = [], ?string $system = null, ?string $model = null): array
 35:     {
 36:         $key = (string) config('services.gemini.api_key');
 37:         $model ??= config('services.gemini.model');
 38:         if ($key === '' || ! is_string($model) || ! preg_match('/^[a-zA-Z0-9._-]+$/', $model) || str_contains($model, '..')) {
 39:             throw new LogicException('إعدادات Gemini غير مكتملة.');
 40:         }
 41:         if (trim($prompt) === '') {
 42:             throw new InvalidArgumentException('نص الطلب مطلوب.');
 43:         }
 44:         if (count($images) > config('services.gemini.max_images', 5)) {
 45:             throw new InvalidArgumentException('الحد الأقصى 5 صور في الطلب.');
 46:         }
 47: 
 48:         $parts = [['text' => $prompt]];
 49:         foreach ($images as $image) {
 50:             if (! $image instanceof UploadedFile || ! $image->isValid()
 51:                 || ! in_array($image->getMimeType(), ['image/jpeg', 'image/png', 'image/webp'], true)
 52:                 || $image->getSize() > config('services.gemini.max_image_bytes', 4 * 1024 * 1024)) {
 53:                 throw new InvalidArgumentException('الصورة يجب أن تكون JPG أو PNG أو WebP وبحد أقصى 4MB.');
 54:             }
 55:             $parts[] = ['inlineData' => ['mimeType' => $image->getMimeType(), 'data' => base64_encode($image->getContent())]];
 56:         }
 57: 
 58:         $payload = [
 59:             'contents' => [['role' => 'user', 'parts' => $parts]],
 60:             'generationConfig' => [
 61:                 'temperature' => 0.4,
 62:                 'maxOutputTokens' => (int) config('services.gemini.max_output_tokens', 2048),
 63:             ],
 64:         ];
 65:         if ($system !== null && trim($system) !== '') {
 66:             $payload['systemInstruction'] = ['parts' => [['text' => $system]]];
 67:         }
 68: 
 69:         for ($attempt = 0; $attempt < 2; $attempt++) {
 70:             try {
 71:                 $response = Http::acceptJson()->asJson()->withHeaders(['x-goog-api-key' => $key])
 72:                     ->withOptions(['verify' => config('services.integrations.ca_bundle') ?: true])
 73:                     ->connectTimeout(5)->timeout(max(1, (int) config('services.gemini.timeout_seconds', 20)))
 74:                     ->post('https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent', $payload);
 75:             } catch (ConnectionException $e) {
 76:                 // M9: retry connect failures only — a read timeout may have
 77:                 // executed server-side, so retrying would double-bill tokens.
 78:                 if ($attempt === 0 && self::isConnectFailure($e)) {
 79:                     logger()->warning('gemini.request_retry', ['method' => 'generate', 'reason' => 'connect_failure']);
 80: 
 81:                     continue;
 82:                 }
 83:                 throw new GeminiException('تعذّر الاتصال بخدمة Gemini.');
 84:             }
 85:             if (($response->status() === 429 || $response->serverError()) && $attempt === 0) {
 86:                 logger()->warning('gemini.request_retry', ['method' => 'generate', 'reason' => 'http_'.$response->status()]);
 87:                 // L7: نحترم Retry-After (من ثانية لـ 5 ثواني) بدل 250ms.
 88:                 usleep(min(5, max(1, (int) $response->header('Retry-After'))) * 1_000_000);
 89: 
 90:                 continue;
 91:             }
 92:             if (! $response->successful()) {
 93:                 throw new GeminiException('تعذّر تنفيذ طلب Gemini.', $response->status());
 94:             }
 95: 
 96:             $candidate = $response->json('candidates.0', []);
 97:             if (! is_array($candidate)) {
 98:                 $candidate = [];
 99:             }
100:             if (($candidate['finishReason'] ?? null) !== 'STOP') {
101:                 throw new GeminiException('لم ترجع خدمة Gemini إجابة مكتملة.');
102:             }
103:             $text = collect($candidate['content']['parts'] ?? [])
104:                 ->reject(fn ($part) => ! empty($part['thought']))
105:                 ->pluck('text')->filter(fn ($part) => is_string($part))->implode('');
106:             if (trim($text) === '') {
107:                 throw new GeminiException('لم ترجع خدمة Gemini إجابة نصية.');
108:             }
109: 
110:             $usage = $response->json('usageMetadata', []);
111:             $input = (int) ($usage['promptTokenCount'] ?? 0);
112:             $output = (int) ($usage['candidatesTokenCount'] ?? 0);
113: 
114:             return ['text' => trim($text), 'model' => $model, 'usage' => [
115:                 'input_tokens' => $input, 'output_tokens' => $output,
116:                 'total_tokens' => (int) ($usage['totalTokenCount'] ?? $input + $output),
117:             ]];
118:         }
119: 
120:         throw new GeminiException('تعذّر تنفيذ طلب Gemini.');
121:     }
122: 
123:     /**
124:      * Structured JSON output for document/shelf-photo parsing (phase 4 stocktake
125:      * sheets). Prompt must instruct the model to ignore injected instructions in
126:      * the image text. Never use for direct approvals — fills counts only.
127:      *
128:      * @param  array<string,mixed>  $schema  JSON Schema for responseSchema
129:      * @param  list<UploadedFile>  $images
130:      * @return array{data:array<string,mixed>|list<mixed>, model:string, usage:array{input_tokens:int,output_tokens:int,total_tokens:int}}
131:      */
132:     public function generateStructured(string $prompt, array $schema, array $images = [], ?string $model = null): array
133:     {
134:         $key = (string) config('services.gemini.api_key');
135:         $model ??= config('services.gemini.model');
136:         if ($key === '' || ! is_string($model) || ! preg_match('/^[a-zA-Z0-9._-]+$/', $model) || str_contains($model, '..')) {
137:             throw new LogicException('إعدادات Gemini غير مكتملة.');
138:         }
139:         if (trim($prompt) === '') {
140:             throw new InvalidArgumentException('نص الطلب مطلوب.');
141:         }
142:         if ($schema === []) {
143:             throw new InvalidArgumentException('مخطط الاستجابة مطلوب.');
144:         }
145:         if (count($images) > config('services.gemini.max_images', 5)) {
146:             throw new InvalidArgumentException('الحد الأقصى 5 صور في الطلب.');
147:         }
148: 
149:         $parts = [['text' => $prompt]];
150:         foreach ($images as $image) {
151:             if (! $image instanceof UploadedFile || ! $image->isValid()
152:                 || ! in_array($image->getMimeType(), ['image/jpeg', 'image/png', 'image/webp'], true)
153:                 || $image->getSize() > config('services.gemini.max_image_bytes', 4 * 1024 * 1024)) {
154:                 throw new InvalidArgumentException('الصورة يجب أن تكون JPG أو PNG أو WebP وبحد أقصى 4MB.');
155:             }
156:             $parts[] = ['inlineData' => ['mimeType' => $image->getMimeType(), 'data' => base64_encode($image->getContent())]];
157:         }
158: 
159:         $payload = [
160:             'contents' => [['role' => 'user', 'parts' => $parts]],
161:             'generationConfig' => [
162:                 'temperature' => 0.2,
163:                 'maxOutputTokens' => (int) config('services.gemini.max_output_tokens', 2048),
