226:     /**
227:      * @param  list<array{role:string, parts:list<array<string,mixed>>}>  $contents
228:      * @param  list<array<string,mixed>>  $functionDeclarations
229:      * @return array{parts:list<array<string,mixed>>, text:string, calls:list<array{name:string,args:array<string,mixed>}>, usage:array{input_tokens:int,output_tokens:int,total_tokens:int}, finish:string, model:string}
230:      */
231:     public function converse(array $contents, array $functionDeclarations = [], ?string $system = null, ?string $model = null): array
232:     {
233:         $key = (string) config('services.gemini.api_key');
234:         $model ??= config('services.gemini.model');
235:         if ($key === '' || ! is_string($model) || ! preg_match('/^[a-zA-Z0-9._-]+$/', $model) || str_contains($model, '..')) {
236:             throw new LogicException('إعدادات Gemini غير مكتملة.');
237:         }
238:         if ($contents === []) {
239:             throw new InvalidArgumentException('محتوى المحادثة مطلوب.');
240:         }
241:         // Associative JSON decoding loses the distinction between {} and [].
242:         // Gemini requires these fields to remain maps, including after database replay.
243:         foreach ($contents as $turnIndex => $turn) {
244:             foreach ($turn['parts'] as $partIndex => $part) {
245:                 foreach (['functionCall' => 'args', 'functionResponse' => 'response'] as $node => $field) {
246:                     if (isset($part[$node][$field]) && is_array($part[$node][$field])) {
247:                         $contents[$turnIndex]['parts'][$partIndex][$node][$field] = (object) $part[$node][$field];
248:                     }
249:                 }
250:             }
251:         }
252:         // M-9: حد الإخراج من الإعدادات (كما في generate) لا مثبتًا — نماذج
253:         // التفكير (Gemini 2.5) تحسب توكنز التفكير ضمنه فتظهر MAX_TOKENS زورًا.
254:         $maxOutputTokens = max(1024, (int) config('services.gemini.max_output_tokens', 2048));
255:         $generationConfig = ['temperature' => 0.2, 'maxOutputTokens' => $maxOutputTokens];
256:         if (is_string($model) && preg_match('/^gemini-2\.5/i', $model) === 1) {
257:             $generationConfig['thinkingConfig'] = ['thinkingBudget' => min(1024, (int) ($maxOutputTokens / 4))];
258:         }
259:         $payload = [
260:             'contents' => $contents,
261:             'generationConfig' => $generationConfig,
262:         ];
263:         if ($functionDeclarations) {
264:             $payload['tools'] = [['functionDeclarations' => $functionDeclarations]];
265:             $payload['toolConfig'] = ['functionCallingConfig' => ['mode' => 'AUTO']];
266:         }
267:         if ($system !== null && trim($system) !== '') {
268:             $payload['systemInstruction'] = ['parts' => [['text' => $system]]];
269:         }
270:         for ($attempt = 0; $attempt < 2; $attempt++) {
271:             try {
272:                 $response = Http::acceptJson()->asJson()->withHeaders(['x-goog-api-key' => $key])
273:                     ->withOptions(['verify' => config('services.integrations.ca_bundle') ?: true])
274:                     ->connectTimeout(5)->timeout(max(1, (int) config('services.gemini.timeout_seconds', 20)))
275:                     ->post('https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent', $payload);
276:             } catch (ConnectionException $e) {
277:                 // M9: retry connect failures only (see generate()).
278:                 if ($attempt === 0 && self::isConnectFailure($e)) {
279:                     logger()->warning('gemini.request_retry', ['method' => 'converse', 'reason' => 'connect_failure']);
280: 
281:                     continue;
282:                 }
283:                 throw new GeminiException('تعذّر الاتصال بخدمة Gemini.');
284:             }
285:             if (($response->status() === 429 || $response->serverError()) && $attempt === 0) {
286:                 logger()->warning('gemini.request_retry', ['method' => 'converse', 'reason' => 'http_'.$response->status()]);
287:                 // L7: نحترم Retry-After (من ثانية لـ 5 ثواني) بدل 250ms.
288:                 usleep(min(5, max(1, (int) $response->header('Retry-After'))) * 1_000_000);
289: 
290:                 continue;
291:             }
292:             if (! $response->successful()) {
293:                 throw new GeminiException('تعذّر تنفيذ طلب Gemini.', $response->status());
294:             }
295:             $candidate = $response->json('candidates.0', []);
296:             if (! is_array($candidate)) {
297:                 $candidate = []; // L7: يرمي GeminiException تحت (finishReason فاضي) بدل TypeError
298:             }
299:             $finish = (string) ($candidate['finishReason'] ?? '');
300:             $usage = $response->json('usageMetadata', []);
301:             // M7: حضّر قياس الاستخدام قبل أي باب خروج — الرد غير المكتمل
302:             // (MAX_TOKENS/SAFETY...) كمان بيكلف توكنز لازم تدخل الميزانية.
303:             $measured = [
304:                 'input_tokens' => (int) ($usage['promptTokenCount'] ?? 0),
305:                 'output_tokens' => (int) ($usage['candidatesTokenCount'] ?? 0),
306:                 'total_tokens' => (int) ($usage['totalTokenCount'] ?? 0),
307:             ];
308:             if ($finish !== 'STOP') {
309:                 throw GeminiException::withUsage('لم ترجع خدمة Gemini إجابة مكتملة.', $measured, $response->status());
310:             }
311:             $parts = $candidate['content']['parts'] ?? [];
312:             if (! is_array($parts)) {
313:                 $parts = [];
314:             }
315:             $text = collect($parts)->reject(fn ($p) => ! empty($p['thought']))->pluck('text')->filter(fn ($p) => is_string($p))->implode('');
316:             $calls = [];
317:             foreach ($parts as $part) {
318:                 if (is_array($part) && isset($part['functionCall']['name'])) {
319:                     $calls[] = ['name' => (string) $part['functionCall']['name'], 'args' => is_array($part['functionCall']['args'] ?? null) ? $part['functionCall']['args'] : []];
320:                     if (isset($part['functionCall']['id']) && is_string($part['functionCall']['id'])) {
321:                         $calls[array_key_last($calls)]['id'] = $part['functionCall']['id'];
322:                     }
323:                 }
324:             }
325:             if (! $calls && trim($text) === '') {
326:                 throw GeminiException::withUsage('لم ترجع خدمة Gemini إجابة مكتملة.', $measured);
327:             }
328:             $input = $measured['input_tokens'];
329:             $output = $measured['output_tokens'];
330:             $output = max($output, $measured['total_tokens'] - $input);
331: 
332:             return ['parts' => $parts, 'text' => trim($text), 'calls' => $calls, 'finish' => $finish, 'model' => $model,
333:                 'usage' => ['input_tokens' => $input, 'output_tokens' => $output, 'total_tokens' => max($measured['total_tokens'], $input + $output)]];
334:         }
335:         throw new GeminiException('تعذّر تنفيذ طلب Gemini.');
336:     }
