 35:     public static function normalizeDigits(string $value): string
 36:     {
 37:         return strtr($value, [
 38:             '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',
 39:             '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
 40:             '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',
 41:             '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
 42:         ]);
 43:     }
