 45:     /** @return list<string> */
 46:     public static function expandCatalogSearchTerms(string $query): array
 47:     {
 48:         $clean = trim(self::normalizeDigits($query));
 49:         if ($clean === '') {
 50:             return [];
 51:         }
 52:         $terms = [$clean];
 53:         $norm = self::normalizeForSearch($clean);
 54:         if ($norm !== '' && $norm !== $clean) {
 55:             $terms[] = $norm;
 56:         }
 57:         $synonyms = (array) config('ai_catalog_synonyms', []);
 58:         foreach ($synonyms as $phrase => $expansions) {
 59:             $normPhrase = self::normalizeForSearch((string) $phrase);
 60:             if ($normPhrase !== '' && (str_contains($norm, $normPhrase) || str_contains(mb_strtolower($clean), mb_strtolower((string) $phrase)))) {
 61:                 foreach ((array) $expansions as $exp) {
 62:                     $terms[] = (string) $exp;
 63:                 }
 64:             }
 65:         }
 66: 
 67:         return array_values(array_unique(array_filter($terms, fn ($t) => trim($t) !== '')));
 68:     }
 69: 
 70:     public static function normalize(string $value): string
 71:     {
 72:         $v = mb_strtolower(trim($value));
 73:         $v = str_replace(['أ', 'إ', 'آ', 'ٱ'], 'ا', $v);
 74:         $v = str_replace(['ة'], 'ه', $v);
 75:         $v = str_replace(['ى'], 'ي', $v);
 76:         $v = preg_replace('/[\x{064B}-\x{065F}\x{0640}]/u', '', $v) ?? $v;
 77: 
 78:         return preg_replace('/\s+/u', ' ', $v) ?? $v;
 79:     }
