 93:     /** @return list<array{id:int,label:string,meta:string}> */
 94:     public function branches(User $actor, string $query = '', array $filters = []): array
 95:     {
 96:         $restricted = $this->restricted($actor);
 97:         if ($restricted === -1) {
 98:             return [];
 99:         }
100: 
101:         // M6/L5: الفلترة في SQL (ILIKE محمي بـ SearchTerm::escape) مع LIMIT —
102:         // استعلام بلا نتيجة ما يمسحش الجدول كله ولا يعمل ذاكرة lazy.
103:         return Branch::query()->withCount('users')
104:             ->when($restricted !== null, fn ($x) => $x->whereKey($restricted))
105:             ->when(array_key_exists('active', $filters), fn ($x) => $x->where('is_active', $filters['active']))
106:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
107:             ->when(isset($filters['city']), fn ($x) => $x->where('city', $filters['city']))
108:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
109:                 ->where('name', 'ilike', SearchTerm::pattern($query))
110:                 ->orWhere('code', 'ilike', SearchTerm::pattern($query))
111:                 ->orWhere('city', 'ilike', SearchTerm::pattern($query))))
112:             ->orderBy('id')
113:             ->limit(50)
114:             ->get()
115:             ->map(fn (Branch $b) => ['id' => $b->id, 'label' => $b->name.' ('.$b->code.')', 'meta' => trim(($b->city ?? '').' · '.($b->is_active ? 'نشط' : 'متوقف').' · موظفين: '.$b->users_count)])
116:             ->values()
117:             ->all();
118:     }
