183:             ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted), fn ($q) => $q->when($branchId !== null, fn ($w) => $w->where('branch_id', $branchId)))
184:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
185:                 ->where('name', 'ilike', SearchTerm::pattern($query))
