199:     /** @return list<array{id:int,label:string,meta:string}> */
200:     public function transfers(User $actor, string $query = '', array $filters = []): array
201:     {
202:         $restricted = $this->restricted($actor);
203:         if ($restricted === -1) {
204:             return [];
205:         }
206:         $scope = fn ($x) => $restricted !== null
207:             ? $x->where(fn ($w) => $w->where('from_branch_id', $restricted)->orWhere('to_branch_id', $restricted))
208:             : $x;
209:         $clean = trim(self::normalizeDigits($query));
210: 
211:         // مسار سريع: رقم مستند مضبوط (TRF-00012).
212:         if ($clean !== '' && preg_match('/^[A-Za-z]+-\d+$/', $clean)) {
213:             $exact = StockTransfer::query()->with(['fromBranch:id,name', 'toBranch:id,name'])
214:                 ->tap($scope)->whereRaw('LOWER(transfer_number) = LOWER(?)', [$clean])->limit(2)->get();
215:             if ($exact->count() === 1) {
216:                 return $this->mapTransfers($exact)->all();
217:             }
218:         }
219: 
220:         $search = $this->inventoryDocumentSearch($clean);
221:         $route = null;
222:         if (preg_match('/(?:^|\s)من\s+(.+?)\s+(?:إلى|الى|لـ?|لفرع)\s*(.+)$/u', $search, $parts)) {
223:             $route = [$this->inventoryDocumentSearch($parts[1]), $this->inventoryDocumentSearch($parts[2])];
224:         }
225: 
226:         return $this->mapTransfers(StockTransfer::query()->with(['fromBranch:id,name', 'toBranch:id,name'])
227:             ->tap($scope)
228:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
229:             ->when(self::mentionsYesterday($clean), fn ($x) => $x->whereDate('created_at', today()->subDay()))
230:             ->when(self::mentionsToday($clean), fn ($x) => $x->whereDate('created_at', today()))
231:             ->when($route !== null, fn ($x) => $x
232:                 ->whereHas('fromBranch', fn ($b) => $b->where('name', 'ilike', SearchTerm::pattern($route[0])))
233:                 ->whereHas('toBranch', fn ($b) => $b->where('name', 'ilike', SearchTerm::pattern($route[1]))))
234:             ->when($route === null && $search !== '', function ($x) use ($search): void {
235:                 $pattern = SearchTerm::pattern($search);
236:                 $x->where(fn ($w) => $w
237:                     ->where('transfer_number', 'ilike', $pattern)
238:                     ->orWhere('notes', 'ilike', $pattern)
239:                     ->orWhereHas('fromBranch', fn ($b) => $b->where('name', 'ilike', $pattern))
240:                     ->orWhereHas('toBranch', fn ($b) => $b->where('name', 'ilike', $pattern)));
241:             })
242:             ->orderByDesc('id')
243:             ->limit(20)
244:             ->get())->all();
245:     }
