274:                 $x->where(fn ($w) => $w
275:                     ->where('stocktake_number', 'ilike', $pattern)
276:                     ->orWhere('notes', 'ilike', $pattern)
277:                     ->orWhereHas('branch', fn ($b) => $b->where('name', 'ilike', $pattern)));
278:             })
279:             ->orderByDesc('id')
280:             ->limit(20)
281:             ->get())->all();
282:     }
