284:     private function inventoryDocumentSearch(string $query): string
285:     {
286:         $query = preg_replace('/(?:^|\s)(?:التحويل|تحويل|اللي|جرد|الجرد|بتاع|فرع|امبارح|أمس|النهارده|اليوم)(?=\s|$)/u', ' ', $query) ?? $query;
287: 
288:         return trim(preg_replace('/\s+/u', ' ', $query) ?? $query);
