322:     public function treasuries(User $actor, string $query = '', array $filters = []): array
323:     {
324:         $restricted = $this->restricted($actor);
325:         if ($restricted === -1) {
326:             return [];
327:         }
328:         $clean = trim(self::normalizeDigits($query));
329: 
330:         // مسار سريع: كود خزينة مضبوط.
331:         if ($clean !== '' && preg_match('/^[A-Za-z]+-\d+$/', $clean)) {
332:             $exact = Treasury::query()->with('branch:id,name')
333:                 ->when($restricted !== null, fn ($x) => $x->where('branch_id', $restricted))
334:                 ->whereRaw('LOWER(code) = LOWER(?)', [$clean])->limit(2)->get();
335:             if ($exact->count() === 1) {
336:                 return $this->mapTreasuries($exact, $actor)->all();
337:             }
338:         }
339: 
340:         return $this->mapTreasuries(Treasury::query()->with('branch:id,name')
341:             ->when($restricted !== null, fn ($x) => $x->where('branch_id', $restricted))
342:             ->when($restricted === null && isset($filters['branch_id']), fn ($x) => $x->where('branch_id', (int) $filters['branch_id']))
343:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
344:             ->when(array_key_exists('active', $filters), fn ($x) => $x->where('is_active', (bool) $filters['active']))
345:             ->when($clean !== '', function ($x) use ($clean): void {
346:                 $pattern = SearchTerm::pattern($clean);
347:                 $x->where(fn ($w) => $w
348:                     ->where('name', 'ilike', $pattern)
349:                     ->orWhere('code', 'ilike', $pattern));
350:             })
351:             ->orderBy('id')
352:             ->limit(20)
353:             ->get(), $actor)->all();
354:     }
