374:             }
375:         }
376: 
377:         return $this->mapTreasuryTransfers(TreasuryTransfer::query()->with(['fromTreasury.branch:id,name', 'toTreasury.branch:id,name'])
378:             ->when($restricted !== null, fn ($x) => $x->where(fn ($w) => $w
