381:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
382:             ->when(self::mentionsYesterday($clean), fn ($x) => $x->whereDate('created_at', today()->subDay()))
383:             ->when(self::mentionsToday($clean), fn ($x) => $x->whereDate('created_at', today()))
384:             ->when($clean !== '', function ($x) use ($clean): void {
385:                 $pattern = SearchTerm::pattern($clean);
386:                 $x->where(fn ($w) => $w
387:                     ->where('transfer_number', 'ilike', $pattern)
388:                     ->orWhere('notes', 'ilike', $pattern));
389:             })
390:             ->orderByDesc('id')
391:             ->limit(20)
392:             ->get())->all();
