517:     /** تقنيع رقم موبايل: 11 رقمًا يظهر أول 3 وآخر 3 فقط، غير كده ***. */
518:     public static function maskPhone(?string $p): string
519:     {
520:         return $p && strlen($p) === 11 ? substr($p, 0, 3).'*****'.substr($p, -3) : '***';
521:     }
