523:     /** تقنيع رقم ضريبي/سجل تجاري: أول حرفين وآخر حرفين فقط. */
524:     public static function maskLegal(?string $v): ?string
525:     {
526:         if ($v === null || trim($v) === '') {
527:             return null;
528:         }
529:         $v = trim($v);
530: 
531:         return mb_strlen($v) <= 4 ? '***' : mb_substr($v, 0, 2).'***'.mb_substr($v, -2);
532:     }
