555:     /**
556:      * @return list<array{id:int,label:string,meta:string}>
557:      *                                                      لا يوجد branch scoping هنا — مقصود، زي REST بالظبط
558:      *                                                      (CustomerController مبيستخدمش BranchAccess).
559:      */
560:     public function customers(User $actor, string $query = '', array $filters = []): array
561:     {
562:         $q = Customer::query()
563:             ->when(($filters['business_only'] ?? false), fn ($x) => $x->whereIn('type', ['wholesale', 'distributor']))
564:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
565:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
566:             ->when(isset($filters['customer_group_id']), fn ($x) => $x->where('customer_group_id', $filters['customer_group_id']))
567:             ->when(isset($filters['pending_older_than_hours']), fn ($x) => $x->where('status', 'pending')->where('created_at', '<', now()->subHours((int) $filters['pending_older_than_hours'])));
568:         if (trim($query) !== '') {
569:             // L5: حرف أو اتنين مش بيستفيدوا من trigram.
570:             if (mb_strlen(trim($query)) < 3) {
571:                 return [];
572:             }
573:             if (preg_match('/^[0-9٠-٩۰-۹\s().+-]+$/u', trim($query))) {
574:                 // L5: LIKE مش ILIKE عشان يستخدم index الـ text_pattern_ops.
575:                 $q->whereLike('phone', SearchTerm::prefix(Customer::normalizePhone($query)), caseSensitive: true);
576:             } else {
577:                 $q->whereLike('search_text', SearchTerm::pattern($query), caseSensitive: false);
578:             }
579:         }
580: 
581:         return $q->orderBy('id')->limit(50)->get()
582:             ->map(fn (Customer $c) => [
583:                 'id' => $c->id,
584:                 'label' => $c->company_name ? $c->name.' — '.$c->company_name : $c->name,
585:                 'meta' => self::maskPhone($c->phone).' · '.self::statusLabel($c->status->value).' · '.self::typeLabel($c->type->value),
586:             ])
587:             ->values()
588:             ->all();
589:     }
