687:     /** @param list<string> $fields */
688:     public function matches(string $query, array $fields): bool
689:     {
690:         $nq = self::normalizeForSearch($query);
691:         if ($nq === '') {
692:             return true;
693:         }
694:         foreach ($fields as $f) {
695:             if (str_contains(self::normalizeForSearch($f), $nq)) {
696:                 return true;
697:             }
698:         }
699: 
700:         return false;
701:     }
702: 
703:     public static function normalizeForSearch(string $value): string
704:     {
705:         return preg_replace('/(^|\s)ال/u', '$1', self::normalize($value)) ?? self::normalize($value);
706:     }
