913:         abort_unless(app(ToolRegistry::class)->canReadEntity($actor, $type), 403, 'المرجع خارج صلاحيات العرض.');
914:         $id = $reference['id'] ?? null;
915:         $branch = $this->restricted($actor);
916:         $model = match ($type) {
917:             'branch' => Branch::query()->when($branch !== null, fn ($q) => $q->whereKey($branch))->find($id),
918:             'user' => User::query()->where('is_system', false)->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
919:             'role' => Role::query()->where('guard_name', 'staff')->find($id),
920:             'permission' => Permission::query()->where('guard_name', 'staff')->where('name', $id)->first(),
921:             'location' => Location::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
922:             // العملاء بلا branch scoping — زي REST بالظبط.
923:             'customer' => Customer::query()->find($id),
924:             'customer_group' => CustomerGroup::query()->find($id),
925:             'category' => Category::query()->find($id),
926:             'product' => Product::query()->find($id),
927:             'variant' => ProductVariant::query()->with('product:id,name_ar,code')->find($id),
928:             'transfer' => StockTransfer::query()->when($branch !== null, fn ($q) => $q->where(fn ($w) => $w->where('from_branch_id', $branch)->orWhere('to_branch_id', $branch)))->find($id),
929:             'stocktake' => Stocktake::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
930:             'production_receipt' => ProductionReceipt::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
931:             'treasury' => Treasury::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
932:             'treasury_transfer' => TreasuryTransfer::query()->when($branch !== null, fn ($q) => $q->where(fn ($w) => $w
933:                 ->whereHas('fromTreasury', fn ($t) => $t->where('branch_id', $branch))
934:                 ->orWhereHas('toTreasury', fn ($t) => $t->where('branch_id', $branch))))->find($id),
935:             'expense' => Expense::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
936:             default => null,
937:         };
938:         abort_unless($model, 422, 'الاختيار مش موجود أو خارج نطاقك.');
939: 
940:         $rawLabel = match ($type) {
941:             'category', 'product' => (string) $model->name_ar,
942:             'variant' => (($model->product?->name_ar ?? '').' — '.$model->sku),
943:             'transfer' => (string) $model->transfer_number,
944:             'stocktake' => (string) $model->stocktake_number,
945:             'production_receipt' => (string) $model->batch_number,
946:             'treasury_transfer' => (string) $model->transfer_number,
947:             'expense' => (string) $model->expense_number,
948:             default => (string) $model->name,
