 18: /**
 19:  * Staff administration guardrails and security coordinator.
 20:  * Manages concurrency locks, optimistic locking, role invariants, and audit logging.
 21:  */
 22: final class StaffAdministration
 23: {
 24:     /**
 25:      * Acquire a transactional PostgreSQL advisory lock to serialize staff membership and role changes.
 26:      * Prevents race conditions during critical checks such as last-active-admin validation.
 27:      */
 28:     public static function lock(): void
 29:     {
 30:         // L3: SET LOCAL يسري على الـ transaction كلها — 55P03 (lock timeout)
 31:         // تتحول لـ RetryableConflict (409 قابلة لإعادة المحاولة) بدل 500،
 32:         // وبدل failed نهائي في مسار confirmBulk.
 33:         try {
 34:             DB::statement("SET LOCAL lock_timeout = '5s'");
 35:             DB::select('SELECT pg_advisory_xact_lock(79301, 1)');
 36:         } catch (QueryException $e) {
 37:             if (($e->errorInfo[0] ?? null) === '55P03') {
 38:                 throw new RetryableConflict('النظام مشغول حاليًا؛ حاول مرة أخرى.', $e);
 39:             }
 40:             throw $e;
 41:         }
 42:     }
 43: 
 44:     /**
 45:      * Verify record lock_version matches expected optimistic concurrency version.
 46:      */
 47:     public static function assertVersion(Model $record, ?int $expected): void
 48:     {
 49:         // Detects concurrent permission/profile updates occurring within the same second
 50:         abort_if($expected !== null && (int) $record->lock_version !== $expected, 409,
 51:             'تم تعديل السجل بواسطة مستخدم آخر؛ أعد التحميل قبل الحفظ.');
 52:     }
 53: 
 54:     /**
 55:      * Increment monotonic lock_version counter for optimistic concurrency tracking.
 56:      */
 57:     public static function advanceVersion(Model $record): void
 58:     {
 59:         $record->forceFill(['lock_version' => (int) $record->lock_version + 1])->save();
 60:     }
 61: 
 62:     /**
 63:      * Invalidate cached Spatie permissions across all application instances after commit.
 64:      */
 65:     public static function clearPermissionCacheAfterCommit(): void
 66:     {
 67:         DB::afterCommit(function (): void {
 68:             try {
 69:                 app(PermissionRegistrar::class)->forgetCachedPermissions();
 70:             } catch (\Throwable $exception) {
 71:                 report($exception);
 72:                 logger()->error('staff.permission_cache_invalidation_failed');
 73:             }
 74:         });
 75:     }
 76: 
 77:     /**
 78:      * Capture snapshot of user role assignments, branch scoping, and active status.
 79:      *
 80:      * @return array{roles: list<string>, branch_id: int|null, is_active: bool}
 81:      */
 82:     public static function userState(User $user): array
 83:     {
 84:         return ['roles' => $user->roles()->orderBy('name')->pluck('name')->all(),
 85:             // L-5: البريد مقنّع (أول حرفين + النطاق) — تغيير بريد موظف
 86:             // هو الطريق الطبيعي للاستيلاء على حساب عبر استعادة كلمة
 87:             // المرور، فلا بد أن يظهر في before/after، لكن بلا قيمة كاملة.
 88:             'email' => self::maskEmail($user->email),
 89:             'branch_id' => $user->branch_id, 'is_active' => (bool) $user->is_active];
 90:     }
 91: 
 92:     /**
 93:      * Capture snapshot of role definition and its assigned permissions.
 94:      *
 95:      * @return array{name: string, permissions: list<string>}
 96:      */
 97:     /** @return array{name: string, is_active: bool} */
 98:     public static function mayGrantPermissions(?User $actor, array $permissions): bool
 99:     {
100:         if (! $actor instanceof User) {
101:             return false;
102:         }
103:         $actor->unsetRelation('roles')->unsetRelation('permissions');
104: 
105:         return $actor->hasRole(StaffRole::SuperAdmin->value, 'staff') || $actor->hasAllPermissions(array_values(array_unique($permissions)));
106:     }
107: 
108:     /** @param list<string> $roles */
109:     public static function mayManageUser(mixed $actor, ?User $target = null, array $roles = []): bool
110:     {
111:         if (! $actor instanceof User) {
112:             return false;
113:         }
114:         $actor->unsetRelation('roles')->unsetRelation('permissions');
115:         if ($target?->is_system) {
116:             return false;
117:         }
118:         if ($actor->hasRole(StaffRole::SuperAdmin->value, 'staff')) {
119:             return true;
120:         }
121:         if (in_array(StaffRole::SuperAdmin->value, $roles, true) || $target?->hasRole(StaffRole::SuperAdmin->value, 'staff')) {
122:             return false;
123:         }
124:         $permissions = Role::query()->where('guard_name', 'staff')->whereIn('name', $roles)->with('permissions')->get()
125:             ->flatMap(fn (Role $role) => $role->permissions->pluck('name'));
126:         if ($target !== null) {
127:             $permissions = $permissions->merge($target->getAllPermissions()->pluck('name'));
128:         }
129: 
130:         return $actor->hasAllPermissions($permissions->unique()->all());
131:     }
