328:                 // M5: تحليل مستند واحد بس في الخطوة (كل واحد ممكن ياخد ~45 ثانية).
329:                 if ($call['name'] === 'inspect_customer_document' && ++$inspections > 1) {
330:                     $responses = array_merge($responses, ToolOutcome::denied('تحليل مستند واحد بس في كل خطوة؛ اطلب الباقي بعدين.', auditable: false)->asFunctionResponse($call)['parts']);
331: 
332:                     continue;
333:                 }
334:                 if ($progress) {
335:                     $progress($this->registry->isWrite($call['name']) ? 'بحسب التأثير وبجهز كارت المراجعة…' : 'بدوّر في البيانات المسموحة ليك…');
336:                 }
337:                 $outcome = $this->registry->dispatch($actor, $conv, $call);
338:                 $response = $outcome->asFunctionResponse($call);
339:                 if ($outcome->type === 'proposal') {
340:                     $response['parts'][0]['functionResponse']['response']['status'] = 'awaiting_confirmation';
341:                 }
342:                 if ($outcome->type === 'picker') {
343:                     $response['parts'][0]['functionResponse']['response'] = ['status' => 'awaiting_selection'];
344:                 }
345:                 $responses = array_merge($responses, $response['parts']);
346:                 $halted = $halted || $outcome->haltsLoop();
347:                 if ($outcome->uiBlock) {
348:                     if ($outcome->type === 'data') {
349:                         $readBlocks[] = $outcome->uiBlock;
350:                     } else {
351:                         $blocks[] = $outcome->uiBlock;
352:                     }
353:                 }
354:                 if ($outcome->type === 'denied') {
355:                     $denials[] = $outcome->message;
356:                 }
357:             }
358:             foreach ($excessCalls as $call) {
359:                 $responses = array_merge($responses, ToolOutcome::denied('عدد الاستدعاءات في الخطوة تجاوز الحد ('.self::MAX_CALLS_PER_STEP.')؛ قسّم الطلب على خطوات.', auditable: false)->asFunctionResponse($call)['parts']);
360:             }
361:             AiMessage::create(['conversation_id' => $conv->id, 'role' => 'tool', 'provider_parts' => $this->cappedToolResponses($responses)]);
362:             $history[] = ['role' => 'user', 'parts' => $this->cappedToolResponses($responses)];
363:             if ($halted) {
364:                 $blocks = array_merge($readBlocks, $blocks);
365:                 $replyText = implode("\n", array_filter([$res['text'], ...$denials]));
366:                 $modelMsg->forceFill(['content' => $replyText ?: null, 'ui_blocks' => $blocks])->save();
367: 
368:                 return new AgentReply($replyText, $blocks, $modelMsg->id);
369:             }
370:         }
371:         $msg = AiMessage::create(['conversation_id' => $conv->id, 'role' => 'model', 'content' => 'محتاج توضيح أكتر عشان أكمل.']);
372: 
373:         return new AgentReply('محتاج توضيح أكتر عشان أكمل.', [], $msg->id);
374:     }
