376:     /** @return array{name:string,args:array<string,mixed>}|null */
377:     private function financeShortcut(string $text): ?array
378:     {
379:         if (preg_match('/\Aجهّز دفعة تحويل فائض الأدراج للرئيسية(?: للفرع رقم ([1-9][0-9]{0,17}))?\z/u', $text, $matches)) {
380:             $args = ['drawer_surplus' => true];
381:             if (isset($matches[1])) {
382:                 $args['branch_id'] = (int) $matches[1];
383:             }
384: 
385:             return ['name' => 'bulk_actions', 'args' => $args];
386:         }
387:         if (preg_match('/\Aجهّز تحويل خزينة عكسي للتحويل المعتمد رقم ([1-9][0-9]{0,17})\z/u', $text, $matches)) {
388:             return ['name' => 'create_treasury_transfer', 'args' => ['reverse_transfer_id' => (int) $matches[1]]];
389:         }
390: 
391:         return null;
392:     }
