394:     /**
395:      * M3: رد تجاوز سقف توكنز الدورة. يُستدعى من فحصين: فحص بداية الخطوة
396:      * (يحسب من قاعدة البيانات فيشمل توكنز الرؤية) وفحص ما بعد الاستكمال
397:      * (يشمل استهلاك الاستكمال الحالي).
398:      */
399:     private function cycleCapReply(AiConversation $conv, array $readBlocks, int $cycleCap, ?int $messageId = null): AgentReply
400:     {
401:         $text = 'الطلب ده استنزف سقف التوكنز للدورة ('.$cycleCap.') فاتوقفت. جرّب طلب أقصر أو اقتسمه.';
402:         $blocks = array_merge($readBlocks, [['type' => 'notice', 'message' => 'الدورة نفدت سقف التوكنز ('.$cycleCap.' توكن) واتوقفت قبل إتمام الطلب.']]);
403:         $messageId ??= AiMessage::create([
404:             'conversation_id' => $conv->id,
405:             'role' => 'model',
406:             'content' => $text,
407:             'ui_blocks' => $blocks,
408:         ])->id;
409: 
410:         return new AgentReply($text, $blocks, $messageId);
