 29:     public function confirm(User $actor, AiPendingAction $action, ?string $typed = null, ?array $selectedItems = null): ToolOutcome
 30:     {
 31:         if ($action->tool === 'bulk_actions') {
 32:             return $this->confirmBulk($actor, $action, $typed, $selectedItems);
 33:         }
 34:         $toolInstance = $this->registry->toolInstance($action->tool);
 35:         if ($toolInstance instanceof ExecutesOutsideTransaction && $toolInstance->executesOutsideTransaction($action)) {
 36:             return $this->confirmOutsideTransaction($actor, $action, $typed, $toolInstance);
 37:         }
 38:         try {
 39:             $result = DB::transaction(function () use ($actor, $action, $typed, $selectedItems) {
 40:                 $this->lockForAction($action->tool);
 41:                 $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
 42:                 try {
 43:                     return $this->confirmLocked($actor, $locked, $typed, $selectedItems);
 44:                 } catch (HttpExceptionInterface $e) {
 45:                     return $e;
 46:                 }
 47:             });
 48:         } catch (\Throwable $e) {
 49:             // M-3: unexpected errors must not leave the proposal stuck in
 50:             // pending — record the failure outside the rolled-back transaction.
 51:             if (! $e instanceof HttpExceptionInterface) {
 52:                 AiPendingAction::whereKey($action->id)->where('status', 'pending')
 53:                     ->update(['status' => 'failed', 'result' => ['message' => 'تعذّر التنفيذ بسبب خطأ غير متوقع؛ اطلب اقتراحًا جديدًا.']]);
 54:             }
 55:             throw $e;
 56:         }
 57:         if ($result instanceof \Throwable) {
 58:             throw $result;
 59:         }
 60: 
 61:         return $result;
 62:     }
