 64:     private function confirmOutsideTransaction(User $actor, AiPendingAction $action, ?string $typed, WriteTool $tool): ToolOutcome
 65:     {
 66:         $claim = DB::transaction(function () use ($actor, $action, $typed) {
 67:             $this->lockForAction($action->tool);
 68:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
 69:             try {
 70:                 return $this->confirmLocked($actor, $locked, $typed);
 71:             } catch (HttpExceptionInterface $e) {
 72:                 return $e;
 73:             }
 74:         });
 75:         if ($claim instanceof \Throwable) {
 76:             throw $claim;
 77:         }
 78:         if ($claim instanceof ToolOutcome && $claim->type !== 'claimed') {
 79:             return $claim;
 80:         }
 81: 
 82:         try {
 83:             $outcome = $tool->execute($actor, $action->fresh() ?? $action);
 84:         } catch (\Throwable $e) {
 85:             DB::transaction(function () use ($action, $e): void {
 86:                 $locked = AiPendingAction::query()->lockForUpdate()->find($action->id);
 87:                 if ($locked && $locked->status === 'confirmed') {
 88:                     $message = ($e instanceof BusinessException || $e instanceof ValidationException)
 89:                         ? ($e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage())
 90:                         : 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.';
 91:                     $this->markFailed($locked, $message ?: 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.');
 92:                 }
 93:             });
 94:             if ($e instanceof BusinessException && $e->status === 409) {
 95:                 abort(409, $e->getMessage());
 96:             }
 97:             if ($e instanceof HttpExceptionInterface) {
 98:                 throw $e;
 99:             }
100:             if ($e instanceof BusinessException || $e instanceof ValidationException) {
101:                 $msg = $e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage();
102: 
103:                 return ToolOutcome::result(false, $msg ?: 'تعذّر التنفيذ.');
104:             }
105:             throw $e;
106:         }
107: 
108:         return DB::transaction(function () use ($action, $outcome): ToolOutcome {
109:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
110:             if ($locked->status === 'confirmed') {
111:                 return $this->finalizeAction($locked, $outcome);
112:             }
113: 
114:             return ToolOutcome::wrap($outcome->type, $outcome->data, $outcome->uiBlock, $outcome->message);
115:         });
116:     }
