118:     private function confirmBulk(User $actor, AiPendingAction $action, ?string $typed, ?array $selectedItems): ToolOutcome
119:     {
120:         $claim = DB::transaction(function () use ($actor, $action, $typed, $selectedItems) {
121:             StaffAdministration::lock();
122:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
123:             abort_unless($locked->user_id === $actor->id, 403);
124:             $this->authorizeTool($actor, $locked);
125:             if ($locked->status === 'executed') {
126:                 return ToolOutcome::result((bool) ($locked->result['ok'] ?? false), $locked->result['message'], $locked->result);
127:             }
128:             abort_unless($locked->status === 'pending' && $locked->expires_at->isFuture(), 409, 'العملية الجماعية مش متاحة للتنفيذ.');
129:             abort_unless(trim((string) $typed) === 'تنفيذ', 422, 'اكتب تنفيذ لتأكيد المجموعة.');
130:             $ids = $locked->args['action_ids'];
131:             $selected = $selectedItems ?? $ids;
132:             abort_if(! $selected || array_diff($selected, $ids) !== [] || count(array_unique($selected)) !== count($selected), 422);
133:             $locked->forceFill(['status' => 'confirmed'])->save();
134:             // M-4: المختارون فقط يتحولون لـ pending، والباقون يُلغون في نفس
135:             // الـ transaction — فلا نافذة سباق لتأكيد مستبعد من تبويب آخر،
136:             // ولا أيتام pending لو انهارت العملية بعد الـ claim.
137:             AiPendingAction::query()->whereIn('id', $selected)->where('status', 'bulk_child')->update(['status' => 'pending']);
138:             AiPendingAction::query()->whereIn('id', array_diff($ids, $selected))->whereIn('status', ['bulk_child', 'pending'])->update(['status' => 'cancelled']);
139: 
140:             return ['selected' => $selected, 'all' => $ids];
141:         });
142:         if ($claim instanceof ToolOutcome) {
143:             return $claim;
144:         }
145:         $results = [];
146:         foreach ($claim['selected'] as $id) {
147:             $child = AiPendingAction::query()->where('conversation_id', $action->conversation_id)->where('user_id', $actor->id)->findOrFail($id);
148:             try {
149:                 // M-5: set_branch_status خرج من الـ bulk نهائيًا (كان نص
150:                 // "تنفيذ" واحد يؤكد تعطيل فروع، والحماية بالكود المكتوب
151:                 // تُلغى من السيرفر بتعبئة تلقائية — residual risk M10).
152:                 // لا تعبئة تلقائية لأي نص تأكيد هنا: أي عنصر عالي الخطورة
153:                 // في مجموعة قديمة بلا نص مدخل من المستخدم يفشل برسالة
154:                 // واضحة بدل تنفيذه بتعبئة من السيرفر.
155:                 $outcome = $this->confirm($actor, $child, null);
156:                 $results[] = ['action_id' => $id, 'ok' => $outcome->type === 'result', 'message' => $outcome->message];
157:             } catch (QueryException $e) {
158:                 if (! $this->isRetryableLockFailure($e)) {
159:                     report($e);
160:                     AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
161:                     $results[] = ['action_id' => $id, 'ok' => false, 'message' => 'تعذّر تنفيذ العنصر ده ضمن الدفعة؛ راجع التفاصيل أو جرّبه لوحده.'];
162: 
163:                     continue;
164:                 }
165:                 $this->retryBulkConflict($action, $claim, $results);
166:             } catch (RetryableConflict $e) {
167:                 // H2: قفل/تايم-أوت من confirmLocked أو StaffAdministration::lock
168:                 // يصل هنا كاستثناء مخصص — نفس مسار إعادة المحاولة، لا failed.
169:                 $this->retryBulkConflict($action, $claim, $results);
170:             } catch (\Throwable $e) {
171:                 if (! $e instanceof HttpExceptionInterface && ! $e instanceof ValidationException) {
172:                     report($e);
173:                 }
174:                 AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
175:                 $results[] = ['action_id' => $id, 'ok' => false, 'message' => 'تعذّر تنفيذ العنصر ده ضمن الدفعة؛ راجع التفاصيل أو جرّبه لوحده.'];
176:             }
177:         }
178:         $successes = count(array_filter($results, fn ($item) => $item['ok']));
179:         $ok = $successes === count($results);
180:         $message = 'تم تنفيذ '.$successes.' من '.count($results).' عمليات.';
181:         // L4: الأب الفاشل كليًا يُوسم failed لا executed — وإلا usage()
182:         // والتقارير تحسبه نجاحًا.
183:         $parentStatus = $successes === 0 ? 'failed' : 'executed';
184:         $action->refresh()->forceFill(['status' => $parentStatus, 'executed_at' => now(), 'result' => ['ok' => $ok, 'message' => $message, 'items' => $results]])->save();
185:         $block = ['type' => 'result', 'ok' => $ok, 'message' => $message, 'items' => $results];
186:         $this->event($action, 'result', $message, [$block]);
187: 
188:         return ToolOutcome::result($ok, $message, ['items' => $results], $block);
189:     }
