191:     /**
192:      * H2: تعارض مؤقت أثناء تأكيد عنصر جماعي — الأب يرجع pending
193:      * (قابل للتأكيد من جديد)، والعنصر الحالي يبقى pending، ولا شيء يوسم
194:      * failed. تُرمى 409 دائمًا بعد تسجيل حدث النتيجة.
195:      *
196:      * @param  array{selected:list<string>,all:list<string>}  $claim
197:      * @param  list<array{action_id:string,ok:bool,message:string}>  $results
198:      */
199:     private function retryBulkConflict(AiPendingAction $action, array $claim, array $results): never
200:     {
201:         AiPendingAction::whereKey($action->id)->where('status', 'confirmed')->update(['status' => 'pending']);
202:         $done = count(array_filter($results, fn ($item) => $item['ok']));
203:         $message = $done === 0
204:             ? 'السجل مشغول بتعديل تاني؛ مفيش حاجة اتنفذت. جرّب تأكيد الدفعة تاني بعد لحظة.'
205:             : 'السجل مشغول بتعديل تاني؛ العناصر المنفذة: '.$done.' من '.count($claim['selected']).'. الباقي ما اتنفذش — جرّب تأكيد الدفعة تاني بعد لحظة.';
206:         $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
207:         abort(409, $message);
208:     }
