210:     /**
211:      * M7: القفل الاستشاري العام لأدوات إدارة الموظفين فقط. أدوات
212:      * الكتالوج والمخزون تعتمد على أقفالها الخاصة (CatalogLock::tree +
213:      * أقفال الصفوف، أو InventoryService::lockLevels بترتيب ثابت)، فأخذ
214:      * القفل العام عند تأكيدها كان يسلسل كل شيء خلف أثقل عملية.
215:      */
216:     private function lockForAction(string $tool): void
217:     {
218:         $def = $this->registry->definitions()[$tool] ?? null;
219:         $provider = $def['provider'] ?? null;
220:         if ($provider instanceof ToolProvider && ! $provider->usesGlobalAdminLock()) {
221:             return;
222:         }
223:         StaffAdministration::lock();
224:     }
