226:     private function authorizeTool(User $actor, AiPendingAction $action): void
227:     {
228:         $actor->refresh();
229:         abort_unless($this->settings->getBool('ai_enabled', false), 403, 'المساعد مقفول.');
230:         $disabled = $this->settings->get('ai_disabled_tools', []);
231:         abort_if(is_array($disabled) && in_array($action->tool, $disabled, true), 403, 'الأداة مقفولة من الإعدادات.');
232:         abort_if($this->registry->isCustomerTool($action->tool) && ! $this->registry->customerToolsEnabled(), 403, 'أدوات العملاء مقفولة من الإعدادات.');
233:         abort_if($this->registry->toolHiddenByFlags($action->tool), 403, 'الأداة مقفولة من الإعدادات.');
234:         $def = $this->registry->definitions()[$action->tool] ?? null;
235:         abort_unless($def && $actor->is_active && $actor->can('ai_agent.use') && $actor->can('ai_agent.execute') && $this->registry->actorHasToolPermissions($actor, $action->tool, $def), 403);
236:         abort_unless($action->conversation()->exists(), 409, 'المحادثة اتحذفت.');
237:         abort_unless(hash_equals($action->args_hash, $this->registry->hashArgs($action->args)), 409, 'بيانات الإجراء اتغيرت.');
238:     }
