240:     private function confirmLocked(User $actor, AiPendingAction $action, ?string $typed, ?array $selectedItems = null): ToolOutcome
241:     {
242:         abort_unless($action->user_id === $actor->id, 403);
243:         $this->authorizeTool($actor, $action);
244:         if ($action->status === 'executed') {
245:             return ToolOutcome::result(true, 'اتنفذ قبل كده.', $action->result ?? []);
246:         }
247:         abort_unless($action->status === 'pending', 409, 'الإجراء مش في حالة انتظار.');
248:         if ($action->expires_at->isPast()) {
249:             $action->forceFill(['status' => 'expired'])->save();
250:             abort(409, 'انتهت صلاحية كارت التأكيد.');
251:         }
252:         if (! hash_equals($action->args_hash, $this->registry->hashArgs($action->args))) {
253:             abort(409, 'بيانات الإجراء اتغيرت.');
254:         }
255:         abort_unless($this->settings->getBool('ai_enabled', false), 403, 'المساعد مقفول.');
256:         // re-check execute + original permission
257:         $defs = $this->registry->definitions();
258:         $def = $defs[$action->tool] ?? null;
259:         abort_unless($def && $actor->can('ai_agent.execute') && $this->registry->actorHasToolPermissions($actor, $action->tool, $def), 403);
260:         if ($action->risk === 'high') {
261:             $preview = $action->preview ?? [];
262:             [$expectedTyped, $typedHint] = ProposalBuilder::resolveTypedConfirmation($action->tool, $action->args ?? [], $preview);
263:             $typedInstruction = null;
264:             if (in_array($action->tool, ['approve_dealer_application', 'reject_dealer_application', 'suspend_customer', 'set_credit_limit'], true)) {
265:                 $typedInstruction = 'اكتب آخر 4 أرقام من موبايل التاجر.';
266:             } elseif ($action->tool === 'adjust_customer_wallet') {
267:                 $typedInstruction = 'اكتب آخر 4 أرقام من موبايل العميل.';
268:             } elseif ($typedHint !== null && $typedHint !== '') {
269:                 $typedInstruction = 'اكتب '.$typedHint.': '.$expectedTyped;
270:             }
271:             // L-9: مطابقة متسامحة (trim + توحيد حالة) بدل الحرفية الصارمة.
272:             $norm = fn (?string $v): ?string => $v === null ? null : mb_strtolower(trim($v));
273:             if ($expectedTyped !== null && $typed !== null && $norm($typed) !== $norm($expectedTyped)) {
274:                 abort(422, 'نص التأكيد مش مطابق.');
275:             }
276:             if ($expectedTyped !== null && ($typed === null || trim($typed) === '')) {
277:                 abort(422, $typedInstruction ?? 'اكتب نص التأكيد المطلوب: '.$expectedTyped);
278:             }
279:         }
280:         $tool = $this->registry->toolInstance($action->tool);
281:         if ($tool instanceof ExecutesOutsideTransaction && $tool->executesOutsideTransaction($action)) {
282:             $action->forceFill(['status' => 'confirmed'])->save();
283: 
284:             return ToolOutcome::wrap('claimed');
285:         }
286:         $via = ['channel' => 'ai', 'conversation_id' => $action->conversation_id, 'action_id' => $action->id];
287:         try {
288:             $outcome = DB::transaction(function () use ($actor, $action, $via, $selectedItems) {
289:                 $this->registry->lockTargets($action);
290: 
291:                 return $this->registry->executeWrite($actor, $action, $via, $selectedItems);
292:             });
293:         } catch (UniqueConstraintViolationException) {
294:             // M14: 23505 بتصل برا الـ savepoint — الإجراء يتاخد failed برسالة
295:             // مفهومة بدل 500 والإجراء يتعلق pending للأبد.
296:             $message = 'قيمة مشتركة (كود فرع أو موقع/بريد) اتحجزت لحظة الحفظ. اطلب اقتراح جديد.';
297:             $action->forceFill(['status' => 'failed', 'result' => ['message' => $message, 'conflict_409' => true]])->save();
298:             $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
299:             abort(409, $message);
300:         } catch (BusinessException|ValidationException $e) {
301:             if ($e instanceof BusinessException && $e->status === 409) {
302:                 $message = $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح. تحب أجهّز اقتراح جديد؟';
303:                 $action->forceFill(['status' => 'failed', 'result' => ['message' => $message, 'conflict_409' => true]])->save();
304:                 $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
305:                 abort(409, $message);
306:             }
307:             if ($e instanceof BusinessException && $e->status === 403) {
308:                 $message = $e->getMessage() ?: 'صلاحيتك على السجل ده اتغيرت بعد الاقتراح؛ اطلب اقتراحًا جديدًا.';
309:                 $this->markFailed($action, $message);
310: 
311:                 return ToolOutcome::result(false, $message);
312:             }
313:             // M-5: خطأ عمل مفهوم (تعطيل مرفوض/تحقق) يُحوَّل لفشل مسجَّل بدل
314:             // إلغاء الـ transaction الخارجية وبقاء الإجراء pending للأبد.
315:             $message = $e instanceof ValidationException
316:                 ? collect($e->errors())->flatten()->implode(' ')
317:                 : $e->getMessage();
318:             $message = trim((string) $message) !== '' ? $message : 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.';
319:             $action->forceFill(['status' => 'failed', 'result' => ['message' => $message]])->save();
320:             $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
321: 
322:             return ToolOutcome::result(false, $message);
323:         } catch (AuthorizationException|ModelNotFoundException|RoleAlreadyExists $e) {
324:             $message = match (true) {
325:                 $e instanceof AuthorizationException => 'صلاحيتك على السجل ده اتغيرت بعد الاقتراح؛ اطلب اقتراحًا جديدًا.',
326:                 $e instanceof ModelNotFoundException => 'السجل المطلوب لم يعد موجودًا؛ اطلب اقتراحًا جديدًا.',
327:                 default => trim((string) $e->getMessage()) !== '' ? $e->getMessage() : 'القيمة المطلوبة موجودة بالفعل؛ اطلب اقتراحًا جديدًا.',
328:             };
329:             $this->markFailed($action, $message);
330: 
331:             return ToolOutcome::result(false, $message);
332:         } catch (QueryException $e) {
333:             // M1: كتلة QueryException واحدة. قفل/deadlock → RetryableConflict
334:             // (409 قابل لإعادة المحاولة) من غير وسم failed (الـ savepoint
335:             // اتراجع ومفيش حالة اتغيرت). غير كده → failed برسالة مفهومة.
336:             if (in_array($e->errorInfo[0] ?? null, ['55P03', '40P01', '40001'], true) || $this->isRetryableLockFailure($e)) {
337:                 throw new RetryableConflict('السجل مشغول بتعديل تاني؛ مفيش حاجة اتنفذت. جرّب التأكيد تاني بعد لحظة.', $e);
338:             }
339:             report($e);
340:             $message = match ($e->errorInfo[0] ?? null) {
341:                 '23514' => 'البيانات مش مستوفية لشروط الحفظ (مثلاً بيانات قانونية ناقصة)؛ كمّلها واطلب اقتراح جديد.',
342:                 '23503' => 'سجل مرتبط بالإجراء اتغير أو اتحذف؛ اطلب اقتراح جديد.',
343:                 default => 'تعذّر التنفيذ بسبب خطأ في قاعدة البيانات؛ اطلب اقتراح جديد.',
344:             };
345:             $this->markFailed($action, $message);
346: 
347:             return ToolOutcome::result(false, $message);
348:         } catch (HttpExceptionInterface $e) {
349:             if ($e->getStatusCode() === 409) {
350:                 // H2: التعارض القابل لإعادة المحاولة لا يوسم failed — مفيش
351:                 // حالة اتغيرت، وإعادة التأكيد بعد لحظة كافية.
352:                 if (! $e instanceof RetryableConflict) {
353:                     $action->forceFill(['status' => 'failed', 'result' => ['message' => $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح. تحب أجهّز اقتراح جديد؟', 'conflict_409' => true]])->save();
354:                     $this->event($action, 'result', $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح.', [['type' => 'result', 'ok' => false, 'message' => $e->getMessage() ?: 'حد عدّل السجل ده بعد الاقتراح.']]);
355:                 }
356:             }
357:             throw $e;
358:         }
359: 
360:         return $this->finalizeAction($action, $outcome);
361:     }
362: 
363:     private function finalizeAction(AiPendingAction $action, ToolOutcome $outcome): ToolOutcome
364:     {
365:         $ok = $outcome->type === 'result';
366:         $storedResult = $outcome->data;
367:         unset($storedResult['generated_password']);
368:         // الأدوات قد تحفظ مراجع أنشأتها أثناء التنفيذ (مثل مسودة تحويل)
369:         // في expected_versions — حدّث النسخة قبل حساب حالة التراجع.
370:         $action->refresh();
371:         if ($ok && $this->registry->canUndo($action)) {
372:             $storedResult['undo_state'] = $this->registry->targetState($action);
373:         }
374:         $action->forceFill(['status' => $ok ? 'executed' : 'failed', 'result' => array_merge($storedResult, ['message' => $outcome->message]), 'executed_at' => $ok ? now() : null])->save();
375:         // Strip generated password from stored result? Keep only in response block, remove from result json
376:         $block = $outcome->uiBlock;
377:         if ($block) {
378:             $blocks = [$block];
379:             if ($ok && $this->registry->canUndo($action)) {
380:                 $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
381:                 $blocks[0]['undo_action_id'] = $action->id;
382:             }
383:         } else {
384:             $blocks = [['type' => 'result', 'ok' => $ok, 'message' => $outcome->message ?? '']];
385:             if ($ok && $this->registry->canUndo($action)) {
386:                 $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
387:                 $blocks[0]['undo_action_id'] = $action->id;
388:             }
389:         }
390:         $this->event($action, 'result', $outcome->message ?? '', $blocks, stripPassword: in_array($action->tool, ['create_staff_user', 'create_customer'], true));
391: 
392:         return ToolOutcome::wrap($outcome->type, $outcome->data, $blocks[0] ?? null, $outcome->message);
393:     }
394: 
395:     public function cancel(User $actor, AiPendingAction $action): AiPendingAction
396:     {
397:         abort_unless($action->user_id === $actor->id, 403);
398: 
399:         return DB::transaction(function () use ($actor, $action): AiPendingAction {
400:             $this->lockForAction($action->tool);
401:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
402:             if ($locked->status === 'pending') {
403:                 $locked->forceFill(['status' => 'cancelled'])->save();
404:                 if ($locked->tool === 'bulk_actions') {
405:                     // M10: الإجراءات الفرعية بتنقفل مع الخبّة الجماعية.
406:                     AiPendingAction::query()->where('user_id', $actor->id)->where('conversation_id', $locked->conversation_id)->whereIn('id', $locked->args['action_ids'])->whereIn('status', ['pending', 'bulk_child'])->update(['status' => 'cancelled']);
407:                 }
408:                 $this->event($locked, 'result', 'تم إلغاء الإجراء '.$locked->id, [['type' => 'result', 'ok' => true, 'message' => 'تم إلغاء الإجراء.']]);
409:             }
410: 
411:             return $locked;
412:         });
413:     }
414: 
415:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
416:     {
417:         // L-6: فحص الملكية قبل قفل الصفوف — لا قفل لصفوف إجراء لا يملكه المستخدم.
418:         abort_unless($action->user_id === $actor->id, 403);
419: 
420:         return DB::transaction(function () use ($actor, $action) {
421:             $this->lockForAction($action->tool);
422:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
423:             abort_unless($locked->user_id === $actor->id, 403);
424:             $this->registry->lockTargets($locked);
425: 
426:             return $this->undoLocked($actor, $locked);
427:         });
428:     }
429: 
430:     private function undoLocked(User $actor, AiPendingAction $action): ToolOutcome
431:     {
432:         abort_unless($action->user_id === $actor->id, 403);
433:         $this->authorizeTool($actor, $action);
434:         abort_unless($this->registry->canUndo($action), 409);
435:         abort_unless(isset($action->result['undo_state']) && hash_equals($action->result['undo_state'], $this->registry->targetState($action)), 409, 'السجل اتعدل بعد التنفيذ؛ التراجع مش آمن.');
436:         abort_unless($action->status === 'executed' && $action->executed_at && $action->executed_at->copy()->addMinutes(15)->isFuture(), 409, 'التراجع مش متاح.');
437:         abort_unless($actor->can('ai_agent.execute'), 403);
438:         $via = ['channel' => 'ai', 'conversation_id' => $action->conversation_id, 'action_id' => $action->id];
439:         try {
440:             $outcome = DB::transaction(fn () => $this->registry->executeUndo($actor, $action, $via));
441:         } catch (BusinessException $e) {
442:             if ($e->status === 409) {
443:                 $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
444:                 abort(409, $e->getMessage());
445:             }
446: 
447:             return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التراجع.');
448:         } catch (HttpExceptionInterface $e) {
449:             if ($e->getStatusCode() === 409) {
450:                 $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
451:                 throw $e;
452:             } throw $e;
453:         }
454:         if ($outcome->type === 'result') {
455:             $action->forceFill(['status' => 'undone'])->save();
456:             $this->event($action, 'result', 'تم التراجع.', [['type' => 'result', 'ok' => true, 'message' => 'تم التراجع.']]);
457:         }
458: 
459:         return $outcome;
460:     }
461: 
462:     private function isRetryableLockFailure(QueryException $e): bool
463:     {
464:         return in_array((string) $e->getCode(), ['55P03', '40P01'], true);
465:     }
466: 
467:     /**
468:      * M-3: وسم الإجراء failed برسالة واضحة + حدث نتيجة — بدل بقائه
469:      * pending للأبد بعد استثناء غير مصنّف.
470:      */
471:     private function markFailed(AiPendingAction $action, string $message): void
472:     {
473:         $action->forceFill(['status' => 'failed', 'result' => ['message' => $message]])->save();
474:         $this->event($action, 'result', $message, [['type' => 'result', 'ok' => false, 'message' => $message]]);
475:     }
476: 
477:     private function event(AiPendingAction $action, string $kind, string $text, array $blocks, bool $stripPassword = false): void
478:     {
479:         if ($stripPassword) {
480:             // L8: لا تعتمد على regex فوق صياغة عربية قد تتغير — المؤقتة
481:             // تُعرض مرة واحدة في رد التأكيد فقط، والمخزّن نص ثابت.
482:             $created = $action->tool === 'create_customer' ? 'العميل' : 'الموظف';
483:             $text = "تم إنشاء {$created} (الباسورد ظهر للأدمن مرة واحدة).";
484:             $blocks = array_map(function ($b) use ($created) {
485:                 if (isset($b['message'])) {
486:                     $b['message'] = "تم إنشاء {$created}.";
487:                 }
488:                 if (isset($b['generated_password'])) {
489:                     unset($b['generated_password']);
490:                 }
491: 
492:                 return $b;
493:             }, $blocks);
494:         }
495:         AiMessage::create(['conversation_id' => $action->conversation_id, 'role' => 'event', 'content' => $text, 'ui_blocks' => $blocks]);
496:     }
