135:     public function withValidator(Validator $validator): void
136:     {
137:         $allowedKeys = array_values(array_filter(array_keys($this->rules()), fn ($key) => ! str_starts_with($key, 'expected.')));
138:         $body = $this->validationData();
139:         $unknownKeys = array_diff(array_keys($body), $allowedKeys, ['_method', '_token']);
140: 
141:         $validator->after(function (Validator $validator) use ($unknownKeys, $body): void {
142:             $changed = array_diff(array_keys($body), ['expected', '_method', '_token']);
143:             $expected = is_array($body['expected'] ?? null) ? $body['expected'] : [];
144:             foreach (array_diff($changed, array_keys($expected)) as $key) {
145:                 $validator->errors()->add('expected.'.$key, 'القيمة الأصلية مطلوبة لهذا الإعداد.');
146:             }
147:             foreach (array_diff(array_keys($expected), $changed) as $key) {
148:                 $validator->errors()->add('expected.'.$key, 'قيمة أصلية غير مرتبطة بإعداد معدل.');
149:             }
150:             foreach ($unknownKeys as $unknownKey) {
151:                 $validator->errors()->add($unknownKey, 'إعداد غير معروف.');
152:             }
153:         });
154:     }
