  72: final class ToolRegistry
  73: {
  74:     private ProposalBuilder $proposals;
  75: 
  76:     /**
  77:      * @param  iterable<ToolProvider>  $providers
  78:      */
  79:     public function __construct(
  80:         private EntityResolver $resolver,
  81:         private BranchAccess $branches,
  82:         private SettingService $settings,
  83:         private iterable $providers = [],
  84:         ?ProposalBuilder $proposals = null,
  85:     ) {
  86:         $this->proposals = $proposals ?? new ProposalBuilder($this->settings);
  87:     }
  88: 
  89:     /** @return iterable<ToolProvider> */
  90:     public function providers(): iterable
  91:     {
  92:         return $this->providers;
  93:     }
  94: 
  95:     public function toolInstance(string $name): ?AgentTool
  96:     {
  97:         $def = $this->definitions()[$name] ?? null;
  98:         if (! $def || ! isset($def['provider'])) {
  99:             return null;
 100:         }
 101: 
 102:         return $def['tool'] ?? ($def['provider']->tools()[$name] ?? null);
 103:     }
 104: 
 105:     /** INFO: التعريفات تُبنى من الصفر في كل نداء وكانت تُستدعى عشرات
 106:      * المرات في الطلب الواحد (من declarationsFor وisWrite وdispatch
 107:      * وauthorizeTool وconfirmLocked، ومنها داخل rules() وauditableSettings()
 108:      * في UpdateSettingsRequest). خزّنها في property — لا حالة طلب
 109:      * داخلها، فهي ثوابت من الـ enums فقط. */
 110:     private ?array $definitionsCache = null;
 111: 
 112:     /** @return array<string, array{kind:ToolKind, permissions:list<string>, declaration:array<string,mixed>, risk:string}> */
 113:     public function definitions(): array
 114:     {
 115:         return $this->definitionsCache ??= $this->buildDefinitions();
 116:     }
 117: 
 118:     /** 6.1: كل أدوات العملاء — تختفي كلها لما ai_customer_tools_enabled=false. */
 119:     public const CUSTOMER_TOOLS = [
 120:         'list_customers', 'get_customer_profile', 'dealer_queue_summary', 'review_dealer_application', 'customer_history',
 121:         'find_duplicate_customers', 'list_customer_groups', 'inspect_customer_document',
 122:         'create_customer', 'update_customer_profile', 'set_customer_group', 'set_credit_limit', 'review_customer_document',
 123:         'approve_dealer_application', 'reject_dealer_application', 'suspend_customer', 'reactivate_customer',
 124:         'restore_customer', 'create_customer_group', 'update_customer_group',
 125:     ];
 126: 
 127:     public function isCustomerTool(string $name): bool
 128:     {
 129:         return in_array($name, self::CUSTOMER_TOOLS, true);
 130:     }
 131: 
 132:     public function customerToolsEnabled(): bool
 133:     {
 134:         return $this->settings->getBool('ai_customer_tools_enabled', false);
 135:     }
 136: 
 137:     /** 5.1: تحليل المستندات مقفول افتراضيًا، وبيحتاج أدوات العملاء مفعّلة كمان. */
 138:     public function documentAnalysisEnabled(): bool
 139:     {
 140:         return $this->customerToolsEnabled() && $this->settings->getBool('ai_document_analysis_enabled', false);
 141:     }
 142: 
 143:     public function toolHiddenByFlags(string $name): bool
 144:     {
 145:         $def = $this->definitions()[$name] ?? null;
 146:         if ($def && isset($def['provider'])) {
 147:             $provider = $def['provider'];
 148:             if (! $provider->enabled()) {
 149:                 return true;
 150:             }
 151:             if (method_exists($provider, 'isToolHidden') && $provider->isToolHidden($name)) {
 152:                 return true;
 153:             }
 154:         }
 155:         if ($this->isCustomerTool($name) && ! $this->customerToolsEnabled()) {
 156:             return true;
 157:         }
 158: 
 159:         return $name === 'inspect_customer_document' && ! $this->documentAnalysisEnabled();
 160:     }
