 257:     /** @return list<array<string,mixed>> */
 258:     public function declarationsFor(User $actor, ?array $domains = null): array
 259:     {
 260:         $disabled = $this->settings->get('ai_disabled_tools', []);
 261:         if (! is_array($disabled)) {
 262:             $disabled = [];
 263:         }
 264:         $out = [];
 265:         foreach ($this->definitions() as $name => $def) {
 266:             if (in_array($name, $disabled, true) || $this->toolHiddenByFlags($name)) {
 267:                 continue;
 268:             }
 269:             if ($domains !== null && ! in_array($name, ['find_entities', 'ask_user_to_choose', 'bulk_actions'], true)) {
 270:                 $toolDomain = $this->domainOf($name, $def);
 271:                 if (! in_array($toolDomain, $domains, true)) {
 272:                     continue;
 273:                 }
 274:             }
 275:             if ($def['kind'] === ToolKind::Write && ! $actor->can('ai_agent.execute')) {
 276:                 continue;
 277:             }
 278:             if (! $this->actorHasToolPermissions($actor, $name, $def)) {
 279:                 continue;
 280:             }
 281:             $out[] = $def['declaration'];
 282:         }
 283: 
 284:         return $out;
 285:     }
