 287:     /**
 288:      * M7: أدوات الكتالوج تأخذ قفل شجرة الكتالوج (CatalogLock) + أقفال
 289:      * الصفوف في الـ services، فلا تحتاج القفل الاستشاري العام — إبقاؤه
 290:      * كان يسلسل كل التأكيدات خلف أثقل عملية كتالوج.
 291:      */
 292:     public function isCatalogTool(string $name): bool
 293:     {
 294:         $def = $this->definitions()[$name] ?? null;
 295: 
 296:         return $def !== null && ($def['provider'] ?? null) instanceof CatalogToolProvider;
 297:     }
 298: 
 299:     public function actorHasToolPermissions(User $actor, string $name, array $def): bool
 300:     {
 301:         if ($name === 'analyze_product_photos') {
 302:             return $actor->can('ai_agent.catalog.vision') && $actor->can('products.create');
 303:         }
 304: 
 305:         $domain = ($def['provider'] ?? null)?->domain();
 306:         if ($domain === 'finance') {
 307:             if (! $actor->can('ai_agent.finance')) {
 308:                 return false;
 309:             }
 310:             if ($name === 'explain_order_money') {
 311:                 return $actor->can('orders.view') && $actor->canAny(array_diff($def['permissions'], ['orders.view']));
 312:             }
 313: 
 314:             return $actor->can($def['permissions']);
 315:         }
 316: 
 317:         if ($domain === 'pricing') {
 318:             return $actor->can($def['permissions']);
 319:         }
 320: 
 321:         return $actor->canAny($def['permissions']);
 322:     }
 323: 
 324:     private function domainOf(string $name, array $def): string
 325:     {
 326:         if (isset($def['provider']) && $def['provider'] instanceof ToolProvider) {
 327:             return $def['provider']->domain();
 328:         }
 329:         if ($this->isCustomerTool($name)) {
 330:             return 'customers';
 331:         }
 332:         if (in_array($name, ['view_settings', 'view_document_numbering', 'update_settings', 'update_document_numbering'], true)) {
 333:             return 'settings';
 334:         }
 335: 
 336:         return 'admin';
 337:     }
