 344:     /** @param array{name:string,args:array<string,mixed>} $call */
 345:     public function dispatch(User $actor, AiConversation $conv, array $call): ToolOutcome
 346:     {
 347:         $outcome = $this->dispatchAllowed($actor, $conv, $call);
 348:         // L11: سجل denied لرفض الصلاحيات فقط — أخطاء التحقق و"مش موجود"
 349:         // من prompt injection كانت تملأ سجل التدقيق (6 خطوات × أدوات).
 350:         if ($outcome->type === 'denied' && $outcome->auditable) {
 351:             StaffAdministration::audit($actor, 'administration.denied', 'ai_conversation', $conv->id, [], via: ['channel' => 'ai', 'conversation_id' => $conv->id]);
 352:         }
 353: 
 354:         return $outcome;
 355:     }
 356: 
 357:     private function dispatchAllowed(User $actor, AiConversation $conv, array $call): ToolOutcome
 358:     {
 359:         $name = $call['name'];
 360:         $args = $call['args'] ?? [];
 361:         $defs = $this->definitions();
 362:         if (! isset($defs[$name])) {
 363:             return ToolOutcome::denied('أداة غير معروفة.', auditable: false);
 364:         }
 365:         $disabled = $this->settings->get('ai_disabled_tools', []);
 366:         if (is_array($disabled) && in_array($name, $disabled, true)) {
 367:             return ToolOutcome::denied('الأداة دي مقفولة من الإعدادات.', auditable: false);
 368:         }
 369:         if ($this->toolHiddenByFlags($name)) {
 370:             return ToolOutcome::denied('الأداة دي مقفولة من الإعدادات.', auditable: false);
 371:         }
 372:         if ($defs[$name]['kind'] === ToolKind::Write && ! $actor->can('ai_agent.execute')) {
 373:             return ToolOutcome::denied('محتاج صلاحية ai_agent.execute لتنفيذ تعديلات.');
 374:         }
 375:         if (! $this->actorHasToolPermissions($actor, $name, $defs[$name])) {
 376:             return ToolOutcome::denied('معندكش الصلاحية الأصلية للأداة دي.');
 377:         }
 378:         try {
 379:             $this->proposals->setConversation($conv);
 380:             if ($name === 'bulk_actions' && ($args['drawer_surplus'] ?? false) === true) {
 381:                 return $this->prepareDrawerSurplus($actor, $conv, $args);
 382:             }
 383:             if (isset($defs[$name]['provider'])) {
 384:                 $tool = $defs[$name]['tool'] ?? $defs[$name]['provider']->tools()[$name];
 385:                 if ($defs[$name]['kind'] === ToolKind::Read) {
 386:                     return $tool->handle($actor, $args);
 387:                 }
 388:                 if ($defs[$name]['kind'] === ToolKind::Write) {
 389:                     return $tool->prepare($actor, $args);
 390:                 }
 391:             }
 392: 
 393:             try {
 394:                 $this->validateArgs($name, $args);
 395:             } catch (ValidationException $e) {
 396:                 return ToolOutcome::denied(collect($e->errors())->flatten()->implode(' '), auditable: false);
 397:             }
 398: 
 399:             return match ($name) {
 400:                 'find_entities' => $this->findEntities($actor, $args),
 401:                 'list_branches' => $this->entityTable('branches', $this->resolver->branches($actor, '', $args)),
 402:                 'list_roles' => $this->entityTable('roles', $this->resolver->roles()),
 403:                 'list_permissions' => $this->permissionsTable(),
 404:                 'list_staff' => $this->entityTable('staff', $this->resolver->users($actor, (string) ($args['query'] ?? ''))),
 405:                 'explain_user_access' => $this->explainUser($actor, $args),
 406:                 'who_can' => $this->whoCan($actor, $args),
 407:                 'compare_roles' => $this->compareRoles($args),
 408:                 'recent_audit' => $this->recentAudit($actor, $args),
 409:                 'ask_user_to_choose' => $this->picker($actor, $args),
 410:                 'bulk_actions' => $this->prepareBulk($actor, $conv, $args),
 411:                 'list_locations' => $this->listLocations($actor, $args),
 412:                 'list_customers' => $this->listCustomers($args),
 413:                 'get_customer_profile' => $this->getCustomerProfile($args),
 414:                 'dealer_queue_summary' => $this->dealerQueueSummary($args),
 415:                 'review_dealer_application' => $this->reviewDealerApplication($args),
 416:                 'customer_history' => $this->customerHistory($args),
 417:                 'find_duplicate_customers' => $this->findDuplicateCustomers($args),
 418:                 'list_customer_groups' => $this->listCustomerGroups($args),
 419:                 'inspect_customer_document' => $this->inspectCustomerDocument($actor, $conv, $args),
 420:                 'view_settings' => $this->viewSettings($actor, $args),
 421:                 'view_document_numbering' => $this->viewDocumentNumbering($actor, $args),
 422:                 default => $this->prepareWrite($actor, $conv, $name, $args),
 423:             };
 424:         } catch (ValidationException $e) {
 425:             return ToolOutcome::denied(collect($e->errors())->flatten()->implode(' '), auditable: false);
 426:         } catch (HttpExceptionInterface $e) {
 427:             $auditable = in_array($e->getStatusCode(), [401, 403], true);
 428: 
 429:             return ToolOutcome::denied($e->getMessage() ?: 'مرفوض.', auditable: $auditable);
 430:         } catch (QueryException $e) {
 431:             // M1: داخل معاملة (prepareBulk) ابتلاع خطأ SQL يترك المعاملة
 432:             // ميتة (25P02) — أعد الرمي ليتراجع الـ savepoint الخاص بالعنصر.
 433:             if (DB::transactionLevel() > 0) {
 434:                 throw $e;
 435:             }
 436:             report($e);
 437: 
 438:             return ToolOutcome::denied('حصل خطأ أثناء تنفيذ الأداة.', auditable: false);
 439:         } catch (\InvalidArgumentException $e) {
 440:             // task.txt §2-19: input-shape problems with a clear message
 441:             // (e.g. vision image over 4MB) must reach the user instead of
 442:             // a generic denial — the message carries no secrets by
 443:             // construction, and stays non-auditable.
 444:             return ToolOutcome::denied($e->getMessage() ?: 'مرفوض.', auditable: false);
 445:         } catch (\Throwable $e) {
 446:             report($e);
 447: 
 448:             return ToolOutcome::denied('حصل خطأ أثناء تنفيذ الأداة.', auditable: false);
 449:         }
 450:     }
