 452:     private function entityTable(string $key, array $items): ToolOutcome
 453:     {
 454:         return ToolOutcome::data([$key => $items], ['type' => 'table', 'columns' => ['الرقم', 'الاسم', 'التفاصيل'], 'rows' => array_map(fn ($item) => [$item['id'], $item['label'], $item['meta']], $items)]);
 455:     }
 456: 
 457:     private function permissionsTable(): ToolOutcome
 458:     {
 459:         $names = Permission::query()->where('guard_name', 'staff')->orderBy('name')->pluck('name')->all();
 460: 
 461:         return ToolOutcome::data(['permissions' => $names], ['type' => 'table', 'columns' => ['الصلاحية'], 'rows' => array_map(fn ($name) => [$name], $names)]);
 462:     }
 463: 
 464:     private function validateArgs(string $name, array &$args): void
 465:     {
 466:         if ($name === 'create_role' && is_string($args['name'] ?? null)) {
 467:             $args['name'] = StaffRole::normalizeName($args['name']);
 468:         }
 469:         if ($name === 'create_branch' && is_string($args['code'] ?? null)) {
 470:             $args['code'] = mb_strtoupper(trim($args['code']));
 471:         }
 472:         if ($name === 'create_staff_user' && is_string($args['email'] ?? null)) {
 473:             $args['email'] = mb_strtolower(trim($args['email']));
 474:         }
 475:         if ($name === 'bulk_actions') {
 476:             // 3.1: الاعتماد والرفض ممنوعان في الجماعي صراحة — كل قرار
 477:             // بيبعت إشعار لعميل حقيقي، فلازم يتراجع لوحده. الرفض هنا
 478:             // برسالة عربية واضحة، مش برسالة Rule::in العامة.
 479:             if (is_array($args['items'] ?? null)) {
 480:                 foreach ($args['items'] as $bulkItem) {
 481:                     if (in_array($bulkItem['tool'] ?? null, ['approve_dealer_application', 'reject_dealer_application'], true)) {
 482:                         throw ValidationException::withMessages(['items' => 'الاعتماد والرفض ممنوعان في العمليات الجماعية؛ كل قرار اعتماد أو رفض لازم يتراجع لوحده، لأنه بيبعت إشعار لعميل حقيقي.']);
 483:                     }
 484:                 }
 485:             }
 486:             Validator::make($args, ['items' => ['required', 'array', 'min:2', 'max:'.max(1, (int) $this->settings->get('ai_bulk_max_items', 25))], 'items.*.tool' => ['required', Rule::in(['update_role_permissions', 'set_user_status', 'assign_roles', 'revoke_user_sessions', 'set_location_status', 'create_location', 'set_customer_group', 'set_credit_limit', 'review_customer_document', 'reactivate_customer', 'create_category', 'update_category', 'move_category', 'reorder_categories', 'set_category_status', 'create_product_draft', 'update_product', 'set_product_status', 'add_variants', 'update_variant', 'set_variant_status', 'attach_product_images', 'reorder_product_media', 'delete_product_media', 'adjust_stock', 'approve_transfer'])], 'items.*.args' => ['required', 'array']])->validate();
 487: 
 488:             return;
 489:         }
 490:         $schema = $this->definitions()[$name]['declaration']['parameters'];
 491:         $rules = [];
 492:         foreach ($schema['properties'] as $key => $property) {
 493:             $rules[$key] = [in_array($key, $schema['required'] ?? [], true) ? 'required' : 'sometimes', match ($property['type']) {
 494:                 'INTEGER' => 'integer', 'BOOLEAN' => 'boolean', 'ARRAY' => 'array', 'OBJECT' => 'array', 'NUMBER' => 'numeric', default => 'string'
 495:             }];
 496:             if ($property['type'] === 'STRING') {
 497:                 $rules[$key][] = 'max:255';
 498:             }
 499:             if ($property['type'] === 'INTEGER') {
 500:                 $rules[$key][] = 'min:1';
 501:             }
 502:             if (isset($property['enum'])) {
 503:                 $rules[$key][] = Rule::in($property['enum']);
 504:             }
 505:             if ($property['type'] === 'ARRAY') {
 506:                 $rules[$key][] = 'max:200';
 507:                 $rules[$key.'.*'] = ['string', 'distinct', 'max:255'];
 508:             }
 509:         }
 510:         if (in_array($name, ['create_role', 'update_role_permissions'], true)) {
 511:             foreach (['permissions', 'add', 'remove'] as $key) {
 512:                 if (isset($rules[$key])) {
 513:                     $rules[$key.'.*'][] = Rule::exists('permissions', 'name')->where('guard_name', 'staff');
 514:                 }
 515:             }
 516:         }
 517:         if ($name === 'assign_roles' || $name === 'create_staff_user') {
 518:             foreach (['roles', 'add', 'remove'] as $key) {
 519:                 if (isset($rules[$key])) {
 520:                     $rules[$key.'.*'][] = Rule::exists('roles', 'name')->where('guard_name', 'staff');
 521:                 }
 522:             }
 523:         }
 524:         if ($name === 'create_staff_user') {
 525:             $userRules = (new StoreUserRequest)->rules();
 526:             unset($userRules['password']);
 527:             $rules = array_replace($rules, $userRules);
 528:         }
 529:         if (in_array($name, ['create_customer', 'update_customer_profile'], true) && is_string($args['phone'] ?? null)) {
 530:             // تطبيع الموبايل قبل الـ regex (أرقام عربية، +20/0020) — نفس
 531:             // ما يعمله الـ mutator عند الحفظ، لكن التحقق يسبق الحفظ.
 532:             $args['phone'] = Customer::normalizePhone($args['phone']);
 533:         }
 534:         if ($name === 'create_customer') {
 535:             // دمج قواعد REST لنفس الحقول المعلنة فقط؛ الباسورد مولّد في
 536:             // السيرفر وقت التنفيذ ومش من args أصلًا.
 537:             $customerRules = array_intersect_key((new StoreCustomerRequest)->rules(), array_flip(['name', 'phone', 'email', 'type', 'company_name', 'tax_number', 'commercial_register']));
 538:             $rules = array_replace($rules, $customerRules);
 539:         }
 540:         if ($name === 'update_customer_profile') {
 541:             $customerRules = array_intersect_key((new UpdateCustomerRequest)->rules(), array_flip(['name', 'email', 'phone', 'company_name', 'tax_number', 'commercial_register']));
 542:             // قاعدة REST تتجاهل route('customer') غير الموجود في سياق
 543:             // المساعد — التجاهل هنا هو عميل الأداة نفسه.
 544:             $customerRules['phone'] = ['sometimes', 'string', 'regex:/^01[0125][0-9]{8}$/', Rule::unique('customers', 'phone')->ignore((int) ($args['customer_id'] ?? 0))];
 545:             $customerRules['email'] = ['sometimes', 'nullable', 'email', 'max:255', new EmailNotUsedByOtherAccountType('customers'), new UniqueCustomerEmail((int) ($args['customer_id'] ?? 0))];
 546:             $rules = array_replace($rules, $customerRules);
 547:         }
 548:         if ($name === 'set_customer_group') {
 549:             $rules['customer_group_id'] = ['required', 'integer', Rule::exists('customer_groups', 'id')];
 550:         }
 551:         if ($name === 'set_credit_limit') {
 552:             $rules['credit_limit'] = ['required', 'numeric', 'min:0', 'max:9999999999.99'];
 553:         }
 554:         if ($name === 'review_customer_document') {
 555:             $rules['note'] = ['nullable', 'string', 'max:500', 'required_if:status,rejected'];
 556:         }
 557:         if ($name === 'approve_dealer_application') {
 558:             $approveRules = array_intersect_key((new ApproveCustomerRequest)->rules(), array_flip(['customer_group_id', 'credit_limit', 'type']));
 559:             $rules = array_replace($rules, $approveRules);
 560:             $rules['verify_document_ids.*'] = ['integer', 'distinct', 'min:1'];
 561:         }
 562:         if ($name === 'reject_dealer_application') {
 563:             $rules['reason'] = ['required', 'string', 'max:2000'];
 564:             $rules['reject_document_ids.*'] = ['integer', 'distinct', 'min:1'];
 565:         }
 566:         if ($name === 'suspend_customer') {
 567:             $rules['reason'] = ['required', 'string', 'max:2000'];
 568:         }
 569:         if ($name === 'create_customer_group') {
 570:             $rules = array_replace($rules, (new StoreCustomerGroupRequest)->rules());
 571:         }
 572:         if ($name === 'update_customer_group') {
 573:             $groupRules = (new UpdateCustomerGroupRequest)->rules();
 574:             // نفس مشكلة route() في UpdateCustomerRequest: التجاهل هو
 575:             // مجموعة الأداة نفسها.
 576:             $groupRules['code'] = ['sometimes', 'string', 'max:64', 'alpha_dash', Rule::unique('customer_groups', 'code')->ignore((int) ($args['customer_group_id'] ?? 0))];
 577:             $rules = array_replace($rules, $groupRules);
 578:         }
 579:         if (in_array($name, ['create_location', 'set_location_status'], true) && isset($rules['code'])) {
 580:             // L-8: كود الموقع max:100 في الـ REST — توحيد الحد بين المسارين.
 581:             $rules['code'] = array_map(static fn ($rule) => $rule === 'max:255' ? 'max:100' : $rule, $rules['code']);
 582:         }
 583:         if ($name === 'create_branch') {
 584:             $rules = array_replace($rules, (new StoreBranchRequest)->rules());
 585:         }
 586:         if ($name === 'create_role') {
 587:             $rules = array_replace($rules, (new StoreRoleRequest)->rules());
 588:         }
 589:         if ($name === 'create_location' && isset($rules['code'])) {
 590:             // L-8: كود الموقع max:100 في REST وmax:255 في المساعد — وحّدها
 591:             // على 100. قاعدة الـ unique الكاملة من StoreLocationRequest لا
 592:             // تُطبَّق هنا لأنها تحتاج route('branch') غير موجود في سياق
 593:             // المساعد؛ التفرد مضمون أصلًا بالـ unique index (branch_id, code)
 594:             // وتحذير prepCreateLocation.
 595:             $rules['code'] = ['required', 'string', 'max:100'];
 596:         }
 597:         Validator::make($args, $rules)->validate();
 598:         abort_if(array_diff(array_keys($args), array_keys((array) $schema['properties'])) !== [], 422, 'بيانات أداة غير مسموحة.');
 599:     }
