 601:     private function findEntities(User $actor, array $args): ToolOutcome
 602:     {
 603:         $type = (string) ($args['type'] ?? '');
 604:         $query = (string) ($args['query'] ?? '');
 605:         if (! $this->canReadEntity($actor, $type)) {
 606:             return ToolOutcome::denied('معندكش صلاحية عرض النوع ده.');
 607:         }
 608: 
 609:         return match ($type) {
 610:             'branch' => ToolOutcome::data(['results' => $this->resolver->branches($actor, $query)]),
 611:             'user' => ToolOutcome::data(['results' => $this->resolver->users($actor, $query)]),
 612:             'role' => ToolOutcome::data(['results' => $this->resolver->roles($query)]),
 613:             'location' => ToolOutcome::data(['results' => $this->resolver->locations($actor, $query, isset($args['branch_id']) ? (int) $args['branch_id'] : null)]),
 614:             'customer' => ToolOutcome::data(['results' => $this->resolver->customers($actor, $query)]),
 615:             'customer_group' => ToolOutcome::data(['results' => $this->resolver->customerGroups($query)]),
 616:             'category' => ToolOutcome::data(['results' => $this->resolver->categories($actor, $query)]),
 617:             'product' => ToolOutcome::data(['results' => $this->resolver->products($actor, $query)]),
 618:             'variant' => ToolOutcome::data(['results' => $this->resolver->variants($actor, $query)]),
 619:             'transfer' => ToolOutcome::data(['results' => $this->resolver->transfers($actor, $query)]),
 620:             'stocktake' => ToolOutcome::data(['results' => $this->resolver->stocktakes($actor, $query)]),
 621:             'production_receipt' => ToolOutcome::data(['results' => $this->resolver->productionReceipts($actor, $query)]),
 622:             'price_list' => ToolOutcome::data(['results' => $this->resolver->priceLists($actor, $query)]),
 623:             'coupon' => ToolOutcome::data(['results' => $this->resolver->coupons($query)]),
 624:             'promotion' => ToolOutcome::data(['results' => $this->resolver->promotions($query)]),
 625:             'treasury' => ToolOutcome::data(['results' => $this->resolver->treasuries($actor, $query, isset($args['branch_id']) ? ['branch_id' => (int) $args['branch_id']] : [])]),
 626:             'treasury_transfer' => ToolOutcome::data(['results' => $this->resolver->treasuryTransfers($actor, $query)]),
 627:             'expense' => ToolOutcome::data(['results' => $this->resolver->expenses($actor, $query)]),
 628:             'permission' => ToolOutcome::data(['results' => Permission::query()->where('guard_name', 'staff')->when($query !== '', fn ($q) => $q->where('name', 'ilike', SearchTerm::pattern($query)))->orderBy('name')->limit(50)->get()->map(fn ($p) => ['id' => $p->name, 'label' => $p->name, 'meta' => ''])->values()->all()]),
 629:             default => ToolOutcome::denied('نوع كيان غير معروف.'),
