 633:     private function explainUser(User $actor, array $args): ToolOutcome
 634:     {
 635:         $user = User::query()->where('is_system', false)->find((int) ($args['user_id'] ?? 0));
 636:         if (! $user) {
 637:             return ToolOutcome::denied('الموظف مش موجود.');
 638:         }
 639:         $restricted = null;
 640:         try {
 641:             $restricted = $this->branches->restrictedBranch($actor);
 642:         } catch (\Throwable) {
 643:             return ToolOutcome::denied('النطاق غير مسموح.');
 644:         }
 645:         if ($restricted !== null && (int) $user->branch_id !== $restricted) {
 646:             return ToolOutcome::denied('الموظف خارج نطاق فرعك.');
 647:         }
 648: 
 649:         return ToolOutcome::data(['user' => ['id' => $user->id, 'name' => $user->name, 'email' => $this->resolver->maskEmail($user->email), 'branch_id' => $user->branch_id, 'is_active' => (bool) $user->is_active, 'roles' => $user->roles()->pluck('name')->all(), 'permissions' => $user->getAllPermissions()->pluck('name')->all(), 'can_view_cost' => CostAccess::canView($user)]]);
