 652:     public function canReadEntity(User $actor, string $type): bool
 653:     {
 654:         $handled = false;
 655:         foreach ($this->providers as $p) {
 656:             $res = $p->canReadEntity($actor, $type);
 657:             if ($res !== null) {
 658:                 $handled = true;
 659:                 if ($res) {
 660:                     return true;
 661:                 }
 662:             }
 663:         }
 664:         if ($handled) {
 665:             return false;
 666:         }
 667:         if (in_array($type, ['customer', 'customer_group', 'customer_document'], true) && ! $this->customerToolsEnabled()) {
 668:             return false;
 669:         }
 670:         $permissions = match ($type) {
 671:             'branch' => ['branches.view', 'branches.manage'],
 672:             'user' => ['users.view', 'users.manage'],
 673:             'role' => ['roles.view', 'roles.manage'],
 674:             'permission' => ['permissions.view', 'roles.view', 'roles.manage'],
 675:             'location' => ['locations.view', 'locations.manage'],
 676:             'customer' => ['customers.view'],
 677:             'customer_group' => ['customer_groups.view'],
 678:             'customer_document' => ['customers.documents.view'],
 679:             'transfer' => ['transfers.view'],
 680:             'stocktake' => ['stocktakes.view'],
 681:             'production_receipt' => ['inventory.view'],
 682:             'treasury' => ['treasuries.view'],
 683:             'treasury_transfer' => ['treasury_transfers.view'],
 684:             'expense' => ['expenses.view'],
 685:             default => [],
 686:         };
 687: 
 688:         return $permissions !== [] && $actor->canAny($permissions);
 689:     }
