 691:     private function whoCan(User $actor, array $args): ToolOutcome
 692:     {
 693:         $perm = (string) ($args['permission'] ?? '');
 694:         $roles = Role::query()->where('guard_name', 'staff')->whereHas('permissions', fn ($q) => $q->where('name', $perm))->pluck('name')->all();
 695:         $restricted = $this->branches->restrictedBranch($actor);
 696:         $users = $this->canReadEntity($actor, 'user') ? User::query()->where('is_system', false)->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted))->where(function ($q) use ($roles, $perm) {
 697:             $q->whereHas('roles', fn ($r) => $r->where('guard_name', 'staff')->whereIn('name', $roles))->orWhereHas('permissions', fn ($p) => $p->where('guard_name', 'staff')->where('name', $perm));
 698:         })->pluck('name')->all() : [];
 699: 
 700:         return ToolOutcome::data(['permission' => $perm, 'roles' => $roles, 'users' => $users]);
 701:     }
