 703:     private function compareRoles(array $args): ToolOutcome
 704:     {
 705:         $a = Role::where('guard_name', 'staff')->find((int) ($args['role_a'] ?? 0));
 706:         $b = Role::where('guard_name', 'staff')->find((int) ($args['role_b'] ?? 0));
 707:         if (! $a || ! $b) {
 708:             return ToolOutcome::denied('دور مش موجود.');
 709:         }
 710:         $pa = $a->permissions()->pluck('name')->all();
 711:         $pb = $b->permissions()->pluck('name')->all();
 712: 
 713:         return ToolOutcome::data(['only_a' => array_values(array_diff($pa, $pb)), 'only_b' => array_values(array_diff($pb, $pa)), 'common' => array_values(array_intersect($pa, $pb))]);
 714:     }
