 762:     // ── P04 Customers: طبقة القراءة ──────────────────────────────────────────
 763:     // قاعدة ثابتة: أي حقل كتبه التاجر بنفسه لا يدخل نتيجة الأداة إلا
 764:     // مغلّفًا بـ untrusted()، وأي قيمة كاملة (موبايل/ضريبي/سجل) لا تذهب
 765:     // للنموذج أبدًا — تظهر للأدمن فقط داخل الـ UI block، لأن
 766:     // asFunctionResponse يبعت data بس، والـ block يتخزن في ui_blocks.
 767: 
 768:     /** 1.6: تغليف بيانات كتبها التاجر — لا تُنفَّذ ولا تُعتَبر سبب قرار. */
 769:     private function untrusted(?string $v, int $max = 120): array
 770:     {
 771:         $clean = mb_substr(preg_replace('/[\x00-\x1F\x7F]/u', ' ', (string) $v), 0, $max);
 772: 
 773:         return ['untrusted_text' => $clean];
 774:     }
 775: 
 776:     /**
 777:      * 5.3: اقتراح مجموعة وحد ائتمان بقاعدة شفافة في PHP (مش تخمين نموذج):
 778:      * وسيط حد الائتمان لتجار نفس النوع المعتمدين في آخر 90 يوم، وأكتر
 779:      * مجموعة استخدامًا بينهم. بيرجع null لو مفيش عينة.
 780:      *
 781:      * @return array{credit_limit:float,customer_group_id:?int,customer_group:?string,sample_size:int,source:string}|null
 782:      */
 783:     public function suggestGroupAndCredit(Customer $customer): ?array
 784:     {
 785:         $peers = Customer::query()->with('customerGroup')
 786:             ->where('type', $customer->type->value)
 787:             ->where('status', CustomerStatus::Approved->value)
 788:             ->where('approved_at', '>=', now()->subDays(90))
 789:             ->whereKeyNot($customer->id)->get();
 790:         if ($peers->isEmpty()) {
 791:             return null;
 792:         }
 793:         $limits = $peers->map(fn (Customer $p) => (float) $p->credit_limit)->sort()->values();
 794:         $n = $limits->count();
 795:         $median = $n % 2 === 1 ? $limits[intdiv($n, 2)] : ($limits[$n / 2 - 1] + $limits[$n / 2]) / 2;
 796:         $topGroupId = $peers->whereNotNull('customer_group_id')->groupBy('customer_group_id')->map->count()->sortDesc()->keys()->first();
 797:         $group = $topGroupId ? $peers->firstWhere('customer_group_id', $topGroupId)?->customerGroup : null;
 798:         $typeNames = ['retail' => 'تجزئة', 'wholesale' => 'جملة', 'distributor' => 'موزّع'];
 799: 
 800:         return [
 801:             'credit_limit' => round((float) $median, 2),
 802:             'customer_group_id' => $group?->id,
 803:             'customer_group' => $group?->name,
 804:             'sample_size' => $n,
 805:             'source' => 'مقترح: '.number_format((float) $median, 0, '.', ',').' (وسيط '.$n.' تاجر '.($typeNames[$customer->type->value] ?? $customer->type->value).' اتعمدوا آخر 3 شهور)',
 806:         ];
 807:     }
