 821:                 ['label' => 'قيد المراجعة', 'value' => $d['pending_count']],
 822:                 ['label' => 'متأخر عن المهلة ('.$d['sla_hours'].' ساعة)', 'value' => $d['sla_breached_count']],
 823:                 ['label' => 'ناقص مستندات', 'value' => $d['missing_documents_count']],
 824:                 ['label' => ($d['ready_count_capped'] ?? false) ? 'جاهز للاعتماد (من أقدم 200)' : 'جاهز للاعتماد', 'value' => $d['ready_count']],
 825:             ]];
 826:         }
 827: 
 828:         if ($this->settings->getBool('ai_finance_tools_enabled', false)
 829:             && $this->settings->getBool('ai_finance_proactive_enabled', true)
 830:             && $actor->can('ai_agent.finance')
 831:             && ($actor->can('treasury_transfers.approve') || $actor->can('treasuries.view') || $actor->can('expenses.view'))) {
 832:             $card = app(\App\Services\Ai\Finance\FinanceWelcome::class)->card($actor);
 833:             if ($card !== null) {
 834:                 return $card;
 835:             }
 836:         }
 837: 
 838:         if ($this->settings->getBool('ai_inventory_tools_enabled', false) && $actor->can('inventory.view')) {
 839:             $card = app(InventoryWelcome::class)->card($actor);
 840:             if ($card !== null) {
 841:                 return $card;
 842:             }
 843:         }
 844: 
 845:         if ($this->settings->getBool('ai_catalog_tools_enabled', false) && $actor->can('products.view')) {
 846:             return $this->catalogWelcomeBlock($actor);
 847:         }
 848: 
 849:         return app(\App\Services\Ai\Pricing\PricingWelcome::class)->card($actor);
 850:     }
