 852:     /**
 853:      * 5.4: كارت الترحيب للكتالوج — query واحدة مجمعة + cache لمدة 60 ثانية لكل مستخدم.
 854:      *
 855:      * @return array<string,mixed>
 856:      */
 857:     public function catalogWelcomeBlock(User $actor): array
 858:     {
 859:         $stats = Cache::remember('ai:catalog-welcome:'.$actor->id, 60, function (): array {
 860:             $row = DB::selectOne("
 861:                 SELECT
 862:                     COUNT(*) FILTER (WHERE p.status = 'draft') AS drafts_count,
 863:                     COUNT(*) FILTER (
 864:                         WHERE NOT EXISTS (
 865:                             SELECT 1 FROM media m
 866:                             WHERE m.collection_name = 'images'
 867:                               AND (
 868:                                 (m.model_type = 'App\\\\Models\\\\Product' AND m.model_id = p.id)
 869:                                 OR (
 870:                                     m.model_type = 'App\\\\Models\\\\ProductVariant'
 871:                                     AND m.model_id IN (
 872:                                         SELECT pv.id FROM product_variants pv
 873:                                         WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 874:                                     )
 875:                                 )
 876:                               )
 877:                         )
 878:                     ) AS missing_images_count,
 879:                     COUNT(*) FILTER (
 880:                         WHERE EXISTS (
 881:                             SELECT 1 FROM product_variants pv
 882:                             WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 883:                               AND (
 884:                                 (p.sales_channel IN ('retail', 'both') AND (pv.retail_price IS NULL OR pv.retail_price <= 0))
 885:                                 OR (p.sales_channel IN ('wholesale', 'both') AND (pv.wholesale_price IS NULL OR pv.wholesale_price <= 0))
 886:                               )
 887:                         )
 888:                     ) AS missing_prices_count,
 889:                     COUNT(*) FILTER (
 890:                         WHERE p.status = 'draft'
 891:                           AND EXISTS (
 892:                               SELECT 1 FROM categories c
 893:                               LEFT JOIN categories p1 ON p1.id = c.parent_id AND p1.deleted_at IS NULL
 894:                               LEFT JOIN categories p2 ON p2.id = p1.parent_id AND p2.deleted_at IS NULL
 895:                               WHERE c.id = p.category_id AND c.deleted_at IS NULL
 896:                                 AND c.is_active = TRUE
 897:                                 AND (c.parent_id IS NULL OR (p1.id IS NOT NULL AND p1.is_active = TRUE AND (p1.parent_id IS NULL OR (p2.id IS NOT NULL AND p2.is_active = TRUE AND p2.parent_id IS NULL))))
 898:                           )
 899:                           AND EXISTS (
 900:                               SELECT 1 FROM product_variants pv
 901:                               WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 902:                           )
 903:                           AND NOT EXISTS (
 904:                               SELECT 1 FROM product_variants pv
 905:                               WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 906:                                 AND (
 907:                                   (p.sales_channel IN ('retail', 'both') AND (pv.retail_price IS NULL OR pv.retail_price <= 0))
 908:                                   OR (p.sales_channel IN ('wholesale', 'both') AND (pv.wholesale_price IS NULL OR pv.wholesale_price <= 0))
 909:                                 )
 910:                           )
 911:                           AND EXISTS (
 912:                               SELECT 1 FROM media m
 913:                               WHERE m.collection_name = 'images'
 914:                                 AND (
 915:                                   (m.model_type = 'App\\\\Models\\\\Product' AND m.model_id = p.id)
 916:                                   OR (
 917:                                       m.model_type = 'App\\\\Models\\\\ProductVariant'
 918:                                       AND m.model_id IN (
 919:                                           SELECT pv2.id FROM product_variants pv2
 920:                                           WHERE pv2.product_id = p.id AND pv2.deleted_at IS NULL AND pv2.is_active = TRUE
 921:                                       )
 922:                                   )
 923:                                 )
 924:                           )
 925:                     ) AS ready_count
 926:                 FROM products p
 927:                 WHERE p.deleted_at IS NULL
 928:             ");
 929: 
 930:             return [
 931:                 'drafts_count' => (int) ($row->drafts_count ?? 0),
 932:                 'ready_count' => (int) ($row->ready_count ?? 0),
 933:                 'missing_images_count' => (int) ($row->missing_images_count ?? 0),
 934:                 'missing_prices_count' => (int) ($row->missing_prices_count ?? 0),
 935:             ];
 936:         });
 937: 
 938:         return [
 939:             'type' => 'welcome_card',
 940:             'domain' => 'catalog',
 941:             'title' => 'ملخص الكتالوج السريع',
 942:             'rows' => [
 943:                 ['label' => 'المسودات', 'value' => $stats['drafts_count']],
 944:                 ['label' => 'جاهز للنشر', 'value' => $stats['ready_count']],
 945:                 ['label' => 'منتجات من غير صور', 'value' => $stats['missing_images_count']],
 946:                 ['label' => 'منتجات ناقصها أسعار', 'value' => $stats['missing_prices_count']],
 947:             ],
 948:             'quick_actions' => [
 949:                 ['label' => 'انشر الجاهز', 'prompt' => 'وريني المسودات الجاهزة للنشر'],
 950:                 ['label' => 'وريني المنتجات من غير صور', 'prompt' => 'وريني المنتجات اللي من غير صور'],
 951:                 ['label' => 'اعمل منتج من صورة', 'prompt' => 'عايز أعمل منتج جديد من صورة'],
