 956:     private function normalizeDigits(?string $v): string
 957:     {
 958:         $v = strtr((string) $v, ['٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9', '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9']);
 959: 
 960:         return preg_replace('/[\s\-_.\/]+/u', '', $v) ?? '';
 961:     }
 962: 
 963:     private function compareId(?string $extracted, ?string $registered): string
 964:     {
 965:         $a = $this->normalizeDigits($extracted);
 966:         $b = $this->normalizeDigits($registered);
 967:         if ($a === '' || $b === '') {
 968:             return 'unreadable';
 969:         }
 970: 
 971:         return $a === $b ? 'match' : 'mismatch';
 972:     }
