1041:     private function customerSearchQuery(array $args)
1042:     {
1043:         $query = (string) ($args['query'] ?? '');
1044:         $q = Customer::query()->with('customerGroup')
1045:             ->when($args['business_only'] ?? false, fn ($x) => $x->whereIn('type', ['wholesale', 'distributor']))
1046:             ->when(isset($args['type']), fn ($x) => $x->where('type', $args['type']))
1047:             ->when(isset($args['status']), fn ($x) => $x->where('status', $args['status']))
1048:             ->when(isset($args['customer_group_id']), fn ($x) => $x->where('customer_group_id', $args['customer_group_id']))
1049:             ->when(isset($args['pending_older_than_hours']), fn ($x) => $x->where('status', 'pending')->where('created_at', '<', now()->subHours((int) $args['pending_older_than_hours'])));
1050:         if (trim($query) !== '') {
1051:             if (preg_match('/^[0-9٠-٩۰-۹\s().+-]+$/u', trim($query))) {
1052:                 // L5: LIKE مش ILIKE عشان يستخدم index الـ text_pattern_ops.
1053:                 $q->whereLike('phone', SearchTerm::prefix(Customer::normalizePhone($query)), caseSensitive: true);
1054:             } else {
1055:                 $q->whereLike('search_text', SearchTerm::pattern($query), caseSensitive: false);
1056:             }
1057:         }
1058: 
1059:         return $q;
1060:     }
