1114:     private function dealerQueueSummary(array $args): ToolOutcome
1115:     {
1116:         $sla = max(1, (int) ($args['sla_hours'] ?? $this->settings->get('ai_dealer_review_sla_hours', 48)));
1117:         // M-4: تجميع SQL واحد + ready على أقدم 200 + stale-while-revalidate بدل stampede.
1118:         $data = Cache::flexible('ai:dealer-queue-summary:'.$sla, [60, 300], function () use ($sla): array {
1119:             $agg = Customer::query()->where('status', CustomerStatus::Pending->value)
1120:                 ->selectRaw('COUNT(*) AS pending_count')
1121:                 ->selectRaw('COUNT(*) FILTER (WHERE created_at < ?) AS sla_breached_count', [now()->subHours($sla)])
1122:                 ->selectRaw("COUNT(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM customer_documents d WHERE d.customer_id = customers.id AND d.status = 'verified')) AS missing_documents_count")
1123:                 ->toBase()->first();
1124:             $sampleLimit = 200;
1125:             $ready = Customer::query()->where('status', CustomerStatus::Pending->value)
1126:                 ->with('documents')->orderBy('id')->limit($sampleLimit)->get()
1127:                 ->filter(fn (Customer $c) => $this->reviewCustomer($c)['verdict'] === 'ready')->count();
1128: 
1129:             return [
1130:                 'pending_count' => (int) $agg->pending_count,
1131:                 'sla_breached_count' => (int) $agg->sla_breached_count,
1132:                 'missing_documents_count' => (int) $agg->missing_documents_count,
1133:                 'ready_count' => $ready,
1134:                 'ready_count_capped' => (int) $agg->pending_count > $sampleLimit,
1135:                 'sla_hours' => $sla,
1136:             ];
1137:         });
1138: 
1139:         return ToolOutcome::data($data, ['type' => 'table', 'columns' => ['المؤشر', 'العدد'], 'rows' => [['قيد المراجعة', $data['pending_count']], ['متأخر عن المهلة', $data['sla_breached_count']], ['ناقص مستندات', $data['missing_documents_count']], ['جاهز للاعتماد', $data['ready_count']]]]);
1140:     }
