1155:     /**
1156:      * 1.4: نفس فحوصات approve() قبل الاعتماد، زائد تحذيرات.
1157:      * الرسائل قوالب ثابتة — لا تحتوي أي قيمة كتبها التاجر.
1158:      * $treatVerifiedIds (من المرحلة 2): مستندات تُعامل كموثّقة لمحاكاة
1159:      * التوثيق في prepare الخاص بـ approve_dealer_application — أداة
1160:      * القراءة تستدعي من غيرها فيبقى السلوك مطابقًا.
1161:      *
1162:      * @return array{checks:list<array{key:string,ok:bool,severity:string,message:string}>,verdict:string,next_steps:list<string>}
1163:      */
1164:     private function reviewCustomer(Customer $customer, array $treatVerifiedIds = []): array
1165:     {
1166:         $docs = $customer->relationLoaded('documents') ? $customer->documents : $customer->documents()->get();
1167:         // الحالة الفعالة بعد المحاكاة: الموثّق فعلًا + المحدد للتوثيق.
1168:         $effective = $docs->map(fn ($d) => in_array($d->id, $treatVerifiedIds, true) ? CustomerDocumentStatus::Verified : $d->status);
1169:         $sla = max(1, (int) $this->settings->get('ai_dealer_review_sla_hours', 48));
1170:         $legalNames = ['company_name' => 'اسم الشركة', 'tax_number' => 'الرقم الضريبي', 'commercial_register' => 'السجل التجاري'];
1171:         $missingLegal = array_values(array_filter(array_keys($legalNames), fn ($f) => blank($customer->{$f})));
1172:         $presentTypes = $docs->map(fn ($d) => $d->document_type->value)->all();
1173:         $missingTypes = array_values(array_diff([CustomerDocumentType::CommercialRegister->value, CustomerDocumentType::TaxCard->value], $presentTypes));
1174:         $typeNames = [CustomerDocumentType::CommercialRegister->value => 'سجل تجاري', CustomerDocumentType::TaxCard->value => 'بطاقة ضريبية'];
1175:         $duplicates = $this->duplicateCustomers($customer);
1176:         $checks = [
1177:             ['key' => 'legal_fields', 'ok' => $missingLegal === [], 'severity' => 'blocker', 'message' => $missingLegal === [] ? 'البيانات القانونية التلاتة موجودة.' : 'ناقص: '.implode('، ', array_map(fn ($f) => $legalNames[$f], $missingLegal)).'.'],
1178:             ['key' => 'documents_unverified', 'ok' => ! $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Pending), 'severity' => 'blocker', 'message' => $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Pending) ? 'في مستندات لسه معلقة (pending).' : 'مفيش مستندات معلقة؛ المرفوض مستبعد من القرار.'],
1179:             ['key' => 'no_verified_document', 'ok' => $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Verified), 'severity' => 'blocker', 'message' => $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Verified) ? 'في مستند verified واحد على الأقل.' : 'مفيش ولا مستند verified.'],
1180:             ['key' => 'status_not_pending', 'ok' => $customer->status === CustomerStatus::Pending, 'severity' => 'blocker', 'message' => $customer->status === CustomerStatus::Pending ? 'الطلب قيد المراجعة.' : 'الحالة الحالية مش pending.'],
1181:             ['key' => 'phone_unverified', 'ok' => $customer->phone_verified_at !== null, 'severity' => 'warning', 'message' => $customer->phone_verified_at !== null ? 'رقم الموبايل مؤكد.' : 'رقم الموبايل لسه مش مؤكد.'],
1182:             ['key' => 'duplicates_found', 'ok' => $duplicates === [], 'severity' => 'warning', 'message' => $duplicates === [] ? 'مفيش عملاء مشابهين.' : 'في عملاء مشابهين — راجعهم قبل الاعتماد.'],
1183:             ['key' => 'sla_breached', 'ok' => ! ($customer->status === CustomerStatus::Pending && $customer->created_at < now()->subHours($sla)), 'severity' => 'warning', 'message' => ($customer->status === CustomerStatus::Pending && $customer->created_at < now()->subHours($sla)) ? "الطلب أقدم من مهلة المراجعة ($sla ساعة)." : 'الطلب لسه جوه مهلة المراجعة.'],
1184:             ['key' => 'document_types_missing', 'ok' => $missingTypes === [], 'severity' => 'info', 'message' => $missingTypes === [] ? 'نوعا المستندات الأساسيين موجودين.' : 'ناقص مستند: '.implode('، ', array_map(fn ($t) => $typeNames[$t], $missingTypes)).'.'],
1185:         ];
1186:         $steps = [
1187:             'legal_fields' => 'كمّل البيانات القانونية الناقصة قبل الاعتماد.',
1188:             'documents_unverified' => 'راجع المستندات المعلقة: اعتمد السليم، وارفض غير السليم بسبب واضح.',
1189:             'no_verified_document' => 'لازم مستند موثّق واحد على الأقل قبل الاعتماد.',
1190:             'status_not_pending' => 'الطلب مش قيد المراجعة؛ راجع حالته الحالية قبل أي قرار.',
1191:             'phone_unverified' => 'اطلب من التاجر تأكيد رقم موبايله.',
1192:             'duplicates_found' => 'راجع العملاء المشابهين وتأكد إن ده مش حساب مكرر.',
1193:             'sla_breached' => 'الطلب متأخر عن مهلة المراجعة؛ اديله أولوية.',
1194:             'document_types_missing' => 'اطلب المستندات الناقصة من التاجر.',
1195:         ];
1196:         $nextSteps = [];
1197:         foreach ($checks as $check) {
1198:             if (! $check['ok']) {
1199:                 $nextSteps[] = $steps[$check['key']];
1200:             }
1201:         }
1202:         $verdict = collect($checks)->contains(fn ($c) => $c['severity'] === 'blocker' && ! $c['ok']) ? 'blocked'
1203:             : (collect($checks)->contains(fn ($c) => $c['severity'] === 'warning' && ! $c['ok']) ? 'needs_attention' : 'ready');
1204: 
1205:         return ['checks' => $checks, 'verdict' => $verdict, 'next_steps' => $nextSteps];
1206:     }
1207: 
1208:     /**
1209:      * 1.5: كشف التكرار — تطابق تام ضريبي/سجل، تشابه trigram للاسم (> 0.6)،
1210:      * أو نفس إيميل حساب محذوف. أقصى 5 نتائج، وكل نتيجة معاها reason.
1211:      *
1212:      * @return list<array{id:int,name:array,company_name:array,status:string,type:string,reason:string}>
1213:      */
1214:     private function duplicateCustomers(Customer $customer): array
1215:     {
1216:         $found = [];
1217:         $add = function (Customer $other, string $reason) use (&$found): void {
1218:             if (! isset($found[$other->id])) {
1219:                 $found[$other->id] = ['customer' => $other, 'reasons' => []];
1220:             }
1221:             if (! in_array($reason, $found[$other->id]['reasons'], true)) {
1222:                 $found[$other->id]['reasons'][] = $reason;
1223:             }
1224:         };
1225:         $id = $customer->id;
1226:         // H2: TRIM(...) بقت sargable بفضل expression indexes في migration 2026_11_05.
1227:         if (trim((string) $customer->tax_number) !== '') {
1228:             Customer::query()->whereKeyNot($id)->whereRaw('TRIM(tax_number) = ?', [trim((string) $customer->tax_number)])->limit(5)->get()->each(fn (Customer $o) => $add($o, 'نفس الرقم الضريبي'));
1229:         }
1230:         if (trim((string) $customer->commercial_register) !== '') {
1231:             Customer::query()->whereKeyNot($id)->whereRaw('TRIM(commercial_register) = ?', [trim((string) $customer->commercial_register)])->limit(5)->get()->each(fn (Customer $o) => $add($o, 'نفس السجل التجاري'));
1232:         }
1233:         if (trim((string) $customer->company_name) !== '') {
1234:             $name = trim((string) $customer->company_name);
1235:             // H2: المعامل % هو اللي بيستخدم GIN trigram index؛ similarity() لوحدها = seq scan.
1236:             Customer::query()->whereKeyNot($id)
1237:                 ->whereRaw('company_name % ?', [$name])
1238:                 ->whereRaw('similarity(company_name, ?) > 0.6', [$name])
1239:                 ->orderByRaw('similarity(company_name, ?) DESC', [$name])
1240:                 ->limit(5)->get()->each(fn (Customer $o) => $add($o, 'اسم شركة مشابه'));
1241:         }
1242:         if ($customer->email) {
1243:             Customer::onlyTrashed()->whereKeyNot($id)->where('email', mb_strtolower(trim($customer->email)))->get()->each(fn (Customer $o) => $add($o, 'نفس الإيميل (حساب محذوف)'));
1244:         }
1245: 
1246:         return collect($found)->values()->take(5)->map(fn ($entry) => [
1247:             'id' => $entry['customer']->id,
1248:             'name' => $this->untrusted($entry['customer']->name),
1249:             'company_name' => $this->untrusted($entry['customer']->company_name),
1250:             'status' => $entry['customer']->status->value,
1251:             'type' => $entry['customer']->type->value,
1252:             'reason' => implode('، ', $entry['reasons']),
1253:         ])->all();
1254:     }
