1256:     private function customerHistory(array $args): ToolOutcome
1257:     {
1258:         $customer = $this->findCustomer($args);
1259:         if (! $customer) {
1260:             return ToolOutcome::denied('العميل مش موجود.');
1261:         }
1262:         $limit = min(30, max(1, (int) ($args['limit'] ?? 20)));
1263:         $rows = CustomerAuditLog::query()->where('customer_id', $customer->id)->with('actor:id,name')
1264:             ->orderByDesc('created_at')->orderByDesc('id')->limit($limit)->get()
1265:             ->map(fn (CustomerAuditLog $log) => [
1266:                 'action' => $log->action,
1267:                 'actor' => $log->actor ? ['id' => $log->actor->id, 'name' => $log->actor->name] : null,
1268:                 'metadata' => $log->metadata,
1269:                 'created_at' => $log->created_at,
1270:             ])->all();
1271: 
1272:         return ToolOutcome::data(['customer_id' => $customer->id, 'history' => $rows], ['type' => 'table', 'columns' => ['الإجراء', 'الموظف', 'التاريخ'], 'rows' => array_map(fn ($r) => [$r['action'], $r['actor']['name'] ?? '—', (string) $r['created_at']], $rows)]);
1273:     }
