1304:     private function prepareDrawerSurplus(User $actor, AiConversation $conv, array $args): ToolOutcome
1305:     {
1306:         if (! $actor->can('ai_agent.finance') || ! $actor->can('treasury_transfers.create')
1307:             || $this->toolHiddenByFlags('create_treasury_transfer')) {
1308:             return ToolOutcome::denied('تحويل فائض الأدراج غير متاح لك.');
1309:         }
1310:         $validated = Validator::make($args, ['branch_id' => ['nullable', 'integer', 'min:1']])->validate();
1311:         $branchId = isset($validated['branch_id']) ? (int) $validated['branch_id'] : null;
1312:         try {
1313:             $rows = app(\App\Services\Ai\Finance\Tools\DailyCloseBriefingTool::class)->surplusTransfers($actor, $branchId);
1314:         } catch (\Illuminate\Auth\Access\AuthorizationException) {
1315:             return ToolOutcome::denied('الفرع خارج نطاقك.');
1316:         }
1317:         if ($rows === []) {
1318:             return ToolOutcome::denied('مفيش فائض أدراج متاح للتحويل.', auditable: false);
1319:         }
1320:         if (count($rows) > max(1, (int) $this->settings->get('ai_bulk_max_items', 25))) {
1321:             return ToolOutcome::denied('الدفعة أكبر من الحد المسموح. حدد فرعًا أصغر نطاقًا.', auditable: false);
1322:         }
1323: 
1324:         return $this->prepareBulk($actor, $conv, ['items' => array_map(
1325:             fn (array $row) => ['tool' => 'create_treasury_transfer', 'args' => $row + ['drawer_surplus' => true]],
1326:             $rows,
1327:         )]);
1328:     }
