1330:     private function prepareBulk(User $actor, AiConversation $conv, array $args): ToolOutcome
1331:     {
1332:         return DB::transaction(function () use ($actor, $conv, $args): ToolOutcome {
1333:             $ids = [];
1334:             $items = [];
1335:             $creditUnderUsed = 0;
1336:             $allSetCustomerGroup = $args['items'] !== [];
1337:             foreach ($args['items'] as $item) {
1338:                 // M1: savepoint لكل عنصر — خطأ SQL في عنصر واحد يتراجع
1339:                 // وحده، والمعاملة الخارجية تفضل سليمة لإلغاء السابق.
1340:                 try {
1341:                     $outcome = DB::transaction(fn () => $this->dispatch($actor, $conv, ['name' => $item['tool'], 'args' => $item['args']]));
1342:                 } catch (QueryException $e) {
1343:                     report($e);
1344:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1345: 
1346:                     return ToolOutcome::denied('تعذّر تجهيز أحد عناصر العملية الجماعية بسبب خطأ في قاعدة البيانات؛ راجع العناصر وحاول مجددًا.');
1347:                 }
1348:                 if ($outcome->type !== 'proposal') {
1349:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1350: 
1351:                     return ToolOutcome::denied($outcome->message ?? 'حدد كل العناصر بوضوح قبل تجهيز العملية الجماعية.');
1352:                 }
1353:                 $id = $outcome->data['pending_action_id'];
1354:                 $ids[] = $id;
1355:                 // M7: العناصر عالية الخطورة محتاجة تأكيد مكتوب خاص بيها — ما ينفعش في الجماعي.
1356:                 if (AiPendingAction::whereKey($id)->value('risk') === 'high') {
1357:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1358: 
1359:                     return ToolOutcome::denied('العنصر "'.($outcome->uiBlock['title'] ?? $item['tool']).'" عالي الخطورة؛ نفّذه لوحده مش ضمن عملية جماعية.');
1360:                 }
1361:                 $items[] = ['key' => $id, 'label' => $outcome->uiBlock['title'], 'change' => $item['tool'], 'before' => $outcome->uiBlock['before'] ?? null, 'after' => $outcome->uiBlock['after'] ?? null];
1362:                 // 3.2: عدّ عناصر الائتمان اللي بتنزل تحت المستخدم — من
1363:                 // preview العنصر نفسه (before: used_credit، after:
1364:                 // credit_limit)، مش من إعادة حساب قد تتغير بعد الاقتراح.
1365:                 if ($item['tool'] === 'set_credit_limit') {
1366:                     $before = $outcome->uiBlock['before'] ?? [];
1367:                     $after = $outcome->uiBlock['after'] ?? [];
1368:                     if (isset($before['used_credit'], $after['credit_limit']) && (float) $after['credit_limit'] < (float) $before['used_credit']) {
1369:                         $creditUnderUsed++;
1370:                     }
1371:                 }
1372:                 if ($item['tool'] !== 'set_customer_group') {
1373:                     $allSetCustomerGroup = false;
1374:                 }
1375:             }
1376:             // 3.2: لو كل عناصر المجموعة بلا تغيير أصلًا (المجموعة القديمة
1377:             // = المستهدفة في كل عنصر، من inverse المقترح نفسه)، مفيش
1378:             // عملية أصلًا — denied، والعناصر الفرعية تُلغى زي أي فشل prep.
1379:             if ($allSetCustomerGroup && $ids !== []) {
1380:                 $noChange = AiPendingAction::whereIn('id', $ids)->get()->every(fn (AiPendingAction $child) => array_key_exists('customer_group_id', $child->inverse ?? []) && (int) $child->inverse['customer_group_id'] === (int) ($child->args['customer_group_id'] ?? -1) && (int) ($child->args['customer_group_id'] ?? -1) !== -1);
1381:                 if ($noChange) {
1382:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1383: 
1384:                     return ToolOutcome::denied('مفيش تغيير.');
1385:                 }
1386:             }
1387:             $warnings = [];
1388:             // 3.2: تحذير مجمّع في أعلى الكارت لما أكتر من 30% من كل
1389:             // العناصر بتنزل حد الائتمان تحت المستخدم.
1390:             if ($creditUnderUsed > 0 && $ids !== [] && $creditUnderUsed / count($ids) > 0.3) {
1391:                 $warnings[] = 'تحذير مجمّع: '.$creditUnderUsed.' من '.count($ids).' عناصر بيقللوا حد الائتمان تحت الرصيد المستخدم — التجار دول هيبقوا فوق الحد فورًا، وطلباتهم الآجلة الجاية هتترفض.';
1392:             }
1393:             $warnings[] = 'كل عنصر بيتنفذ لوحده. راجع التغييرات واستبعد أي عنصر مش مطلوب.';
1394:             $outcome = $this->makeProposal($actor, $conv, 'bulk_actions', ['action_ids' => $ids], [], ['title' => 'مراجعة '.count($ids).' عمليات', 'items' => $items, 'warnings' => $warnings], null, 'high');
1395:             // M10: الأجراءات الفرعية بتبقى bulk_child لحد ما المجموعة تتأكد —
1396:             // كده اصلی الـ confirm() المباشر لواحد منهم مرفوض من غير مراجعة.
1397:             AiPendingAction::whereIn('id', $ids)->where('status', 'pending')->update(['status' => 'bulk_child']);
1398:             $block = $outcome->uiBlock;
1399:             $block['type'] = 'bulk_plan';
1400:             $block['items'] = $items;
1401:             $block['typed_confirmation'] = 'تنفيذ';
1402: 
1403:             return ToolOutcome::proposal($block, $outcome->data);
1404:         });
1405:     }
