1417:     private function prepareWrite(User $actor, AiConversation $conv, string $tool, array $args): ToolOutcome
1418:     {
1419:         $this->assertAiConstraints($actor, new AiPendingAction(['tool' => $tool, 'args' => $args]));
1420:         // Forbidden constants
1421:         if ($tool === 'assign_roles' || $tool === 'create_staff_user') {
1422:             $names = array_merge($args['add'] ?? [], $args['roles'] ?? []);
1423:             if (in_array(StaffRole::SuperAdmin->value, $names, true)) {
1424:                 return ToolOutcome::denied('المساعد مش بيقدر يدّي دور Super Admin. استخدم شاشة الموظفين.');
1425:             }
1426:         }
1427:         if (in_array($tool, ['set_user_status', 'assign_roles', 'revoke_user_sessions'], true) && (int) ($args['user_id'] ?? 0) === $actor->id) {
1428:             return ToolOutcome::denied('مش تقدر تعدّل حسابك من المساعد. استخدم الشاشة العادية.');
1429:         }
1430:         if ($tool === 'assign_roles' && in_array(StaffRole::SuperAdmin->value, $args['remove'] ?? [], true)) {
1431:             return ToolOutcome::denied('المساعد مش بيقدر يشيل دور Super Admin. استخدم شاشة الموظفين.');
1432:         }
1433: 
1434:         return match ($tool) {
1435:             'create_branch' => $this->prepCreateBranch($actor, $conv, $args),
1436:             'set_branch_status' => $this->prepSetBranchStatus($actor, $conv, $args),
1437:             'create_role' => $this->prepCreateRole($actor, $conv, $args),
1438:             'update_role_permissions' => $this->prepUpdateRolePerms($actor, $conv, $args),
1439:             'delete_role' => $this->prepDeleteRole($actor, $conv, $args),
1440:             'create_staff_user' => $this->prepCreateStaffUser($actor, $conv, $args),
1441:             'set_user_status' => $this->prepSetUserStatus($actor, $conv, $args),
1442:             'assign_roles' => $this->prepAssignRoles($actor, $conv, $args),
1443:             'revoke_user_sessions' => $this->prepRevokeSessions($actor, $conv, $args),
1444:             'create_location' => $this->prepCreateLocation($actor, $conv, $args),
1445:             'set_location_status' => $this->prepSetLocationStatus($actor, $conv, $args),
1446:             'delete_location' => $this->prepDeleteLocation($actor, $conv, $args),
1447:             'update_settings' => $this->prepUpdateSettings($actor, $conv, $args),
1448:             'update_document_numbering' => $this->prepUpdateDocNumbering($actor, $conv, $args),
1449:             'create_customer' => $this->prepCreateCustomer($actor, $conv, $args),
1450:             'update_customer_profile' => $this->prepUpdateCustomerProfile($actor, $conv, $args),
1451:             'set_customer_group' => $this->prepSetCustomerGroup($actor, $conv, $args),
1452:             'set_credit_limit' => $this->prepSetCreditLimit($actor, $conv, $args),
1453:             'review_customer_document' => $this->prepReviewCustomerDocument($actor, $conv, $args),
1454:             'approve_dealer_application' => $this->prepApproveDealerApplication($actor, $conv, $args),
1455:             'reject_dealer_application' => $this->prepRejectDealerApplication($actor, $conv, $args),
1456:             'suspend_customer' => $this->prepSuspendCustomer($actor, $conv, $args),
1457:             'reactivate_customer' => $this->prepReactivateCustomer($actor, $conv, $args),
1458:             'restore_customer' => $this->prepRestoreCustomer($actor, $conv, $args),
1459:             'create_customer_group' => $this->prepCreateCustomerGroup($actor, $conv, $args),
1460:             'update_customer_group' => $this->prepUpdateCustomerGroup($actor, $conv, $args),
1461:             default => ToolOutcome::denied('أداة كتابة غير معروفة.'),
1462:         };
1463:     }
