1465:     private function prepCreateBranch(User $actor, AiConversation $conv, array $args): ToolOutcome
1466:     {
1467:         try {
1468:             $this->branches->assertCentralAccess($actor);
1469:         } catch (\Throwable) {
1470:             return ToolOutcome::denied('إنشاء الفروع محتاج وصول مركزي.');
1471:         }
1472:         if (empty($args['name']) || empty($args['code']) || empty($args['type'])) {
1473:             return ToolOutcome::denied('بيانات الفرع ناقصة.');
1474:         }
1475:         if (! in_array($args['type'], array_column(BranchType::cases(), 'value'), true)) {
1476:             return ToolOutcome::denied('نوع فرع غير صحيح.');
1477:         }
1478:         $warnings = [];
1479:         if (Branch::where('code', mb_strtoupper(trim((string) $args['code'])))->exists()) {
1480:             $warnings[] = 'الكود ده مستخدم قبل كده.';
1481:         }
1482:         $data = ['name' => (string) $args['name'], 'code' => mb_strtoupper(trim((string) $args['code'])), 'type' => (string) $args['type'], 'city' => $args['city'] ?? null, 'phone' => $args['phone'] ?? null];
1483: 
1484:         return $this->makeProposal($actor, $conv, 'create_branch', $data, [], ['title' => 'إنشاء فرع '.$data['name'], 'after' => $data, 'warnings' => $warnings], null, 'low');
1485:     }
