1487:     private function prepSetBranchStatus(User $actor, AiConversation $conv, array $args): ToolOutcome
1488:     {
1489:         $branch = null;
1490:         if (! empty($args['branch_id'])) {
1491:             $branch = Branch::find((int) $args['branch_id']);
1492:         } elseif (! empty($args['branch_query'])) {
1493:             $opts = $this->resolver->branches($actor, (string) $args['branch_query']);
1494:             if (count($opts) === 1) {
1495:                 $branch = Branch::find($opts[0]['id']);
1496:             }
1497:         }
1498:         if (! $branch) {
1499:             return $this->pickerFor($actor, 'branch', 'set_branch_status', (string) ($args['branch_query'] ?? ''));
1500:         }
1501:         $restricted = null;
1502:         try {
1503:             $restricted = $this->branches->restrictedBranch($actor);
1504:         } catch (\Throwable) {
1505:             return ToolOutcome::denied('النطاق غير مسموح.');
1506:         }
1507:         if ($restricted !== null) {
1508:             return ToolOutcome::denied('تعطيل/تفعيل الفروع محتاج وصول مركزي.');
1509:         }
1510:         $active = (bool) ($args['active'] ?? false);
1511:         $warnings = ['عدد الموظفين في الفرع: '.$branch->users()->count()];
1512:         if (! $active) {
1513:             $warnings[] = 'تعطيل فرع عملية خطيرة.';
1514:         }
1515:         $risk = $active ? 'low' : 'high';
1516: 
1517:         return $this->makeProposal($actor, $conv, 'set_branch_status', ['branch_id' => $branch->id, 'active' => $active], ['branch:'.$branch->id => $this->branchVersion($branch)], ['title' => ($active ? 'تفعيل ' : 'تعطيل ').$branch->name, 'before' => ['is_active' => (bool) $branch->is_active], 'after' => ['is_active' => $active], 'warnings' => $warnings], ['is_active' => (bool) $branch->is_active], $risk);
1518:     }
