1520:     private function prepCreateRole(User $actor, AiConversation $conv, array $args): ToolOutcome
1521:     {
1522:         try {
1523:             $this->branches->assertCentralAccess($actor);
1524:         } catch (\Throwable) {
1525:             return ToolOutcome::denied('إنشاء الأدوار محتاج وصول مركزي.');
1526:         }
1527:         $name = StaffRole::normalizeName((string) ($args['name'] ?? ''));
1528:         if ($name === '' || StaffRole::isReserved($name)) {
1529:             return ToolOutcome::denied('اسم الدور محجوز أو فاضي.');
1530:         }
1531:         $perms = array_values(array_unique($args['permissions'] ?? []));
1532:         if (! StaffAdministration::mayGrantPermissions($actor, $perms)) {
1533:             return ToolOutcome::denied('لا يمكنك إسناد صلاحيات لا تملكها.');
1534:         }
1535:         $sensitive = array_filter($perms, fn ($p) => str_ends_with($p, '.manage') || in_array($p, ['ai_agent.execute', 'ai_agent.settings', 'settings.manage'], true));
1536: 
