1672:     private function prepUpdateCustomerProfile(User $actor, AiConversation $conv, array $args): ToolOutcome
1673:     {
1674:         $customer = $this->findCustomer($args);
1675:         if (! $customer) {
1676:             return ToolOutcome::denied('العميل مش موجود.');
1677:         }
1678:         $data = ['customer_id' => $customer->id];
1679:         $before = [];
1680:         $after = [];
1681:         foreach (['name', 'email', 'phone', 'company_name', 'tax_number', 'commercial_register'] as $field) {
1682:             if (array_key_exists($field, $args) && $args[$field] != $customer->{$field}) {
1683:                 $data[$field] = $args[$field];
1684:                 $before[$field] = $customer->{$field};
1685:                 $after[$field] = $args[$field];
1686:             }
1687:         }
1688:         if ($before === []) {
1689:             return ToolOutcome::denied('مفيش حقول للتعديل.');
1690:         }
1691:         $legalChanged = (bool) array_intersect_key($data, array_flip(['company_name', 'tax_number', 'commercial_register']));
1692:         $sensitiveChanged = $legalChanged || (bool) array_intersect_key($data, array_flip(['email', 'phone']));
1693:         if ($sensitiveChanged && ! $actor->can('customers.approve')) {
1694:             return ToolOutcome::denied('تعديل الإيميل أو الموبايل أو البيانات القانونية محتاج صلاحية customers.approve.');
1695:         }
1696:         $warnings = [];
1697:         $credentialsChanged = collect(['email', 'phone'])->contains(fn ($f) => array_key_exists($f, $data));
1698:         if ($credentialsChanged) {
1699:             $warnings[] = 'هيتم تسجيل خروج التاجر من كل الأجهزة وإلغاء توثيق الموبايل.';
1700:         }
1701:         $risk = 'medium';
1702:         if ($legalChanged && $customer->status === CustomerStatus::Approved) {
1703:             $warnings[] = 'تغيير الهوية القانونية لتاجر معتمد.';
1704:             $risk = 'high';
1705:         }
1706: 
1707:         return $this->makeProposal($actor, $conv, 'update_customer_profile', $data, ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'تعديل بيانات '.$customer->name, 'before' => $before, 'after' => $after, 'warnings' => $warnings], $before, $risk);
1708:     }
