1725:     private function prepSetCreditLimit(User $actor, AiConversation $conv, array $args): ToolOutcome
1726:     {
1727:         $customer = $this->findCustomer($args);
1728:         if (! $customer) {
1729:             return ToolOutcome::denied('العميل مش موجود.');
1730:         }
1731:         $current = (float) $customer->credit_limit;
1732:         $new = (float) $args['credit_limit'];
1733:         $used = (float) app(WholesalePaymentNoticeService::class)->outstandingBalance($customer);
1734:         $threshold = (float) $this->settings->get('ai_credit_limit_confirm_threshold', 100000);
1735:         $warnings = [];
