1737:             $warnings[] = 'التاجر هيبقى فوق الحد فورًا، وطلباته الآجلة الجاية هتترفض.';
1738:         }
1739:         $increase = $current > 0 ? ($new - $current) / $current : ($new > 0 ? INF : 0.0);
1740:         $risk = ($new > $threshold || $increase > 1.0) ? 'high' : 'medium';
1741: 
1742:         return $this->makeProposal($actor, $conv, 'set_credit_limit', ['customer_id' => $customer->id, 'credit_limit' => $args['credit_limit']], ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'تعيين حد ائتمان '.$customer->name, 'before' => ['credit_limit' => $current, 'used_credit' => $used], 'after' => ['credit_limit' => $new, 'used_credit' => $used], 'warnings' => $warnings], ['credit_limit' => $customer->credit_limit], $risk);
1743:     }
