1760:     private function prepApproveDealerApplication(User $actor, AiConversation $conv, array $args): ToolOutcome
1761:     {
1762:         $customer = $this->findCustomer($args);
1763:         if (! $customer) {
1764:             return ToolOutcome::denied('العميل مش موجود.');
1765:         }
1766:         $customer->load('documents');
1767:         $verifyIds = array_values(array_unique(array_map('intval', $args['verify_document_ids'] ?? [])));
1768:         sort($verifyIds);
1769:         $docs = $customer->documents->whereIn('id', $verifyIds);
1770:         if ($docs->count() !== count($verifyIds)) {
1771:             return ToolOutcome::denied('في مستند مش تابع للعميل ده.');
1772:         }
1773:         $review = $this->reviewCustomer($customer, $verifyIds);
1774:         $blockers = collect($review['checks'])->filter(fn ($c) => $c['severity'] === 'blocker' && ! $c['ok'])->values();
1775:         if ($blockers->isNotEmpty()) {
1776:             return ToolOutcome::denied('الاعتماد متعطل: '.implode(' ', $blockers->map(fn ($c) => $c['message'])->all()), auditable: false);
1777:         }
1778:         $warnings = collect($review['checks'])->filter(fn ($c) => $c['severity'] === 'warning' && ! $c['ok'])->map(fn ($c) => $c['message'])->values()->all();
1779:         $data = ['customer_id' => $customer->id];
1780:         if ($verifyIds !== []) {
1781:             $data['verify_document_ids'] = $verifyIds;
1782:         }
1783:         if (isset($args['customer_group_id'])) {
1784:             $data['customer_group_id'] = (int) $args['customer_group_id'];
1785:         }
1786:         if (isset($args['credit_limit'])) {
1787:             $data['credit_limit'] = $args['credit_limit'];
1788:         }
1789:         if (isset($args['type'])) {
1790:             $data['type'] = $args['type'];
1791:         }
1792:         $group = isset($data['customer_group_id']) ? CustomerGroup::find($data['customer_group_id']) : $customer->customerGroup;
1793:         $expected = ['customer:'.$customer->id => $this->customerVersion($customer)];
1794:         foreach ($verifyIds as $id) {
1795:             $expected['customer_document:'.$id] = $this->documentVersion($docs->firstWhere('id', $id));
1796:         }
1797:         // M6: من غير الموبايل — وإلا التأكيد بآخر 4 أرقام يفقد معناه.
1798:         $company = ['name' => $customer->name, 'company_name' => $customer->company_name, 'tax_number' => $customer->tax_number, 'commercial_register' => $customer->commercial_register, 'email' => $customer->email ? $this->resolver->maskEmail($customer->email) : null];
1799: 
1800:         return $this->makeProposal($actor, $conv, 'approve_dealer_application', $data, $expected, ['title' => 'اعتماد تاجر '.($customer->company_name ?? $customer->name), 'before' => ['status' => $customer->status->value, 'company' => $company, 'customer_group' => $customer->customerGroup?->name, 'credit_limit' => (float) $customer->credit_limit], 'after' => ['status' => CustomerStatus::Approved->value, 'company' => $company, 'documents_to_verify' => $docs->map(fn ($d) => ['id' => $d->id, 'type' => $d->document_type->value, 'name' => CustomerDocument::safeName($d->original_name), 'download_url' => route('admin.customers.documents.download', ['customer' => $customer->id, 'document' => $d->id])])->values()->all(), 'suggestion' => $this->suggestGroupAndCredit($customer), 'customer_group' => $group ? ['id' => $group->id, 'name' => $group->name, 'discount_percentage' => $group->discount_percentage] : null, 'credit_limit' => isset($data['credit_limit']) ? (float) $data['credit_limit'] : (float) $customer->credit_limit], 'warnings' => $warnings], null, 'high');
1801:     }
