1848:     private function prepReactivateCustomer(User $actor, AiConversation $conv, array $args): ToolOutcome
1849:     {
1850:         $customer = $this->findCustomer($args);
1851:         if (! $customer) {
1852:             return ToolOutcome::denied('العميل مش موجود.');
1853:         }
1854:         if ($customer->status !== CustomerStatus::Suspended) {
1855:             return ToolOutcome::denied('الحساب مش موقوف.');
1856:         }
1857: 
1858:         $target = CustomerStatus::tryFrom((string) $customer->pre_suspension_status)?->value
1859:             ?? ($customer->approved_at ? CustomerStatus::Approved->value : CustomerStatus::Pending->value);
1860: 
1861:         return $this->makeProposal($actor, $conv, 'reactivate_customer', ['customer_id' => $customer->id], ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'إعادة تفعيل '.$customer->name, 'before' => ['status' => CustomerStatus::Suspended->value], 'after' => ['status' => $target], 'warnings' => []], ['suspension_reason' => $customer->suspension_reason], 'medium');
1862:     }
