1881:         } catch (\Throwable) {
1882:             return ToolOutcome::denied('إدارة مجموعات العملاء محتاجة وصول مركزي.');
1883:         }
1884:         $data = ['name' => (string) $args['name'], 'code' => (string) $args['code']];
1885:         foreach (['description', 'discount_percentage', 'is_active'] as $field) {
1886:             if (array_key_exists($field, $args)) {
1887:                 $data[$field] = $args[$field];
1888:             }
1889:         }
1890: 
1891:         return $this->makeProposal($actor, $conv, 'create_customer_group', $data, [], ['title' => 'إنشاء مجموعة '.$data['name'], 'after' => $data, 'warnings' => []], null, 'low');
