1894:     private function prepUpdateCustomerGroup(User $actor, AiConversation $conv, array $args): ToolOutcome
1895:     {
1896:         try {
1897:             $this->branches->assertCentralAccess($actor);
1898:         } catch (\Throwable) {
1899:             return ToolOutcome::denied('إدارة مجموعات العملاء محتاجة وصول مركزي.');
1900:         }
1901:         $group = CustomerGroup::find((int) $args['customer_group_id']);
1902:         if (! $group) {
1903:             return ToolOutcome::denied('المجموعة مش موجودة.');
1904:         }
1905:         $data = ['customer_group_id' => $group->id];
1906:         $before = [];
1907:         $after = [];
1908:         foreach (['name', 'code', 'description', 'discount_percentage', 'is_active'] as $field) {
1909:             if (! array_key_exists($field, $args)) {
1910:                 continue;
1911:             }
1912:             $changed = match ($field) {
1913:                 'discount_percentage' => (float) $args[$field] !== (float) $group->{$field},
1914:                 'is_active' => (bool) $args[$field] !== (bool) $group->{$field},
1915:                 default => $args[$field] != $group->{$field},
1916:             };
1917:             if ($changed) {
1918:                 $data[$field] = $args[$field];
1919:                 $before[$field] = $group->{$field};
1920:                 $after[$field] = $args[$field];
1921:             }
1922:         }
1923:         if ($before === []) {
1924:             return ToolOutcome::denied('مفيش حقول للتعديل.');
1925:         }
1926:         $discountChanged = array_key_exists('discount_percentage', $data);
1927:         $hasCustomers = $group->customers()->exists();
1928:         $risk = ($discountChanged && $hasCustomers) ? 'high' : 'medium';
1929:         $warnings = ($discountChanged && $hasCustomers) ? ['المجموعة فيها عملاء — تغيير الخصم هيأثر عليهم.'] : [];
1930: 
1931:         return $this->makeProposal($actor, $conv, 'update_customer_group', $data, ['customer_group:'.$group->id => $this->customerGroupVersion($group)], ['title' => 'تعديل مجموعة '.$group->name, 'before' => $before, 'after' => $after, 'warnings' => $warnings], $before, $risk);
1932:     }
