1934:     public function executeWrite(User $actor, AiPendingAction $action, array $via, ?array $selectedItems = null): ToolOutcome
1935:     {
1936:         $args = $action->args;
1937:         $tool = $action->tool;
1938:         $providerTool = $this->toolInstance($tool);
1939:         if ($selectedItems !== null && $providerTool instanceof ExecutesSelectedItems) {
1940:             return $providerTool->executeSelected($actor, $action, $selectedItems);
1941:         }
1942:         try {
1943:             if ($providerTool instanceof WriteTool) {
1944:                 return $providerTool->execute($actor, $action);
1945:             }
1946:             $this->assertAiConstraints($actor, $action);
1947: 
1948:             return match ($tool) {
1949:                 'create_branch' => $this->execCreateBranch($actor, $args, $via, $action),
1950:                 'set_branch_status' => $this->execSetBranchStatus($actor, $args, $via, $action),
1951:                 'create_role' => $this->execCreateRole($actor, $args, $via, $action),
1952:                 'update_role_permissions' => $this->execUpdateRolePerms($actor, $args, $via, $action),
1953:                 'delete_role' => $this->execDeleteRole($actor, $args, $via, $action),
1954:                 'create_staff_user' => $this->execCreateStaffUser($actor, $args, $via, $action),
1955:                 'set_user_status' => $this->execSetUserStatus($actor, $args, $via, $action),
1956:                 'assign_roles' => $this->execAssignRoles($actor, $args, $via, $action),
1957:                 'revoke_user_sessions' => $this->execRevoke($actor, $args, $via, $action),
1958:                 'create_location' => $this->execCreateLocation($actor, $args, $via, $action),
1959:                 'set_location_status' => $this->execSetLocationStatus($actor, $args, $via, $action),
1960:                 'delete_location' => $this->execDeleteLocation($actor, $args, $via, $action),
1961:                 'update_settings' => $this->execUpdateSettings($actor, $args, $via, $action),
1962:                 'update_document_numbering' => $this->execUpdateDocNumbering($actor, $args, $via, $action),
1963:                 'create_customer' => $this->execCreateCustomer($actor, $args, $via, $action),
1964:                 'update_customer_profile' => $this->execUpdateCustomerProfile($actor, $args, $via, $action),
1965:                 'set_customer_group' => $this->execSetCustomerGroup($actor, $args, $via, $action),
1966:                 'set_credit_limit' => $this->execSetCreditLimit($actor, $args, $via, $action),
1967:                 'review_customer_document' => $this->execReviewCustomerDocument($actor, $args, $via, $action),
1968:                 'approve_dealer_application' => $this->execApproveDealerApplication($actor, $args, $via, $action),
1969:                 'reject_dealer_application' => $this->execRejectDealerApplication($actor, $args, $via, $action),
1970:                 'suspend_customer' => $this->execSuspendCustomer($actor, $args, $via, $action),
1971:                 'reactivate_customer' => $this->execReactivateCustomer($actor, $args, $via, $action),
1972:                 'restore_customer' => $this->execRestoreCustomer($actor, $args, $via, $action),
1973:                 'create_customer_group' => $this->execCreateCustomerGroup($actor, $args, $via, $action),
1974:                 'update_customer_group' => $this->execUpdateCustomerGroup($actor, $args, $via, $action),
1975:                 default => ToolOutcome::result(false, 'أداة غير معروفة.'),
1976:             };
1977:         } catch (HttpExceptionInterface $e) {
1978:             if ($e->getStatusCode() === 409) {
1979:                 throw $e;
1980:             }
1981: 
1982:             return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التنفيذ.');
1983:         }
1984:     }
