1986:     private function assertAiConstraints(User $actor, AiPendingAction $action): void
1987:     {
1988:         $args = $action->args;
1989:         if (isset($args['user_id'])) {
1990:             $user = User::where('is_system', false)->findOrFail($args['user_id']);
1991:             abort_if($actor->is($user), 403, 'لا يمكن تعديل حسابك من المساعد.');
1992:             $branch = $this->branches->restrictedBranch($actor);
1993:             abort_if($branch !== null && (int) $user->branch_id !== $branch, 403);
1994:             abort_unless(StaffAdministration::mayManageUser($actor, $user), 403);
1995:             if ($action->tool === 'assign_roles') {
1996:                 abort_if($user->hasRole(StaffRole::SuperAdmin->value, 'staff'), 403, 'استخدم الشاشة لإدارة Super Admin.');
1997:             }
1998:         }
1999:         if (isset($args['role_id'])) {
2000:             // H2: الأدوار عامة على كل الفروع — إدارتها من المساعد محتاجة
2001:             // وصول مركزي، زي ما محصل في شاشة الأدوار.
2002:             $this->branches->assertCentralAccess($actor);
2003:             $role = Role::where('guard_name', 'staff')->findOrFail($args['role_id']);
2004:             abort_if(StaffRole::isReserved($role->name), 403);
2005:         }
2006:         // H2: إنشاء الأدوار بلا role_id — الفحص أعلاه لا يغطيه، والتحقق
2007:         // في prepare وحده لا يكفي وقت execute.
2008:         if (in_array($action->tool, ['create_role', 'update_role_permissions', 'delete_role'], true)) {
2009:             $this->branches->assertCentralAccess($actor);
2010:         }
2011:         // 2.2: ممنوعات المساعد الصريحة — لا تعتمد على غياب الأداة من الـ
2012:         // registry، لأن prepareWrite/executeWrite ممكن يتنده عليهم مباشرة.
2013:         if ($action->tool === 'delete_customer') {
2014:             abort(403, 'حذف العملاء من المساعد ممنوع؛ استخدم شاشة العملاء.');
2015:         }
2016:         if ($action->tool === 'update_customer_profile' && (isset($args['password']) || isset($args['type']) || isset($args['status']))) {
2017:             abort(403, 'تغيير الباسورد أو النوع أو الحالة من المساعد ممنوع.');
2018:         }
2019:         // H1: نفس قاعدة UpdateCustomerRequest::authorize() — بتتفحص في prepareWrite
2020:         // وexecuteWrite وexecuteUndo، فسحب الصلاحية بعد الاقتراح بيوقف التنفيذ.
2021:         if ($action->tool === 'update_customer_profile' && $this->touchesSensitiveCustomerFields($action)) {
2022:             abort_unless($actor->can('customers.approve'), 403, 'تعديل الإيميل أو الموبايل أو البيانات القانونية محتاج صلاحية customers.approve.');
2023:         }
2024:         if ($action->tool === 'create_customer' && ($args['type'] ?? null) === CustomerType::Distributor->value) {
2025:             abort_unless($actor->can('customers.approve'), 403, 'إنشاء حساب موزّع محتاج صلاحية customers.approve.');
2026:         }
2027:         if (in_array($action->tool, ['create_customer_group', 'update_customer_group'], true)) {
2028:             $this->branches->assertCentralAccess($actor);
2029:         }
2030:         $roles = array_merge($args['add'] ?? [], $args['remove'] ?? [], $args['roles'] ?? []);
2031:         if (in_array($action->tool, ['assign_roles', 'create_staff_user'], true)) {
2032:             abort_if(in_array(StaffRole::SuperAdmin->value, $roles, true), 403);
2033:         }
2034:     }
2035: 
2036:     /** H1: وقت الاقتراح (action مش محفوظ) نقارن بالقيم الحالية؛ بعد الحفظ args فيها الحقول المتغيرة بس. */
2037:     private function touchesSensitiveCustomerFields(AiPendingAction $action): bool
2038:     {
2039:         $fields = ['email', 'phone', 'company_name', 'tax_number', 'commercial_register'];
2040:         $args = $action->args ?? [];
2041:         if ($action->exists) {
2042:             return array_intersect_key($args, array_flip($fields)) !== [];
2043:         }
2044:         $customer = Customer::query()->find((int) ($args['customer_id'] ?? 0));
2045:         if (! $customer) {
2046:             return false;
2047:         }
2048:         foreach ($fields as $field) {
2049:             if (! array_key_exists($field, $args)) {
2050:                 continue;
2051:             }
2052:             $new = $field === 'email' && is_string($args[$field]) ? mb_strtolower(trim($args[$field])) : $args[$field];
2053:             if ($new != $customer->{$field}) {
2054:                 return true;
2055:             }
2056:         }
2057: 
2058:         return false;
2059:     }
