2061:     private function checkVersion(string $key, mixed $expected, $model): void
2062:     {
2063:         if (str_starts_with($key, 'branch:')) {
2064:             abort_if($this->branchVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2065:         } elseif (str_starts_with($key, 'location:')) {
2066:             // H3: الموقع نسختة lock هي بصمة الحالة، بتقارن كذا في قفل الصف.
2067:             abort_if($this->hashArgs(['is_active' => (bool) $model->is_active]) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2068:         } elseif (str_starts_with($key, 'customer_document:')) {
2069:             abort_if($this->documentVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2070:         } elseif (str_starts_with($key, 'customer_group:')) {
2071:             abort_if($this->customerGroupVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2072:         } elseif (str_starts_with($key, 'customer:')) {
2073:             abort_if($this->customerVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2074:         } else {
2075:             abort_if((int) $model->lock_version !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2076:         }
2077:     }
