2084:     /**
2085:      * 0.6: بصمة نسخة للعميل — حقول مستقرة فقط. wallet_balance وupdated_at
2086:      * متعمد غيابهما: بيتغيروا مع كل طلب/حركة محفظة، ولو دخلوا في البصمة
2087:      * كل كارت تأكيد كان هيتلغي بـ 409 من غير سبب حقيقي.
2088:      * 2.3: name دخلت مع أدوات الكتابة — update_customer_profile بيكتبها،
2089:      * وتعديلها من REST بين الاقتراح والتأكيد لازم يرفض بـ 409.
2090:      */
2091:     private const CUSTOMER_VERSION_FIELDS = [
2092:         'name', 'status', 'type', 'customer_group_id', 'credit_limit', 'company_name',
2093:         'tax_number', 'commercial_register', 'email', 'phone', 'deleted_at',
