2112:     public function lockTargets(AiPendingAction $action): void
2113:     {
2114:         if (($providerTool = $this->toolInstance($action->tool)) instanceof LocksTargets) {
2115:             $providerTool->lockTargets($action);
2116: 
2117:             return;
2118:         }
2119:         // 2.3: ترتيب قفل ثابت — العميل أولًا ثم مستنداته (رقميًا) ثم
2120:         // المجموعة — يمنع الـ deadlock بين عمليتين متزامنتين على نفس
2121:         // العميل، وهو نفس الترتيب اللي reviewDocument بيستخدمه.
2122:         $keys = array_keys($action->expected_versions ?? []);
2123:         $rank = ['customer' => 0, 'customer_document' => 1, 'customer_group' => 2, 'branch' => 3, 'user' => 4, 'role' => 5, 'location' => 6];
2124:         usort($keys, function ($a, $b) use ($rank) {
2125:             [$ta, $ia] = explode(':', $a, 2);
2126:             [$tb, $ib] = explode(':', $b, 2);
2127: 
2128:             return [$rank[$ta] ?? 99, (int) $ia] <=> [$rank[$tb] ?? 99, (int) $ib];
2129:         });
2130:         foreach ($keys as $key) {
2131:             $version = $action->expected_versions[$key];
2132:             [$type, $id] = explode(':', $key, 2);
2133:             $model = match ($type) {
2134:                 'branch' => Branch::class, 'user' => User::class, 'role' => Role::class, 'location' => Location::class,
2135:                 'customer' => Customer::class, 'customer_document' => CustomerDocument::class, 'customer_group' => CustomerGroup::class,
2136:                 default => null
2137:             };
2138:             abort_unless($model, 409);
2139:             $record = $type === 'customer'
2140:                 ? Customer::withTrashed()->lockForUpdate()->find($id)
2141:                 : $model::query()->lockForUpdate()->find($id);
2142:             abort_unless($record, 409, 'السجل اتحذف.');
2143:             if ($action->status === 'pending') {
2144:                 $this->checkVersion($key, $version, $record);
2145:             }
2146:         }
2147:     }
