2149:     public function canUndo(AiPendingAction $action): bool
2150:     {
2151:         if (($providerTool = $this->toolInstance($action->tool)) !== null) {
2152:             return $providerTool instanceof UndoableTool && $providerTool->canUndo($action);
2153:         }
2154: 
2155:         return $action->inverse && in_array($action->tool, ['set_branch_status', 'update_role_permissions', 'set_user_status', 'assign_roles', 'set_location_status', 'update_customer_profile', 'set_customer_group', 'set_credit_limit', 'review_customer_document', 'suspend_customer', 'reactivate_customer', 'update_customer_group'], true);
2156:     }
