2158:     public function targetState(AiPendingAction $action): string
2159:     {
2160:         if (($providerTool = $this->toolInstance($action->tool)) instanceof UndoableTool) {
2161:             return $providerTool->targetState($action);
2162:         }
2163:         $args = $action->args;
2164:         if (in_array($action->tool, ['update_customer_profile', 'set_customer_group', 'set_credit_limit', 'suspend_customer', 'reactivate_customer'], true) && isset($args['customer_id'])) {
2165:             return $this->customerVersion(Customer::withTrashed()->findOrFail($args['customer_id']));
2166:         }
2167:         if ($action->tool === 'review_customer_document' && isset($args['document_id'])) {
2168:             return $this->documentVersion(CustomerDocument::findOrFail($args['document_id']));
2169:         }
2170:         if ($action->tool === 'update_customer_group' && isset($args['customer_group_id'])) {
2171:             return $this->customerGroupVersion(CustomerGroup::findOrFail($args['customer_group_id']));
2172:         }
2173:         if (isset($args['branch_id']) && $action->tool === 'set_branch_status') {
2174:             return $this->branchVersion(Branch::findOrFail($args['branch_id']));
2175:         }
2176:         if (isset($args['location_id']) && $action->tool === 'set_location_status') {
2177:             $loc = Location::findOrFail($args['location_id']);
2178: 
2179:             return $this->hashArgs(['is_active' => (bool) $loc->is_active]);
2180:         }
2181:         if (isset($args['role_id'])) {
2182:             $role = Role::findOrFail($args['role_id']);
2183: 
2184:             return $this->hashArgs(['record' => $role->getRawOriginal(), 'state' => StaffAdministration::roleState($role)]);
2185:         }
2186:         $user = User::findOrFail($args['user_id']);
2187: 
2188:         return $this->hashArgs(['record' => $user->getRawOriginal(), 'state' => StaffAdministration::userState($user), 'role_versions' => $user->roles()->orderBy('roles.id')->pluck('lock_version', 'roles.id')->all()]);
2189:     }
