2207:     private function execCreateRole(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2208:     {
2209:         $role = app(CreateRole::class)($actor, $args, $via);
2210:         $action->forceFill(['inverse' => ['role_id' => $role->id]])->save();
