2215:     private function execUpdateRolePerms(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2216:     {
2217:         $role = Role::findOrFail($args['role_id']);
2218:         $current = $role->permissions()->pluck('name')->all();
2219:         $next = array_values(array_unique(array_merge(array_diff($current, $args['remove'] ?? []), $args['add'] ?? [])));
2220:         $failure = app(UpdateRole::class)($actor, $role, ['permissions' => $next, 'expected_version' => (int) ($action->expected_versions['role:'.$role->id] ?? $role->lock_version)], $via);
2221:         if ($failure) {
