2284:     private function resolveBranch(User $actor, array $args): ?Branch
2285:     {
2286:         if (! empty($args['branch_id'])) {
2287:             $branch = Branch::find((int) $args['branch_id']);
2288:             if ($branch) {
2289:                 $restricted = $this->branches->restrictedBranch($actor);
2290:                 if ($restricted !== null && (int) $branch->id !== $restricted) {
2291:                     return null;
2292:                 }
2293:             }
2294: 
2295:             return $branch;
2296:         }
2297:         if (! empty($args['branch_query'])) {
2298:             $opts = $this->resolver->branches($actor, (string) $args['branch_query']);
2299:             if (count($opts) === 1) {
2300:                 return Branch::find($opts[0]['id']);
2301:             }
2302:         }
2303: 
2304:         return null;
2305:     }
