2307:     private function listLocations(User $actor, array $args): ToolOutcome
2308:     {
2309:         $branch = $this->resolveBranch($actor, $args);
2310:         if (! $branch) {
2311:             return $this->pickerFor($actor, 'branch', 'اختر الفرع لعرض مواقعه', (string) ($args['branch_query'] ?? ''));
2312:         }
2313:         $locations = $branch->locations()
2314:             ->when(isset($args['type']), fn ($q) => $q->where('type', $args['type']))
2315:             ->orderBy('id')
2316:             // M7: بلا حد، فرع فيه آلاف المواقع يلاحظ الطلب ونتيجة ضخمة.
2317:             ->limit(200)
2318:             ->get(['id', 'name', 'code', 'type', 'is_active']);
2319: 
2320:         if ($locations->isEmpty()) {
2321:             return ToolOutcome::data(['locations' => [], 'branch' => $branch->name, 'message' => 'مفيش مواقع تخزين في الفرع ده.']);
2322:         }
2323: 
2324:         return ToolOutcome::data(
2325:             ['locations' => $locations->toArray(), 'branch' => $branch->name],
2326:             ['type' => 'table', 'columns' => ['ID', 'الاسم', 'الكود', 'النوع', 'الحالة'],
2327:                 'rows' => $locations->map(fn ($l) => [$l->id, $l->name, $l->code, $l->type->value, $l->is_active ? 'نشط' : 'معطّل'])->all()]
2328:         );
2329:     }
