2464:     private function execDeleteLocation(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2465:     {
2466:         try {
2467:             $summary = DB::transaction(function () use ($actor, $args, $via): array {
2468:                 // H3: قفل صف الموقع زي LocationController::destroy بالظبط —
2469:                 // الحذف ضد حركة متزامنة بيرجع failed بدل QueryException/500.
2470:                 // L-6: صفوف الأرصدة تُقفل قبل صف الموقع (ترتيب lockLevels).
2471:                 StockLevel::query()->where('location_id', $args['location_id'])
2472:                     ->orderBy('branch_id')
2473:                     ->orderByRaw('location_id ASC NULLS FIRST')
2474:                     ->orderBy('product_variant_id')
2475:                     ->lockForUpdate()
2476:                     ->get();
2477:                 $locked = Location::query()->lockForUpdate()->findOrFail($args['location_id']);
2478:                 $this->branches->assertBranch($actor->id, $locked->branch_id);
2479:                 StaffAdministration::authorize($actor, ['locations.delete', 'locations.manage']);
2480: 
2481:                 if (DB::table('stock_movements')->where('location_id', $locked->id)->exists()) {
2482:                     return ['ok' => false, 'message' => 'لا يمكن حذف الموقع لارتباطه بحركات مخزنية.', 'branch_id' => $locked->branch_id];
2483:                 }
2484:                 $hasBalances = StockLevel::query()->where('location_id', $locked->id)
2485:                     ->hasNonZeroBalance()
2486:                     ->exists();
2487:                 if ($hasBalances) {
2488:                     return ['ok' => false, 'message' => 'لا يمكن حذف الموقع وفيه أرصدة. صفّرها أولاً.', 'branch_id' => $locked->branch_id];
2489:                 }
2490: 
2491:                 $branch = Branch::find($locked->branch_id);
2492:                 $name = $locked->name;
2493:                 $code = $locked->code;
2494:                 StockLevel::query()->where('location_id', $locked->id)->delete();
2495: 
2496:                 StaffAdministration::audit($actor, 'location.deleted', 'location', $locked->id,
2497:                     [], ['name' => $name, 'code' => $code], [], $via);
2498:                 $locked->delete();
2499: 
2500:                 return ['ok' => true, 'name' => $name, 'branch_id' => $locked->branch_id, 'branch_name' => $branch?->name ?? ''];
2501:             });
2502:         } catch (QueryException $e) {
2503:             report($e);
2504: 
2505:             return ToolOutcome::result(false, 'تعذّر حذف الموقع؛ تربطه حكّة متزامنة. حاول مرة أخرى.');
2506:         }
2507:         if (! $summary['ok']) {
2508:             return ToolOutcome::result(false, $summary['message'], [], ['type' => 'result', 'ok' => false, 'message' => $summary['message']]);
2509:         }
2510:         $message = 'تم حذف موقع '.$summary['name'].' من '.$summary['branch_name'];
2511: 
2512:         return ToolOutcome::result(true, 'تم حذف الموقع.', [],
2513:             ['type' => 'result', 'ok' => true, 'message' => $message,
2514:                 'deep_link' => '/branches?branchId='.$summary['branch_id']]);
2515:     }
