2519:     private function viewSettings(User $actor, array $args): ToolOutcome
2520:     {
2521:         try {
2522:             $this->branches->assertCentralAccess($actor);
2523:         } catch (\Throwable) {
2524:             return ToolOutcome::denied('عرض الإعدادات محتاج وصول مركزي.');
2525:         }
2526:         $all = $this->settings->getAllGrouped();
2527:         $group = (string) ($args['group'] ?? 'all');
2528: 
2529:         // حماية إعدادات AI
2530:         if (! $actor->can('ai_agent.settings')) {
2531:             unset($all['ai']);
2532:         }
2533: 
2534:         if ($group !== 'all' && $group !== '') {
2535:             $data = $all[$group] ?? [];
2536:             if ($data === []) {
2537:                 return ToolOutcome::denied('المجموعة "'.$group.'" مش موجودة أو فاضية.');
2538:             }
2539: 
2540:             return ToolOutcome::data(['settings' => $data, 'group' => $group]);
2541:         }
2542: 
2543:         return ToolOutcome::data(['settings' => $all]);
2544:     }
