2546:     private function viewDocumentNumbering(User $actor, array $args): ToolOutcome
2547:     {
2548:         try {
2549:             $this->branches->assertCentralAccess($actor);
2550:         } catch (\Throwable) {
2551:             return ToolOutcome::denied('عرض الترقيم محتاج وصول مركزي.');
2552:         }
2553: 
2554:         $allTypes = ['order', 'invoice', 'purchase_order', 'quotation', 'transfer', 'stocktake',
2555:             'return', 'purchase_request', 'delivery', 'supplier_invoice', 'supplier_payment',
2556:             'shift', 'pos_invoice', 'expense', 'treasury_transfer', 'payment_notice', 'movement'];
2557: 
2558:         $type = (string) ($args['type'] ?? 'all');
2559: 
2560:         $readNumbering = function (string $t): array {
2561:             $prefix = $this->settings->get($t.'_prefix', '');
2562:             $next = $this->settings->get($t.'_next_number', 1);
2563:             $padding = (int) $this->settings->get($t.'_padding', 6);
2564: 
2565:             return [
2566:                 'type' => $t,
2567:                 'prefix' => $prefix,
2568:                 'next_number' => $next,
2569:                 'padding' => $padding,
2570:                 'sample' => $prefix.str_pad((string) $next, $padding, '0', STR_PAD_LEFT),
2571:             ];
2572:         };
2573: 
2574:         if ($type !== 'all' && $type !== '') {
2575:             if (! in_array($type, $allTypes, true)) {
2576:                 return ToolOutcome::denied('نوع مستند غير معروف.');
2577:             }
2578: 
2579:             return ToolOutcome::data(['numbering' => $readNumbering($type)]);
2580:         }
2581: 
2582:         $rows = [];
2583:         foreach ($allTypes as $t) {
2584:             $info = $readNumbering($t);
2585:             $rows[] = [$info['type'], $info['prefix'], $info['next_number'], $info['padding'], $info['sample']];
2586:         }
2587: 
2588:         return ToolOutcome::data(
2589:             ['numbering' => $rows],
2590:             ['type' => 'table', 'columns' => ['النوع', 'البادئة', 'العداد', 'الطول', 'عينة'], 'rows' => $rows]
2591:         );
2592:     }
2593: 
2594:     private function prepUpdateSettings(User $actor, AiConversation $conv, array $args): ToolOutcome
2595:     {
2596:         try {
2597:             $this->branches->assertCentralAccess($actor);
2598:         } catch (\Throwable) {
2599:             return ToolOutcome::denied('تعديل الإعدادات محتاج وصول مركزي.');
2600:         }
2601:         $changes = $args['changes'] ?? [];
2602:         if (empty($changes)) {
2603:             return ToolOutcome::denied('مفيش تغييرات.');
2604:         }
2605: 
2606:         // M-3: الوكيل ما يعدّلش حواجزه — الإعدادات دي من شاشة الإدارة (REST) بس.
2607:         $guarded = array_values(array_filter(array_keys($changes), fn ($k) => self::isAgentGuardedSetting($k)));
2608:         if ($guarded !== []) {
2609:             return ToolOutcome::denied('الإعدادات دي بتتعدل من شاشة الإعدادات بس: '.implode(', ', $guarded), auditable: true);
2610:         }
2611: 
2612:         // منع تعديل ترقيم من هنا — ليها أداة مخصوصة
2613:         $numberingKeys = array_filter(array_keys($changes), fn ($k) => str_ends_with($k, '_prefix') || str_ends_with($k, '_next_number') || str_ends_with($k, '_padding'));
2614:         if ($numberingKeys !== []) {
2615:             return ToolOutcome::denied('ترقيم المستندات يتعدل من أداة update_document_numbering.');
2616:         }
2617: 
2618:         // التحقق إن المفاتيح موجودة ومسموحة
2619:         // H1: مفاتيح expected/expected.* وai_disabled_tools.* ليست إعدادات قابلة للتعديل.
2620:         $allowedKeys = array_values(array_filter(
2621:             array_keys((new UpdateSettingsRequest)->rules()),
2622:             fn (string $key): bool => $key !== 'expected' && ! str_starts_with($key, 'expected.') && ! str_ends_with($key, '.*') && ! self::isAgentGuardedSetting($key)
2623:         ));
2624:         $unknownKeys = array_diff(array_keys($changes), $allowedKeys);
2625:         if ($unknownKeys !== []) {
2626:             return ToolOutcome::denied('إعدادات غير معروفة: '.implode(', ', $unknownKeys));
2627:         }
2628: 
2629:         // قراءة القيم الحالية
2630:         $current = [];
2631:         foreach (array_keys($changes) as $key) {
2632:             $current[$key] = $this->settings->get($key);
2633:         }
2634: 
2635:         // H1: تطبيق نفس قواعد الـ REST على قيم الوكيل (نحو/نطاقات/حدود
2636:         // prefix وpadding) — المصدر واحد: UpdateSettingsRequest::rules().
2637:         $this->validateSettingChanges($changes);
2638: 
2639:         $warnings = [];
2640:         if (isset($changes['tax_enabled']) && ! $changes['tax_enabled']) {
2641:             $warnings[] = 'تعطيل الضرائب هيأثر على كل الفواتير الجديدة.';
2642:         }
2643:         if (isset($changes['return_window_days'])) {
2644:             if ($changes['return_window_days'] === 0) {
2645:                 $warnings[] = 'الإرجاع هيكون متوقف تماماً.';
2646:             } elseif ($changes['return_window_days'] < 0) {
2647:                 $warnings[] = 'الإرجاع هيكون بلا حد زمني.';
2648:             }
2649:         }
2650: 
2651:         return $this->makeProposal($actor, $conv, 'update_settings',
2652:             ['changes' => $changes, 'expected' => $current], [],
2653:             ['title' => 'تعديل '.count($changes).' إعداد',
2654:                 'before' => $current, 'after' => $changes,
2655:                 'warnings' => $warnings], $current, 'high');
2656:     }
2657: 
2658:     /**
2659:      * H1: تحقق من قيم الإعدادات بمصدر القواعد الواحد (UpdateSettingsRequest)
2660:      * مع تجاهل مفاتيح expected وبقاعدتها اللي بتشترط وجود القيمة الأصلية.
2661:      */
2662:     private function validateSettingChanges(array $changes): void
2663:     {
2664:         $rules = array_filter(
2665:             (new UpdateSettingsRequest)->rules(),
2666:             fn (string $key): bool => $key !== 'expected' && ! str_starts_with($key, 'expected.') && ! str_ends_with($key, '.*') && ! self::isAgentGuardedSetting($key),
2667:             ARRAY_FILTER_USE_KEY
2668:         );
2669:         // H1: مفتاح غير معروف (من هلوسة أو حقن) يترفض هنا أيضًا في execute،
2670:         // حتى لو args اتخزنت قبل الإصلاح.
2671:         $unknown = array_diff(array_keys($changes), array_keys($rules));
2672:         if ($unknown !== []) {
2673:             throw ValidationException::withMessages(array_fill_keys($unknown, 'إعداد غير معروف.'));
2674:         }
2675:         $applicable = [];
2676:         foreach (array_keys($changes) as $key) {
2677:             $applicable[$key] = $rules[$key];
2678:         }
2679:         Validator::make($changes, $applicable)->validate();
2680:     }
2681: 
2682:     private static function isAgentGuardedSetting(string $key): bool
2683:     {
2684:         return str_starts_with($key, 'ai_') || $key === 'allow_self_approve_purchases';
2685:     }
