2687:     private function execUpdateSettings(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2688:     {
2689:         $this->branches->assertCentralAccess($actor);
2690:         StaffAdministration::authorize($actor, ['settings.manage']);
2691:         // M-3: إعادة فحص وقت التأكيد (args ممكن تكون اتخزنت قبل الإصلاح).
2692:         if (array_filter(array_keys($args['changes'] ?? []), fn ($k) => self::isAgentGuardedSetting($k)) !== []) {
2693:             return ToolOutcome::result(false, 'إعدادات الذكاء الاصطناعي وفصل المهام بتتعدل من شاشة الإعدادات بس.');
2694:         }
2695:         // H1: إعادة التحقق وقت التأكيد تحمي من args خزّنت قبل الإصلاح.
2696:         $this->validateSettingChanges($args['changes']);
2697:         // L6: التدقيق يعرف إن التعديل جه من قناة المساعد.
2698:         $this->settings->updateBatch($args['changes'], $args['expected'], $via);
2699: 
2700:         return ToolOutcome::result(true, 'تم تحديث الإعدادات.',
2701:             ['updated_keys' => array_keys($args['changes'])],
2702:             ['type' => 'result', 'ok' => true,
2703:                 'message' => 'تم تحديث '.count($args['changes']).' إعداد.',
2704:                 'deep_link' => '/settings']);
2705:     }
