2707:     private function prepUpdateDocNumbering(User $actor, AiConversation $conv, array $args): ToolOutcome
2708:     {
2709:         try {
2710:             $this->branches->assertCentralAccess($actor);
2711:         } catch (\Throwable) {
2712:             return ToolOutcome::denied('تعديل الترقيم محتاج وصول مركزي.');
2713:         }
2714:         $type = (string) ($args['type'] ?? '');
2715:         if ($type === '') {
2716:             return ToolOutcome::denied('نوع المستند مطلوب.');
2717:         }
2718: 
2719:         $changes = [];
2720:         $current = [];
2721:         if (isset($args['prefix'])) {
2722:             $key = $type.'_prefix';
2723:             $changes[$key] = (string) $args['prefix'];
2724:             $current[$key] = $this->settings->get($key, '');
2725:         }
2726:         if (isset($args['next_number'])) {
2727:             $key = $type.'_next_number';
2728:             $changes[$key] = (int) $args['next_number'];
2729:             $current[$key] = $this->settings->get($key, 1);
2730:         }
2731:         if (isset($args['padding'])) {
2732:             $key = $type.'_padding';
2733:             $changes[$key] = (int) $args['padding'];
2734:             $current[$key] = $this->settings->get($key, 6);
2735:         }
2736: 
2737:         if (empty($changes)) {
2738:             return ToolOutcome::denied('حدد قيمة واحدة على الأقل (prefix أو next_number أو padding).');
2739:         }
2740:         // H1: مسار الترقيم مطبّق عليه حدود الـ REST: بادئة 30 رمزًا
2741:         // كحد أقصى، padding من 1 لـ 20، عداد بين 1 و999999999.
2742:         $this->validateSettingChanges($changes);
2743: 
2744:         $warnings = [];
2745:         if (isset($args['next_number'])) {
2746:             $currentNext = $current[$type.'_next_number'] ?? 1;
2747:             if ($args['next_number'] < $currentNext) {
2748:                 $warnings[] = 'العداد لا ينخفض — لو القيمة أقل من الحالية هتتجاهل.';
2749:             }
2750:         }
2751: 
2752:         // بناء عينة الرقم الجديد
2753:         $newPrefix = $changes[$type.'_prefix'] ?? $this->settings->get($type.'_prefix', '');
2754:         $newNext = $changes[$type.'_next_number'] ?? $this->settings->get($type.'_next_number', 1);
2755:         $newPadding = $changes[$type.'_padding'] ?? $this->settings->get($type.'_padding', 6);
2756:         $sample = $newPrefix.str_pad((string) $newNext, $newPadding, '0', STR_PAD_LEFT);
2757: 
2758:         return $this->makeProposal($actor, $conv, 'update_document_numbering',
2759:             ['type' => $type, 'changes' => $changes, 'expected' => $current], [],
2760:             ['title' => 'تعديل ترقيم '.$type,
2761:                 'before' => $current, 'after' => array_merge($changes, ['sample' => $sample]),
2762:                 'warnings' => $warnings], $current, 'high');
2763:     }
