2798:         return ToolOutcome::result(true, 'تم إنشاء العميل.', ['customer_id' => $customer->id, 'generated_password' => $plain], ['type' => 'result', 'ok' => true, 'message' => 'تم إنشاء العميل. الباسورد المؤقت (يظهر مرة واحدة): '.$plain, 'deep_link' => '/dealers?customer='.$customer->id]);
