2847:         }
2848:         $service->approve($customer, $data, $actor->id, $via);
2849: 
2850:         return ToolOutcome::result(true, 'تم اعتماد التاجر.', ['customer_id' => $customer->id], ['type' => 'result', 'ok' => true, 'message' => 'تم اعتماد التاجر.', 'deep_link' => '/dealers?customer='.$customer->id]);
