2911:     public function executeUndo(User $actor, AiPendingAction $action, array $via): ToolOutcome
2912:     {
2913:         $inv = $action->inverse ?? [];
2914:         $tool = $action->tool;
2915:         $args = $action->args;
2916:         try {
2917:             if (($providerTool = $this->toolInstance($tool)) instanceof UndoableTool) {
2918:                 return $providerTool->undo($actor, $action);
2919:             }
2920:             $this->assertAiConstraints($actor, $action);
2921:             if ($tool === 'set_branch_status' && isset($inv['is_active'])) {
2922:                 $b = Branch::findOrFail($args['branch_id']);
2923:                 app(UpdateBranch::class)($actor, $b, ['is_active' => (bool) $inv['is_active']], $via);
2924: 
2925:                 return ToolOutcome::result(true, 'تم التراجع.');
2926:             }
2927:             if ($tool === 'update_role_permissions' && isset($inv['permissions'])) {
2928:                 $r = Role::findOrFail($args['role_id']);
2929:                 $f = app(UpdateRole::class)($actor, $r, ['permissions' => $inv['permissions']], $via);
2930: 
2931:                 return $f ? ToolOutcome::result(false, 'الدور محمي.') : ToolOutcome::result(true, 'تم التراجع.');
2932:             }
2933:             if ($tool === 'set_user_status' && isset($inv['is_active'])) {
2934:                 $u = User::findOrFail($args['user_id']);
2935:                 $f = app(UpdateStaffUser::class)($actor, $u, ['is_active' => (bool) $inv['is_active']], $via);
2936: 
2937:                 return $f ? ToolOutcome::result(false, 'مش مسموح.') : ToolOutcome::result(true, 'تم التراجع.');
2938:             }
2939:             if ($tool === 'assign_roles' && isset($inv['roles'])) {
2940:                 $u = User::findOrFail($args['user_id']);
2941:                 $f = app(UpdateStaffUser::class)($actor, $u, ['roles' => $inv['roles']], $via);
2942: 
2943:                 return $f ? ToolOutcome::result(false, 'مش مسموح.') : ToolOutcome::result(true, 'تم التراجع.');
2944:             }
2945:             if ($tool === 'set_location_status' && isset($inv['is_active'])) {
2946:                 // H3: التراجع يمر بنفس القاعدة المشتركة (مع قفل الصف داخل الـ action).
2947:                 app(SetLocationStatus::class)(
2948:                     $actor, Location::findOrFail($args['location_id']), (bool) $inv['is_active'], $via);
2949: 
2950:                 return ToolOutcome::result(true, 'تم التراجع.');
2951:             }
2952:             // ── P04-2: تراجع أدوات العملاء ───────────────────────────────
2953:             if (in_array($tool, ['update_customer_profile', 'set_customer_group', 'set_credit_limit'], true) && $inv !== []) {
2954:                 $c = Customer::findOrFail($args['customer_id']);
2955:                 app(CustomerManagementService::class)->update($c, $inv, $actor->id, $via);
2956: 
2957:                 return ToolOutcome::result(true, 'تم التراجع.');
2958:             }
2959:             if ($tool === 'review_customer_document' && isset($inv['status'])) {
2960:                 $c = Customer::findOrFail($args['customer_id']);
2961:                 $d = $c->documents()->whereKey($args['document_id'])->firstOrFail();
2962:                 app(CustomerManagementService::class)->reviewDocument($c, $d, $inv['status'], $actor->id, null, $via);
2963: 
2964:                 return ToolOutcome::result(true, 'تم التراجع.');
2965:             }
2966:             if ($tool === 'suspend_customer') {
2967:                 // التراجع عن الإيقاف = إعادة تفعيل (ترجع معتمدًا لو كان
2968:                 // معتمدًا قبل الإيقاف، وإلا قيد المراجعة)؛ الجلسات المنهية
2969:                 // لا ترجع — التحذير ده كان في كارت التأكيد نفسه.
2970:                 $c = Customer::findOrFail($args['customer_id']);
2971:                 app(CustomerManagementService::class)->reactivate($c, $actor->id, $via, $inv['previous_status'] ?? null); // M12
2972: 
2973:                 return ToolOutcome::result(true, 'تم التراجع.');
2974:             }
2975:             if ($tool === 'reactivate_customer' && array_key_exists('suspension_reason', $inv)) {
2976:                 $c = Customer::findOrFail($args['customer_id']);
2977:                 app(CustomerManagementService::class)->suspend($c, $inv['suspension_reason'] ?? 'إيقاف من المساعد (تراجع عن إعادة التفعيل)', $actor->id, $via);
2978: 
2979:                 return ToolOutcome::result(true, 'تم التراجع.');
2980:             }
2981:             if ($tool === 'update_customer_group' && $inv !== []) {
