146:     /**
147:      * Return all settings grouped by their group name, with values cast to their declared types.
148:      * Numbering counters are read fresh because they change for every generated document number.
149:      *
150:      * @return array<string, array<string, mixed>>
151:      */
152:     public function getAllGrouped(): array
153:     {
154:         $grouped = $this->staticSettings();
155: 
156:         $counters = Setting::query()
157:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
158:             ->orderBy('key')
159:             ->get()
160:             ->mapWithKeys(fn (Setting $setting): array => [
161:                 $setting->key => $this->castValue($setting->value, $setting->type),
162:             ])
163:             ->all();
164: 
165:         if (isset($counters['movement_next_number'])) {
166:             $counters['movement_next_number'] = $this->nextMovementNumber();
167:         }
168:         foreach (self::SEQUENCE_TYPES as $type => $key) {
169:             if (isset($counters[$key])) {
170:                 $counters[$key] = $this->nextDocumentNumber($type);
171:             }
172:         }
173: 
174:         if ($counters !== []) {
175:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
176:             ksort($grouped['numbering']);
177:         }
178: 
179:         return $grouped;
180:     }
