182:     private function staticSettings(): array
183:     {
184:         $read = function (): array {
185:             return Setting::query()
186:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
187:                 ->orderBy('group')
188:                 ->orderBy('key')
189:                 ->get()
190:                 ->groupBy('group')
191:                 ->map(fn ($settings): array => $settings
192:                     ->mapWithKeys(fn (Setting $setting): array => [
193:                         $setting->key => $this->castValue($setting->value, $setting->type),
194:                     ])
195:                     ->all())
196:                 ->all();
197:         };
198: 
199:         $inTransaction = DB::transactionLevel() > 0;
200:         if ($inTransaction && $this->transactionSnapshot !== null) {
201:             return $this->transactionSnapshot;
202:         }
203:         if ($inTransaction && $this->uncommittedSettings) {
204:             return $this->transactionSnapshot = $read();
205:         }
206:         $version = Cache::get(self::CACHE_VERSION_KEY);
207:         if (! is_string($version)) {
208:             Cache::add(self::CACHE_VERSION_KEY, (string) Str::uuid());
209:             $version = Cache::get(self::CACHE_VERSION_KEY);
210:         }
211: 
212:         // M-6: خارج الـ transactions تُحفظ النتيجة في ذاكرة الطلب — كل get()
213:         // كان يكلف رحلتين للكاش وفك تسلسل المصفوفة كاملة.
214:         if ($this->requestCache !== null) {
215:             return $this->requestCache;
216:         }
217:         $key = self::CACHE_KEY.':'.$version;
218:         if ($inTransaction) {
219:             // Reuse committed cache values, but never publish an uncommitted cache miss.
220:             return $this->transactionSnapshot = Cache::get($key) ?? $read();
221:         }
222: 
223:         $result = Cache::remember($key, self::CACHE_TTL_SECONDS, $read);
224:         // كاتب متأخر قد يدير النسخة أثناء القراءة — لقطة قديمة لا تُحفظ
225:         // في ذاكرة الطلب، وإلا التصقت القيمة القديمة بباقي الطلب.
226:         if (Cache::get(self::CACHE_VERSION_KEY) === $version) {
227:             $this->requestCache = $result;
228:         }
229: 
230:         return $result;
231:     }
