233:     public function get(string $key, mixed $default = null): mixed
234:     {
235:         if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
236:             if ($key === 'movement_next_number') {
237:                 return $this->nextMovementNumber();
238:             }
239:             $type = array_search($key, self::SEQUENCE_TYPES, true);
240:             if (is_string($type)) {
241:                 return $this->nextDocumentNumber($type);
242:             }
243:             $setting = Setting::query()->where('key', $key)->first();
244: 
245:             return $setting ? $this->castValue($setting->value, $setting->type) : $default;
246:         }
247:         foreach ($this->staticSettings() as $settings) {
248:             if (array_key_exists($key, $settings)) {
249:                 return $settings[$key];
250:             }
251:         }
252: 
253:         if ($default === null && array_key_exists($key, self::DEFAULTS)) {
254:             return self::DEFAULTS[$key];
255:         }
256: 
257:         return $default;
258:     }
