280:     private function assertNumberingDoesNotCollide(array $settings, array $after): void
281:     {
282:         foreach ($this->numberingDefinitions() as $type => $definition) {
283:             $keys = [$definition['prefix'], $definition['next'], $definition['padding']];
284:             $target = self::NUMBERING_TARGETS[$type] ?? null;
285:             if ($target === null || array_intersect($keys, array_keys($settings)) === []) {
286:                 continue;
287:             }
288: 
289:             $prefix = array_key_exists($definition['prefix'], $after)
290:                 ? (string) $after[$definition['prefix']]
291:                 : (string) $this->get($definition['prefix'], '');
292:             $padding = array_key_exists($definition['padding'], $after)
293:                 ? max(0, (int) $after[$definition['padding']])
294:                 : max(0, (int) $this->get($definition['padding'], 0));
295:             $next = array_key_exists($definition['next'], $after)
296:                 ? (int) $after[$definition['next']]
297:                 : ($type === 'movement' ? $this->nextMovementNumber() : $this->nextDocumentNumber($type));
298: 
299:             // Collision scan covers the next number AND any future number:
300:             // any existing document sharing this prefix whose numeric suffix
301:             // is >= the proposed counter would collide now or later.
302:             $escaped = addcslashes($prefix, '\\%_');
303:             $existing = DB::table($target[0])->where($target[1], 'like', $escaped.'%')->pluck($target[1]);
304:             $max = null;
305:             foreach ($existing as $number) {
306:                 // The remainder after the prefix must be purely numeric:
307:                 // that numeric suffix is what future counters would reproduce.
308:                 $tail = trim(substr((string) $number, strlen($prefix)));
309:                 if ($tail === '' || ! ctype_digit($tail)) {
310:                     continue;
311:                 }
312:                 $max = max($max ?? 0, (int) $tail);
313:             }
314: 
315:             if ($max !== null && $max >= $next) {
316:                 throw ValidationException::withMessages([
317:                     $definition['next'] => 'الرقم '.$prefix.str_pad((string) $next, $padding, '0', STR_PAD_LEFT).' مستخدم بالفعل في '.$target[0].'. غيّر البداية أو البادئة أو الطول.',
318:                 ]);
319:             }
320:         }
321:     }
