323:     /**
324:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
325:      *
326:      * @param  array<string, mixed>  $settings
327:      *
328:      * @throws JsonException
329:      */
330:     public function updateBatch(array $settings, ?array $expected = null, array $via = []): void
331:     {
332:         $this->warnings = [];
333:         DB::transaction(function () use ($settings, $expected, $via): void {
334:             $this->uncommittedSettings = true;
335:             $this->resetReadSnapshot();
336:             $movementSequenceTarget = null;
337:             /** @var array<string, int> $documentSequenceTargets */
338:             $documentSequenceTargets = [];
339:             $lockedSettings = Setting::query()
340:                 ->whereIn('key', array_keys($settings))
341:                 ->orderBy('key')
342:                 ->lockForUpdate()
343:                 ->get()
344:                 ->keyBy('key');
345: 
346:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
347: 
348:             if ($missingKeys !== []) {
349:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
350:             }
351: 
352:             $before = [];
353:             $after = [];
354:             foreach ($settings as $key => $value) {
355:                 /** @var Setting $setting */
356:                 $setting = $lockedSettings->get($key);
357:                 $current = $this->castValue($setting->value, $setting->type);
358:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
359:                     $current = $this->get($key);
360:                 }
361:                 // M7/M8: العدادات الحية (قيم الـ sequences) بتزيد من نفسها مع
362:                 // كل فاتورة/عملية بتتنفذ — تسجيل التوقيع على القيمة الحلية
363:                 // بيورّط 409 دايمًا على الأنظمة المزدحمة. للعدادات القاعدة هي
364:                 // "الجديد ≥ الحالي" بس (فوق)، وexpected يحكم البادئة والطول
365:                 // والأنواع غير العدادية (فاتورة ضريبية مثلًا تفضل بالمساواة).
366:                 $isCounter = in_array($key, self::NUMBERING_COUNTER_KEYS, true);
367:                 if (! $isCounter && $expected !== null && (! array_key_exists($key, $expected)
368:                     || $this->comparisonValue($current, $setting->type) !== $this->comparisonValue($expected[$key], $setting->type))) {
369:                     abort(409, 'تم تغيير إعداد أو عداد منذ فتح الصفحة؛ أعد تحميل الإعدادات قبل الحفظ.');
370:                 }
371:                 $before[$key] = $current;
372: 
373:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
374:                     $requested = $this->counterValue($value);
375:                     if ($requested > 999999999) {
376:                         throw ValidationException::withMessages([$key => 'الحد الأقصى للعداد هو 999999999.']);
377:                     }
378:                     $value = max($this->counterValue($setting->value), $requested);
379:                     if ($key === 'movement_next_number') {
380:                         $value = max($value, $this->nextMovementNumber());
381:                         $movementSequenceTarget = $value;
382:                     }
383:                     $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
384:                     if (is_string($sequenceType)) {
385:                         $value = max($value, $this->nextDocumentNumber($sequenceType));
386:                         $documentSequenceTargets[$sequenceType] = $value;
387:                     }
388:                     if ($requested < $value) {
389:                         throw ValidationException::withMessages([$key => 'لا يمكن خفض عداد الترقيم عن قيمته الحالية.']);
390:                     }
391:                 }
392: 
393:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
394:                     ? ''
395:                     : $this->serializeValue($value, $setting->type);
396:                 $setting->save();
397:                 $after[$key] = $this->castValue($setting->value, $setting->type);
398:             }
399: 
400:             $this->assertNumberingDoesNotCollide($settings, $after);
401:             // M-4: تغيير البادئة أو الطول قد يعيد إصدار رقم صدر من قبل
402:             // (مثال: INV- بطول 6 أصدر INV-001000، ثم بادئة INV-00 وطول 4
403:             // يعيدان الرقم 1000 بصيغة INV-001000). التحقق الحالي يمنع
404:             // تخفيض العداد فقط. بعد تطبيق القيم الجديدة وقبل التدقيق،
405:             // نشيك أن الرقم التالي المُنسَّق غير موجود أصلًا في جدول
406:             // المستند؛ والـ unique index على عمود الرقم هو خط الدفاع
407:             // الأخير وقت التشغيل (موجود على كل أعمدة الأرقام).
408:             $this->assertNoNumberingCollision(array_keys($settings));
409: 
410:             StaffAdministration::audit(request()->user('staff'), 'settings.updated', 'settings', null, array_keys($settings),
411:                 ['settings' => $this->auditableSettings($before)], ['settings' => $this->auditableSettings($after)], $via);
412:             DB::afterCommit(fn () => $this->clearCache());
413: 
414:             // M-2: المزامنة داخل الـ transaction — الـ setval غير transactional،
415:             // ففشل لاحق (rollback) ينتج فجوة فقط، والفجوات مقبولة لهذه الأنواع.
416:             // البديل السابق (afterCommit + warning) كان يترك العداد قديمًا
417:             // فيكرر أرقام مستندات.
418:             if ($movementSequenceTarget !== null) {
419:                 DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
420:             }
421:             foreach ($documentSequenceTargets as $type => $minimum) {
422:                 DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]);
423:             }
424:         }, attempts: 3);
425:     }
