427:     /**
428:      * Atomically return and increment the next document number for the requested type.
429:      *
430:      * @throws JsonException
431:      */
432:     public function generateNextNumber(string $type): string
433:     {
434:         if ($type === 'movement') {
435:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
436:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
437: 
438:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
439:         }
440:         if (isset(self::SEQUENCE_TYPES[$type])) {
441:             $definitions = $this->numberingDefinitions();
442:             $definition = $definitions[$type];
443:             [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
444:             $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;
445: 
446:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
447:         }
448:         $definitions = $this->numberingDefinitions();
449: 
450:         if (! isset($definitions[$type])) {
451:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
452:         }
453: 
454:         $definition = $definitions[$type];
455:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
456: 
457:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
458:             // Counter row is locked and read fresh; prefix and padding are cached in request memory
459:             $nextSetting = Setting::query()
460:                 ->where('key', $definition['next'])
461:                 ->lockForUpdate()
462:                 ->first();
463: 
464:             if ($nextSetting === null) {
465:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
466:             }
467: 
468:             $nextValue = $this->counterValue($nextSetting->value);
469: 
470:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
471:             $nextSetting->value = (string) ($nextValue + 1);
472:             $nextSetting->save();
473: 
474:             return $formatted;
475:         }, attempts: 3);
476:     }
