478:     /**
479:      * Cache numbering prefix and padding per request to reduce query overhead.
480:      *
481:      * @return array{0: string, 1: int}
482:      */
483:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
484:     {
485:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
486:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
487: 
488:             foreach ([$prefixKey, $paddingKey] as $key) {
489:                 if (! $settings->has($key)) {
490:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
491:                 }
492:             }
493: 
494:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
495:         })();
496:     }
