507:     private function comparisonValue(mixed $value, string $type): ?string
508:     {
509:         if ($type === 'float' && $value !== null && is_numeric($value)) {
510:             return (string) BigDecimal::of((string) $value)->strippedOfTrailingZeros();
511:         }
512: 
513:         return $type === 'string' ? (string) ($value ?? '') : $this->serializeValue($value, $type);
514:     }
