524:     /**
525:      * M-4: نوع المستند → [جدول، عمود الرقم] لفحص تصادم الترقيم.
526:      * invoice وpos_invoice بلا جدول مستندات خاص (فواتير الجملة طلبات،
527:      * وفواتير POS بلا عمود رقم مستقل) فيُتجاوزان من الفحص.
528:      *
529:      * @var array<string, array{0: string, 1: string}>
530:      */
531:     private const DOCUMENT_NUMBER_TARGETS = [
532:         'order' => ['orders', 'order_number'],
533:         'purchase_order' => ['purchase_orders', 'po_number'],
534:         'quotation' => ['quotations', 'quotation_number'],
535:         'transfer' => ['stock_transfers', 'transfer_number'],
536:         'stocktake' => ['stocktakes', 'stocktake_number'],
537:         'return' => ['return_requests', 'return_number'],
538:         'purchase_request' => ['purchase_requests', 'request_number'],
539:         'delivery' => ['supplier_deliveries', 'delivery_number'],
540:         'supplier_invoice' => ['supplier_invoices', 'invoice_number'],
541:         'supplier_payment' => ['supplier_payments', 'payment_number'],
542:         'shift' => ['pos_shifts', 'shift_number'],
543:         'expense' => ['expenses', 'expense_number'],
544:         'treasury_transfer' => ['treasury_transfers', 'transfer_number'],
545:         'payment_notice' => ['wholesale_payment_notices', 'notice_number'],
546:         'movement' => ['stock_movements', 'reference_number'],
547:     ];
