549:     /**
550:      * M-4: لكل نوع مستند اتعدّلت بادئته أو طوله أو عداده، تأكد أن الرقم
551:      * التالي المُنسَّق بالصيغة الجديدة غير موجود أصلًا في جدول المستند.
552:      * استعلام exists واحد لكل نوع اتعدّل.
553:      *
554:      * @param  list<string>  $changedKeys
555:      */
556:     private function assertNoNumberingCollision(array $changedKeys): void
557:     {
558:         foreach (self::DOCUMENT_NUMBER_TARGETS as $type => [$table, $column]) {
559:             // مفاتيح الترقيم بنمط ثابت {type}_prefix/_next_number/_padding
560:             // (بما فيه movement، غير الموجود في numberingDefinitions()).
561:             $keys = [$type.'_prefix', $type.'_next_number', $type.'_padding'];
562:             if (array_intersect($keys, $changedKeys) === []) {
563:                 continue;
564:             }
565:             // قراءة طازجة داخل الـ transaction: المفاتيح المتعدّلة اتحفظت
566:             // بالفعل في الحلقة أعلاه، وغيرها بقيمها الحالية.
567:             $rows = Setting::query()->whereIn('key', $keys)->get()->keyBy('key');
568:             if ($rows->count() !== count($keys)) {
569:                 continue;
570:             }
571:             $prefix = (string) $this->castValue($rows[$keys[0]]->value, $rows[$keys[0]]->type);
572:             $next = (int) $this->castValue($rows[$keys[1]]->value, $rows[$keys[1]]->type);
573:             $padding = (int) $this->castValue($rows[$keys[2]]->value, $rows[$keys[2]]->type);
574:             $candidate = $prefix.str_pad((string) $next, $padding, '0', STR_PAD_LEFT);
575:             if (DB::table($table)->where($column, $candidate)->exists()) {
576:                 throw ValidationException::withMessages([$keys[0] => "الرقم التالي المُنسَّق ({$candidate}) صدر من قبل لنوع {$type}؛ غيّر البادئة أو الطول أو ارفع العداد."]);
577:             }
578:         }
579:     }
