614:     private function nextDocumentNumber(string $type): int
615:     {
616:         if (! isset(self::SEQUENCE_TYPES[$type])) {
617:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
618:         }
619:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
620: 
621:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
622:     }
