624:     private function counterValue(mixed $value): int
625:     {
626:         $number = (is_int($value) || is_string($value))
627:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
628:             : false;
629:         if ($number === false) {
630:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
631:         }
632: 
633:         return $number;
634:     }
635: 
636:     private function castValue(?string $value, string $type): mixed
637:     {
638:         if ($value === null) {
639:             return null;
640:         }
641: 
642:         if ($type === 'json') {
643:             try {
644:                 return json_decode($value, true, 512, JSON_THROW_ON_ERROR);
645:             } catch (JsonException) {
646:                 return null;
647:             }
648:         }
649: 
650:         return match ($type) {
651:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
652:             'integer' => (int) $value,
653:             'float' => (float) $value,
654:             default => $value,
655:         };
656:     }
657: 
658:     /** @throws JsonException */
659:     private function serializeValue(mixed $value, string $type): ?string
660:     {
661:         if ($value === null) {
662:             return null;
663:         }
664: 
665:         if ($type === 'json') {
666:             return json_encode($value, JSON_THROW_ON_ERROR);
667:         }
668: 
669:         if ($type === 'boolean') {
670:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
671:         }
672: 
673:         return (string) $value;
674:     }
